TURATH_CHUNK(7,[{"num":1400,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي قُرَادٍ، قَالَ: خَرَجْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْخَلَاءِ، وَكَانَ إِذَا أَرَادَ الْحَاجَةَ أَبْعَدَ."],"takhrij":"صحيح: رواه النسائي الصغرى (16) وابن ماجه (334) كلاهما من طريق يحيى بن سعيد القطان، عن أبي جعفر عمير بن يزيد الخَطْمي، عن عُمارة بن خزيمة والحارث بن فُضيل، عن عبد الرحمن بن أبي قُراد.","grade":"صحيح","chapter_ar":"باب التباعد للبراز في الفضاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (16) and Ibn Mājah (334).","chapter_en":"Going Far Away to Relieve Oneself in an Open Area","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Qurād, may Allah be pleased with him, reported: I went out with the Messenger of Allah ﷺ to relieve himself. Whenever he intended to answer the call of nature, he would go far away."]},"buhuth":{"en":["In Sunan Ibn Mājah, ʿAbd al-Raḥmān ibn Abī Qurād said: “I performed Ḥajj with the Prophet ﷺ; when he went to relieve himself, he went far away.” Al-Aʿẓamī said: Its chain is ṣaḥīḥ. Ibn Khuzaymah (51) also authenticated it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (16)، وابن ماجه (334)."},{"num":1401,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَذْهَبُ لِحَاجَتِهِ إِلَى الْمَغْمَسِ قَالَ نَافِعٌ: نَحْوَ مِيلَيْنِ مِنْ مَكَّةَ."],"takhrij":"صحيح: رواه أبو يعلى (5600)، والطبراني في المعجم الكبير (13638). والأوسط (4903) من طرق، عن سعيد بن أبي مريم، قال أخبرنا نافع بن عمر الجمحي، عن عمرو بن دينار، عن ابن عمر، فذكر مثله. ومن هذا الوجه أخرجه السراج في مسنده (17) وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التباعد للبراز في الفضاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Yaʿlā (5600), al-Ṭabarānī in al-Muʿjam al-Kabīr (12/451), and al-Muʿjam al-Awsaṭ (5/469).","chapter_en":"Going Far Away to Relieve Oneself in an Open Area","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported: The Prophet ﷺ used to go to al-Mughammis to relieve himself. Nāfiʿ said: “It was approximately two miles from Makkah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (5600)، والطبراني في المعجم الكبير (13638)، والأوسط (4903)."},{"num":1402,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ الْبَرَازَ، انْطَلَقَ حَتَّى لا يَرَاهُ أَحَدٌ."],"takhrij":"حسن: رواه أبو داود (2) وابن ماجه (334) كلاهما من طريق إسماعيل بن عبدالملك، عن أبي الزبير، عن جابر بن عبدالله فذكر مثله. واللفظ لأبي داود. ولفظ ابن ماجه: قال: خرجنا مع رسول الله صلى الله عليه وسلم في سفر، وكان رسول الله صلى الله عليه وسلم لا يأتي البراز حتَّى يتغيَّبَ فلا يُرى.","grade":"حسن","chapter_ar":"باب التباعد للبراز في الفضاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (2) and Ibn Mājah (334). The wording is that of Abū Dāwūd.","chapter_en":"Going Far Away to Relieve Oneself in an Open Area","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: When the Prophet ﷺ wanted to defecate, he would go away until no one could see him."]},"buhuth":{"en":["Ibn Mājah’s wording states:","“We went out with the Messenger of Allah ﷺ on a journey, and the Messenger of Allah ﷺ would not go to relieve himself until he had gone out of sight and could not be seen.”","Its chain is ḥasan because of Ismāʿīl ibn ʿAbd al-Malik. Although scholars differed concerning him, his hadith is ḥasan when it has established supporting foundations, and this is one such case. Al-Dārimī (17), al-Bayhaqī (1/93), and others narrated it through this route in a longer form."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2)، وابن ماجه (334). واللفظ لأبي داود."},{"num":1403,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ الْحَاجَةَ تَنَحَّى، وَلَا يَرْفَعُ ثِيَابَهُ حَتَّى يَدْنُوَ مِنَ الْأَرْضِ."],"takhrij":"صحيح: رواه البيهقي (460) عن أبي الحسن علي بن عبدالله الخسروجردي، أنا أبو بكر الإسماعيلي، ثنا عبدالله بن محمد بن مسلم من أصل كتابه، ثنا أحمد بن محمد بن أبي رجاء المعيصي – شيخ جليل – ثنا وكيع، ثنا الأعمش، عن القاسم بن محمد، عن ابن عمر فذكره. وهذا إسناد صحيح.","grade":"صحيح","chapter_ar":"باب كيف التكشف عند الحاجة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bayhaqī (1/96).","chapter_en":"How One Should Uncover Oneself When Relieving Oneself","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":34,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported: When the Messenger of Allah ﷺ intended to relieve himself, he would move aside and would not raise his garment until he had drawn close to the ground."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البيهقي (460)."},{"num":1404,"demo":false,"sanad":"","matn":["عَنْ عَبْدِالرَّحْمَنِ ابْنِ حَسَنَةَ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي يَدِهِ كَهَيْئَةِ الدَّرَقَةِ، قَالَ: فَوَضَعَهَا، ثُمَّ جَلَسَ، فَبَالَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَــــالَ بَعْضُ الْقَوْمِ: انْظُرُوا إِلَيْهِ يَبُولُ كَمَا تَبُولُ الْمَرْأَةُ، قَالَ: فَسَمِعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: وَيْحَكَ، أَمَا عَلِمْتَ مَا أَصَابَ صَاحِبَ بَنِي إِسْرَائِيلَ، كَانُوا إِذَا أَصَابَهُمْ شَيْءٌ مِنْ الْبَوْلِ قَرَضُوهُ بِالْمَقَارِيضِ، فَنَهَاهُمْ، فَعُذِّبَ فِي قَبْرِهِ."],"takhrij":"صحيح: رواه أحمد (17758)، واللفظ له، والنسائي الصغرى (30)، وابن ماجه (346) كلهم من طريق أبي معاوية، عن الأعمش، عن زيد بن وهب، عن عبدالرحمن بن حسنة فذكره.","grade":"صحيح","chapter_ar":"باب البول قاعدًا","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (17758), whose wording is cited here, al-Nasāʾī (30), and Ibn Mājah (346).","chapter_en":"Urinating While Sitting","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":35,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Ḥasanah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ came out to us carrying something resembling a small shield. He placed it down, then sat and urinated toward it. Some of the people said: “Look at him! He urinates as a woman urinates.” The Prophet ﷺ heard him and said: “Woe to you! Do you not know what happened to the man from the Children of Israel? Whenever any urine touched them, they would cut away the affected part with scissors. He prohibited them from doing so, and because of that he was punished in his grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17758)، واللفظ له، والنسائي (30)، وابن ماجه (346)."},{"num":1405,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: مَنْ حَدَّثَكَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَالَ قَائِمًا فَلَا تُصَدِّقْهُ، مَا بَالَ رَسُولُ اللَّهِ قَائِمًا مُنْذُ أُنْزِلَ عَلَيْهِ الْقُرْآنُ."],"takhrij":"صحيح: رواه أحمد (25045)، والحاكم (649)، والبيهقي (491) كلهم من طرقٍ عن سفيان الثوري، عن المقدام بن شريح، عن أبيه، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب البول قاعدًا","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (25045), al-Ḥākim (644), and al-Bayhaqī (1/101).","chapter_en":"Urinating While Sitting","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":35,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, said: “Whoever tells you that the Messenger of Allah ﷺ urinated while standing, do not believe him. The Messenger of Allah ﷺ did not urinate while standing from the time the Qurʾān was revealed to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (25045)، والحاكم (649)، والبيهقي (491)."},{"num":1406,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ قَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَانْتَهَى إِلَى سُبَاطَةِ قَوْمٍ، فَبَالَ قَائِمًا فَتَنَحَّيْتُ، فَقَالَ: ادْنُهْ، فَدَنَوْتُ حَتَّى قُمْتُ عِنْدَ عَقِبَيْهِ، فَتَوَضَّأَ، فَمَسَحَ عَلَى خُفَّيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (224، 225) من طريق شعبة، ومسلم في الطهارة (273) من طريق أبي خثيمة – كلاهما عن الأعمش، عن أبي وائل، عن حذيفة فذكره. واللفظ لمسلم، وأما البخاري فلم يذكر فمسح على خفيه.","grade":"متفق عليه","chapter_ar":"باب جواز البول قائمًا","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (224, 225) and Muslim in al-Ṭahārah (273). The wording is that of Muslim; al-Bukhārī did not mention, “and he wiped over his leather socks.”","chapter_en":"The Permissibility of Urinating While Standing","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":36,"content":{"translation":{"en":["Ḥudhayfah ibn al-Yamān, may Allah be pleased with him, reported: I was with the Prophet ﷺ when he came to a refuse heap belonging to some people and urinated while standing. I moved away, but he said: “Come closer.” So I came close until I stood near his heels. He then performed wuḍūʾ and wiped over his leather socks."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (224، 225)، ومسلم (273). واللفظ لمسلم، وأما البخاري فلم يذكر: «فمسح على خفيه»."},{"num":1407,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَتَى أَحَدُكُمُ الْغَائِطَ فَلَا يَسْتَقْبِل الْقِبْلَةَ وَلَا يُوَلِّهَا ظَهْرَهُ، شَرِّقُوا أَوْ غَرِّبُوا."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (144) ومسلم في الطهارة (264) كلاهما من طريق الزهري، عن عطاء بن يزيد الليثي، عن أبي أيوب الأنصاري. قال أبو أيوب: فقدمنا الشام فوجدنا مراحيض قد بنيت قِبل القبلة، فننحرف عنها، ونستغفر الله.","grade":"متفق عليه","chapter_ar":"باب النهي عن استقبال القبلة بغائط أو بول في الفضاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (144) and Muslim in al-Ṭahārah (264).","chapter_en":"The Prohibition of Facing or Turning One’s Back to the Qiblah While Relieving Oneself in the Open","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":37,"content":{"translation":{"en":["Abū Ayyūb al-Anṣārī, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “When one of you goes to relieve himself, he should neither face the qiblah nor turn his back toward it. Rather, face east or west.”"]},"buhuth":{"en":["Abū Ayyūb, may Allah be pleased with him, said: “We came to al-Shām and found toilets that had been built facing the qiblah, so we would turn away from it and seek Allah’s forgiveness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (144)، ومسلم (264)."},{"num":1408,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا جَلَسَ أَحَدُكُمْ عَلَى حَاجَتِهِ، فَلَا يَسْتَقْبِلِ الْقِبْلَةَ، وَلَا يَسْتَدْبِرْهَا."],"takhrij":"صحيح: رواه مسلم في الطهارة (265) مختصرا هكذا. من طريق سهيل، عن القعقاع بن حكيم، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن استقبال القبلة بغائط أو بول في الفضاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ṭahārah (265), in this abridged wording.","chapter_en":"The Prohibition of Facing or Turning One’s Back to the Qiblah While Relieving Oneself in the Open","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":37,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “When one of you sits to relieve himself, he should neither face the qiblah nor turn his back toward it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (265) مختصرا هكذا."},{"num":1409,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيَّ يَقُولُ: أَنَا أَوَّلُ مَنْ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَبُولَنَّ أَحَدُكُمْ مُسْتَقْبِلَ الْقِبْلَةِ، وَأَنَا أَوَّلُ مَنْ حَدَّثَ النَّاسَ بِذَلِك."],"takhrij":"صحيح: رواه ابن ماجه (317) قال: حدثنا محمد بن رمحٍ المصري، أنا الليث بن سعد، عن يزيد بن أبي حبيب، أنه سمع عبــــــدالله بن الحارث بن جزء يقول، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن استقبال القبلة بغائط أو بول في الفضاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (317).","chapter_en":"The Prohibition of Facing or Turning One’s Back to the Qiblah While Relieving Oneself in the Open","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":37,"content":{"translation":{"en":["ʿAbdullāh ibn al-Ḥārith ibn Jazʾ al-Zubaydī, may Allah be pleased with him, said: “I was the first person to hear the Prophet ﷺ say: ‘None of you should urinate while facing the qiblah.’ And I was the first to narrate this to the people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (317)."},{"num":1410,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّهُ كَانَ يَقُولُ: إِنَّ نَاسًا يَقُولُونَ: إِذَا قَعَدْتَ عَلَى حَاجَتِكَ فَلَا تَسْتَقْبِلِ الْقِبْلَةَ وَلَا بَيْتَ الْمَقْدِسِ، فَقَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: لَقَدِ ارْتَقَيْتُ يَوْمًا عَلَى ظَهْرِ بَيْتٍ لَنَا، فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى لَبِنَتَيْنِ مُسْتَقْبِلًا بَيْتَ الْمَقْدِسِ لِحَاجَتِهِ، وَقَالَ: لَعَلَّكَ مِنَ الَّذِينَ يُصَلُّونَ عَلَى أَوْرَاكِهِمْ؟ فَقُلْتُ: لَا أَدْرِي وَاللَّهِ.","قَالَ مَالِكٌ: يَعْنِي الَّذِي يُصَلِّي وَلَا يَرْتَفِعُ عَنِ الْأَرْضِ، يَسْجُدُ وَهُوَ لَاصِقٌ بِالْأَرْضِ."],"takhrij":"متفق عليه: رواه مالك في القبلة (3) عن يحيى بن سعيد، عن محمد بن يحيى بن حَبّان، عن عمه واسع بن حَبّان، عن عبدالله بن عمر، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب جواز استقبال القبلة واستدبارها عند قضاء الحاجة في البناء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Qiblah (3), al-Bukhārī (145), and Muslim (266).","chapter_en":"The Permissibility of Facing or Turning One’s Back to the Qiblah While Relieving Oneself in a Built Structure","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":38,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, used to say: Some people say: “When you sit to relieve yourself, do not face the qiblah or Bayt al-Maqdis.” ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, said: “One day I climbed onto the roof of one of our houses and saw the Messenger of Allah ﷺ relieving himself while sitting on two bricks, facing Bayt al-Maqdis.” He said: “Perhaps you are among those who pray while resting on their haunches?” I said: “I do not know, by Allah.” Mālik explained that this refers to someone who prays without lifting himself from the ground, prostrating while remaining pressed against it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (3)، والبخاري (145)، ومسلم (266)."},{"num":1411,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِبَوْلٍ، فَرَأَيْتُهُ قَبْلَ أَنْ يُقْبَضَ بِعَامٍ يَسْتَقْبِلُهَا."],"takhrij":"حسن: رواه أبو داود (13) والترمذي (9) وابن ماجه (325) كلهم عن محمد بن بشار، ثنا وهب بن جرير، ثنا أبي، قال: سمعتُ محمد بن إسحاق يحدث عن أبان بن صالح، عن مجاهد، عن جابر بن عبدالله به.","grade":"حسن","chapter_ar":"باب جواز استقبال القبلة واستدبارها عند قضاء الحاجة في البناء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (13), al-Tirmidhī (9), and Ibn Mājah (325).","chapter_en":"The Permissibility of Facing or Turning One’s Back to the Qiblah While Relieving Oneself in a Built Structure","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":38,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: The Messenger of Allah ﷺ prohibited us from facing the qiblah while urinating, but I saw him facing it one year before he passed away."]},"buhuth":{"en":["Its chain is ḥasan because Muḥammad ibn Isḥāq, though known for tadlīs, explicitly stated direct transmission here. Ibn Khuzaymah (58) authenticated it; al-Dāraquṭnī (1/58) and al-Ḥākim (1/154) also narrated it, and al-Ḥākim called it ṣaḥīḥ according to Muslim’s criterion. Al-Tirmidhī called it ḥasan gharīb, mentioned the weaker Ibn Lahīʿah route, and preferred Jābir’s report. The author agreed, noting that Ibn Lahīʿah is weak and that Ibn Isḥāq’s explicit statement of hearing removes the concern of tadlīs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (13)، والترمذي (9)، وابن ماجه (325)."},{"num":1412,"demo":false,"sanad":"","matn":["عَنْ مَرْوَانَ الأَصْفَرِ قَالَ: رَأَيْتُ ابْنَ عُمَرَ أَنَاخَ رَاحِلَتَهُ مُسْتَقْبِلَ الْقِبْلَةِ، ثُمَّ جَلَسَ يَبُولُ إِلَيْهَا، فَقُلْتُ: يَا أَبَا عَبْدِ الرَّحْمَنِ! أَلَيْسَ قَدْ نُهِيَ عَنْ هَذَا؟ قَالَ: بَلَى، إِنَّمَا نُهِيَ عَنْ ذَلِكَ فِي الْفَضَاءِ، فَإِذَا كَانَ بَيْنَكَ وَبَيْنَ الْقِبْلَةِ شَيْءٌ يَسْتُرُكَ، فَلَا بَأْسَ."],"takhrij":"حسن: رواه أبو داود (11) عن محمد بن يحيى بن فارس، ثنا صفوان بن عيسى، عن الحسن بن ذكوان، عن مروان الأصفر فذكره.","grade":"حسن","chapter_ar":"باب جواز استقبال القبلة واستدبارها عند قضاء الحاجة في البناء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (11).","chapter_en":"The Permissibility of Facing or Turning One’s Back to the Qiblah While Relieving Oneself in a Built Structure","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":38,"content":{"translation":{"en":["Marwān al-Aṣfar reported: I saw Ibn ʿUmar, may Allah be pleased with them, make his riding animal kneel facing the qiblah, then sit and urinate toward it. I said: “O Abū ʿAbd al-Raḥmān, was this not prohibited?” He replied: “Yes, but that prohibition applies in the open. If there is something between you and the qiblah that screens you, there is no harm.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (11)."},{"num":1413,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ لَمْ يَسْتَقْبِلِ الْقِبْلَةَ، وَلَمْ يَسْتَدْبِرْهَا فِي الْغَائِطِ كُتِبَ لَهُ حَسَنَةٌ، وَمُحِيَ عَنْهُ سَيِّئَةٌ."],"takhrij":"حسن: رواه الطبراني في الأوسط (1321) قال: حدثنا أحمد، قال: حدثنا أحمد بن حرب الموصلي، قال: حدثنا القاسم بن يزيد الجَرْمي، عن إبراهيم بن طهمان، عن حسين المعلم، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب أجر من لم يستقبل القبلة عند الحاجة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (1343).","chapter_en":"The Reward of One Who Does Not Face the Qiblah While Relieving Himself","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":39,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Whoever neither faces the qiblah nor turns his back toward it while defecating will have a good deed recorded for him and a sin erased from him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (1321)."},{"num":1414,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: يَقُولُونَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْصَى إِلَى عَلِيٍّ لَقَدْ دَعَا بِالطَّسْتِ لِيَبُولَ فِيهَا فَانْخَنَثَتْ نَفْسُهُ . وَمَا أَشْعُرُ فَإِلَى مَنْ أَوْصَى ؟."],"takhrij":"صحيح: رواه النسائي الصغرى (33) عن عمرو بن علي، أخبرنا أزهر، قال: أخبرنا ابن عون، عن إبراهيم، عن الأسود، عن عائشة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب في البول في الطست","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (33).","chapter_en":"Urinating Into a Basin","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["ʿĀʾishah, the wife of the Prophet ﷺ, may Allah be pleased with her said: “They say that the Prophet ﷺ made a bequest to ʿAlī! He called for a basin so that he could urinate into it, then his body gave way before I even realized it. So to whom could he have made such a bequest?”"]},"buhuth":{"en":["Al-Nasāʾī said that Azhar is Ibn Saʿd al-Sammān. The basis of the report is found in the two Ṣaḥīḥs without the phrase “so that he could urinate into it”: al-Bukhārī in al-Maghāzī (4459) and al-Waṣāyā (2741), and Muslim in al-Waṣiyyah (1636). The expression “inkhanathat” means that his body weakened, bent, and relaxed at death."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (33)."},{"num":1415,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ يَزِيدَ قَالَ: قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يُنْقَعُ بَوْلٌ فِي طَسْتِ فِي الْبَيْتِ، فَإِنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ بَوْلٌ يُنْقَعُ، وَلَا تَبُولَنَّ فِي مُغْتَسَلِكَ."],"takhrij":"حسن: رواه الطبراني في الأوسط (2077)، مجمع البحرين (365)، عن أحمد (هو: ابن زهير التستري)، ثنا إسحاق بن إبراهيم البغوي، ثنا يحيى بن عباد أبو عباد، ثنا يونس بن أبي إسحاق، عن بكر بن ماعز، قال: سمعت عبد الله بن يزيد يحدّث فذكره.","grade":"حسن","chapter_ar":"باب في البول في الطست","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (365).","chapter_en":"Urinating Into a Basin","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["ʿAbdullāh ibn Yazīd, may Allah be pleased with him, reported that the Prophet ﷺ said: “Urine should not be left standing in a basin in the house, for the angels do not enter a house in which urine has been left standing. And do not urinate in the place where you bathe.”"]},"buhuth":{"en":["Its chain is ḥasan because of Bakr ibn Māʿiz al-Kūfī, whom Ibn Maʿīn declared trustworthy and Ibn Ḥibbān included among the trustworthy narrators. Al-Haythamī likewise called al-Ṭabarānī’s chain ḥasan. ʿAbdullāh ibn Yazīd is the Anṣārī al-Khaṭmī Companion; both he and his father had companionship, and he witnessed the Pledge of al-Riḍwān while young. The prohibition refers to leaving urine standing in the house for a period without pouring it away.","The author also examined the report that the Prophet ﷺ kept a vessel beneath his bed for urination at night. He noted criticism of Ḥukaymah bint Umaymah as an unknown narrator despite Ibn Ḥibbān listing her among the trustworthy. He judged the added story that a servant drank the urine to be anomalous or objectionable, citing inconsistency in the servant’s identity and concerns about Ḥajjāj ibn Muḥammad’s later memory. He likewise rejected the report about Umm Ayman drinking urine because of a weak narrator, discontinuity, and inconsistency in its chain."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط، كما في مجمع البحرين (365)."},{"num":1416,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ سَرْجِسَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَبُولَنَّ أَحَدُكُمْ فِي الْجُحْرِ، وَإِذَا نِمْتُمْ فَأَطْفِئُوا السِّرَاجَ، فَإِنَّ الْفَأْرَةَ تَأْخُذُ الْفَتِيلَةَ، فَتَحْرِقُ أَهْلَ الْبَيْتِ، وَأَوْكُوا الْأَسْقِيَةَ، وَخَمِّرُوا الشَّرَابَ، وَغَلِّقُوا الْأَبْوَابَ بِاللَّيْلِ.","قَالُوا لِقَتَادَةَ: مَا يُكْرَهُ مِنَ الْبَوْلِ فِي الْجُحْرِ؟ قَالَ: يُقَالُ إِنَّهَا مَسَاكِنُ الْجِنِّ."],"takhrij":"صحيح: رواه أحمد (20775)، والحاكم (671) كلاهما من طريق معاذ بن هشام، قال: حدثنا أبي عن قتادة، عن عبد الله بن سرجس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن البول في الجحر","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (20775) and al-Ḥākim (666).","chapter_en":"The Prohibition of Urinating Into a Hole","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["ʿAbdullāh ibn Sarjis, may Allah be pleased with him, reported that the Prophet ﷺ said: “None of you should urinate into a hole. When you go to sleep, extinguish the lamp, for a mouse may take the wick and burn the people of the house. Tie the mouths of the waterskins, cover the drink, and close the doors at night.” Qatādah was asked:","“Why is urinating into a hole disliked?” He replied: “It is said that such holes are dwellings of the jinn.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20775)، والحاكم (671)."},{"num":1417,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ الَّذِي لَا يَجْرِي، ثُمَّ يَغْتَسِلُ فِيهِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (239) ومسلم في الطهارة (282) كلاهما من طرق، عن أبي هريرة. وفي رواية عند مسلم: لا تَبُل في الماء الدائم الذي لا يجري ثم تغتسل منه. وزاد أبو داود (70): ولا تغتسل فيه من الجنابة.","grade":"متفق عليه","chapter_ar":"باب المواضع التي ينهى عن البول والبراز فيها","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (239) and Muslim in al-Ṭahārah (282).","chapter_en":"Places in Which Urinating and Defecating Are Prohibited","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that he heard the Messenger of Allah ﷺ say: “None of you should urinate in standing water that does not flow and then bathe in it.”"]},"buhuth":{"en":["In another narration of Muslim:","“Do not urinate in standing water that does not flow and then bathe from it.”","Abū Dāwūd (70) added:","“And do not perform ghusl from janābah in it.”","The expression “standing water” means stagnant water, as stated in the narration of al-Nasāʾī (1/49)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (239)، ومسلم (282)."},{"num":1418,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَغْتَسِلْ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ وَهُوَ جُنُبٌ، فَقَالَ: كَيْفَ يَفْعَلُ يَا أَبَا هُرَيْرَةَ؟ قَالَ: يَتَنَاوَلُهُ تَنَاوُلًا."],"takhrij":"صحيح: رواه مسلم في الطهارة (283) وابن ماجه (605) والبيهقي (1127) و شرح معاني الآثار (17) وابن الجارود في المنتقى (63) كلهم من طريق ابن وهب، عن عمرو بن الحارث، عن بكير بن الأشجّ، أنَّ أبا السائب مولى هشام بن زُهرة حدَّثه، أنَّه سمع أبا هريرة يقول ... فذكر مثله.","grade":"صحيح","chapter_ar":"باب المواضع التي ينهى عن البول والبراز فيها","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (283).","chapter_en":"Places in Which Urinating and Defecating Are Prohibited","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “None of you should bathe in standing water while in a state of janābah.” They asked: “How should he do it, O Abū Hurayrah?” He replied: “He should scoop water from it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (283)."},{"num":1419,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اتَّقُوا اللَّعَّانَيْنِ، قَالُوا: وَمَا اللَّعَّانَانِ يَا رَسُولَ اللَّهِ؟ قَالَ: الَّذِي يَتَخَلَّى فِي طَرِيقِ النَّاسِ، أَوْ فِي ظِلِّهِمْ."],"takhrij":"صحيح: أخرجه مسلم في الطهارة (269) وأحمد (8853) وأبو داود (25) وصححه ابن خزيمة (67) كلهم من طريق إسماعيل بن جعفر، أخبرني العلاء، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب المواضع التي ينهى عن البول والبراز فيها","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ṭahārah (269).","chapter_en":"Places in Which Urinating and Defecating Are Prohibited","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Beware of the two acts that bring curses.” It was asked: “What are the two acts that bring curses, O Messenger of Allah?” He said: “One who relieves himself in the people’s roadway or in their shade.”"]},"buhuth":{"en":["Al-Khaṭṭābī explained that “the two acts that bring curses” means two acts that cause people to curse their perpetrator. The “shade” here means a shaded place people use for resting or lodging, not every patch of shade, for the Prophet ﷺ relieved himself beneath a palm enclosure that necessarily had shade. This report of Abū Hurayrah has supporting reports from Ibn ʿAbbās, Muʿādh ibn Jabal, Jābir, Ibn ʿUmar, Abū Dharr, and others, but none of those supporting reports is authentic."]}},"tuhfa":{},"full":1,"dr":1,"rep":[14762],"tks":"صحيح: رواه مسلم (269)."},{"num":1420,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ نَهَى أَنْ يُبَالَ فِي الْمَاءِ الرَّاكِدِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (281) وأحمد (14778) والبيهقي (471) كلهم من طريق الليث، عن أبي الزبير، عن جابر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب المواضع التي ينهى عن البول والبراز فيها","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (281).","chapter_en":"Places in Which Urinating and Defecating Are Prohibited","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, reported that the Messenger of Allah ﷺ prohibited urinating in stagnant water."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (281)."},{"num":1421,"demo":false,"sanad":"","matn":["عَنْ حُمَيْدٍ الْحِمْيَرِيِّ وَهُوَ ابْنُ عَبْدِ الرَّحْمَنِ قَالَ: لَقِيتُ رَجُلًا صَحِبَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا صَحِبَهُ أَبُو هُرَيْرَةَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَمْتَشِطَ أَحَدُنَا كُلَّ يَوْمٍ أَوْ يَبُولَ فِي مُغْتَسَلِهِ."],"takhrij":"صحيح: رواه أبو داود (28) واللفظ له، والنسائي (238)، وأحمد (17011) كلهم من طريق داود بن عبد الله الأودي، عن حميد الحميري فذكره.","grade":"صحيح","chapter_ar":"باب المواضع التي ينهى عن البول والبراز فيها","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (28), whose wording is cited here, al-Nasāʾī (238), and Aḥmad (17011).","chapter_en":"Places in Which Urinating and Defecating Are Prohibited","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["Ḥumayd al-Ḥimyarī, the son of ʿAbd al-Raḥmān, reported: I met a man who had accompanied the Prophet ﷺ as Abū Hurayrah, may Allah be pleased with him, had accompanied him. He said: “The Messenger of Allah ﷺ prohibited one of us from combing his hair every day and from urinating in the place where he bathes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (28)، واللفظ له، والنسائي (238)، وأحمد (17011)."},{"num":1422,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَانْطَلِقْ إِلَى الشَّجَرَتَيْنِ، فَاقْطَعْ مِنْ كُلِّ وَاحِدَةٍ مِنْهُمَا غُصْنًا، فَأَقْبِلْ بِهِمَا حَتَّى إِذَا قُمْتَ مَقَامِى، فَأَرْسِلْ غُصْنًا عَنْ يَمِينِكَ وَغُصْنًا عَنْ يَسَارِكَ.","قَالَ جَابِرٌ: فَقُلْتُ: قَدْ فَعَلْتُ يَا رَسُولَ اللَّهِ فَعَمَّ ذَاكَ؟ قَالَ: إِنِّى مَرَرْتُ بِقَبْرَيْنِ يُعَذَّبَانِ فَأَحْبَبْتُ بِشَفَاعَتِى أَنْ يُرَفَّهَ عَنْهُمَا مَا دَامَ الْغُصْنَانِ رَطْبَيْنِ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (3012) من طرق عن حاتم بن إسماعيل، عن يعقوب بن مجاهد أبي حزْرة، عن عبادة بن الوليد بن عبادة بن الصامت، عن جابر في حديث طويل، وهو مذكور في دلائل النبوة.","grade":"صحيح","chapter_ar":"باب في نجاسة البول ووجوب الاستبراء منه","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Zuhd wa-l-Raqāʾiq (3012).","chapter_en":"The Impurity of Urine and the Obligation to Guard Oneself From It","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":43,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “Go to the two trees, cut a branch from each of them, then bring them to me. When you reach the place where I stood, place one branch on your right and one on your left.” Jābir said: I asked: “I have done it, O Messenger of Allah. Why did you command this?”","He said: “I passed by two graves whose occupants are being punished, and I wished, through my intercession, that their punishment might be lightened for as long as the two branches remain fresh.”"]},"buhuth":{"en":["The word “yuraffah” means “to be lightened.” This report itself does not state the cause of the punishment; the following reports explain that it concerned urine."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (3012)."},{"num":1423,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: مَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرَيْنِ، فَقَالَ: أَمَا إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ، أَمَّا أَحَدُهُمَا فَكَانَ يَمْشِي بِالنَّمِيمَةِ، وَأَمَّا الآخَرُ فَكَانَ لَا يَسْتَتِرُ مِنْ بَوْلِهِ، قَالَ: فَدَعَا بِعَسِيبٍ رَطْبٍ، فَشَقَّهُ بِاثْنَيْنِ، ثُمَّ غَرَسَ عَلَى هَذَا وَاحِدًا، وَعَلَى هَذَا وَاحِدًا، ثُمَّ قَالَ: لَعَلَّهُ أَنْ يُخَفَّفُ عَنْهُمَا مَا لَمْ يَيْبَسَا.","وَفِي رِوَايَةِ: وَكَانَ الآخَرُ لَا يَسْتَنْزِهُ عَنِ الْبَوْلِ، أَوْ مِنَ الْبَوْلِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (218) وفي الجنائر (1361) ومسلم في الطهارة (292) كلاهما من طريق الأعمش، قال: سمعت مجاهداً يحدِّث عن طاوس، عن ابن عباس... فذكر الحديث. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب في نجاسة البول ووجوب الاستبراء منه","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (218) and al-Janāʾiz (1361), and Muslim in al-Ṭahārah (292). The wording is that of Muslim.","chapter_en":"The Impurity of Urine and the Obligation to Guard Oneself From It","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":43,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: The Messenger of Allah ﷺ passed by two graves and said: “Indeed, they are being punished, and they are not being punished for something regarded as great. As for one of them, he used to go about spreading malicious gossip; and as for the other, he did not protect himself from his urine.” He then called for a fresh palm branch, split it into two pieces, placed one upon each grave, and said: “Perhaps their punishment will be lightened so long as these two do not dry out.”","In another narration: “The other one did not keep himself clean from urine,” or: “from his urine.”"]},"buhuth":{"en":["Al-Bukhārī’s wording also mentions the fresh palm branch and the Companions asking why it was done, to which the Prophet ﷺ replied that perhaps the punishment would be lightened while the branches remained fresh. Al-Khaṭṭābī and others objected to treating this as a general practice for graves. Ibn Bāz explained that the Prophet ﷺ did it only for two specific graves whose punishment had been disclosed to him, and the senior Companions did not practice it generally. The author also mentioned Buraydah’s request for two branches to be placed in his grave and Ibn ʿUmar’s objection to a covering placed over ʿAbd al-Raḥmān ibn Abī Bakr’s grave, concluding from al-Bukhārī’s arrangement that the incident was specific.","As for the report, “Most of the punishment of the grave is because of urine, so keep yourselves clean from urine,” transmitted by al-Dāraquṭnī through Isrāʾīl from Abū Yaḥyā al-Qattāt from Mujāhid from Ibn ʿAbbās, the author judged it objectionable. He cited Aḥmad’s criticism of the very objectionable reports transmitted from Abū Yaḥyā and noted that the defect may come from both Abū Yaḥyā and Isrāʾīl because both were described as having poor retention and confusion."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3848,13602],"tks":"متفق عليه: رواه البخاري (218)، وفي الجنائز bukhari(1361)، ومسلم (292)، واللفظ لمسلم."},{"num":1424,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَكْثَرُ عَذَابِ الْقَبْرِ مِنَ الْبَوْلِ."],"takhrij":"صحيح: رواه ابن ماجه (348) عن أبي بكر بن أبي شيبة – وهو في مصنفه (1306) قال: حدثنا عفان، قال: حدثنا أبو عوانة، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكر الحديث. ورواه الدارقطني (365) وقال: صحيح، والحاكم (658) وقال: صحيح على شرط الشيخين ولا أعرف له علة،. وأورده البوصيري في زوائد ابن ماجه وقال: هذا إسناد صحيح رجاله عن آخرهم محتج بهم في الصحيحين وحكى الترمذي في العلل عن البخاري أنه قال: إنه حديث صحيح. وأما أبو حاتم فقال: حديث باطل يعني مرفوعا، العلل (1/366) قلت: هذا مثال لاختلاف أنظار العلماء.","grade":"صحيح","chapter_ar":"باب في نجاسة البول ووجوب الاستبراء منه","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (348) from Abū Bakr ibn Abī Shaybah, and it is also found in his Muṣannaf (1/122).","chapter_en":"The Impurity of Urine and the Obligation to Guard Oneself From It","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":43,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Most of the punishment of the grave is because of urine.”"]}},"tuhfa":{},"full":1,"rep":[3852],"tks":"صحيح: رواه ابن ماجه (348)، عن أبي بكر بن أبي شيبة، وهو في مصنفه (1/122)."},{"num":1425,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كُنَّا نَمْشِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَرَرْنَا عَلَى قَبْرَيْنِ، فَقَامَ، فَقُمْنَا مَعَهُ، فَجَعَلَ لَوْنُهُ يَتَغَيَّرُ حَتَّى رَعَدَ كُمُّ قَمِيصِهِ، فَقُلْنَا: مَا لَكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: مَا تَسْمَعُونَ مَا أَسْمَعُ؟ قُلْنَا: وَمَا ذَاكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: هَذَانِ رَجُلانِ يُعَذَّبَانِ فِي قُبُورِهِمَا عَذَابًا شَدِيدًا فِي ذَنْبٍ هَيِّنٍ، قُلْنَا: مِمَّ ذَلِكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: كَانَ أَحَدُهُمَا لا يَسْتَنْزِهُ مِنَ الْبَوْلِ، وَكَانَ الآخَرُ يُؤْذِي النَّاسَ بِلِسَانِهِ، وَيَمْشِي بَيْنَهُمْ بِالنَّمِيمَةِ، فَدَعَا بِجَرِيدَتَيْنِ مِنْ جَرَائِدِ النَّخْلِ، فَجَعَلَ فِي كُلِّ قَبْرٍ وَاحِدَةً . قُلْنَا: وَهَلْ يَنْفَعُهُمَا ذَلِكَ يَا رَسُولَ اللَّهِ؟ قَالَ: نَعَمْ، يُخَفِّفُ عَنْهُمَا مَا دَامَا رَطْبَتَيْنِ."],"takhrij":"صحيح: رواه ابن حبان (824) قال: أخبرنا أبو عروبة، قال: حدثنا محمد بن وهب بن أبي كريمة، قال: حدثنا محمد بن سلمة، عن أبي عبد الرحيم، قال: حدثني زيد بن أبي أُنَيْسة، عن المنهال بن عمرو، عن عبدالله بن الحارث، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في نجاسة البول ووجوب الاستبراء منه","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Ḥibbān (824).","chapter_en":"The Impurity of Urine and the Obligation to Guard Oneself From It","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":43,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: We were walking with the Messenger of Allah ﷺ when we passed by two graves. He stopped, and we stopped with him. His complexion began to change until even the sleeve of his shirt trembled. We asked: “What is wrong, O Prophet of Allah?” He said: “Do you not hear what I hear?” We replied: “What is it, O Prophet of Allah?” He said: “These are two men being severely punished in their graves for sins they considered slight.” We asked: “Because of what, O Prophet of Allah?” He said: “One of them did not protect himself from urine, while the other used to harm people with his tongue and spread malicious gossip among them.” He then called for two fresh palm branches and placed one upon each grave. We asked: “Will that benefit them, O Messenger of Allah?” He said: “Yes. Their punishment will be lightened for as long as the two branches remain fresh.”"]},"buhuth":{"en":["Ibn Abī Shaybah (3/376) and Aḥmad (9686) also narrated reports with similar wording."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (824)."},{"num":1426,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ قَالَ: بَيْنَا أَنَا أُمَاشِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ آخِذَ بِيَدِي وَرَجُلٌ عَنْ يَسَارِهِ، فَإِذَا نَحْنُ بِقَبْرَيْنِ أَمَامَنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ، وَبَلَى، فَأَيُّكُمْ يَأْتِينِي بِجَرِيدَةٍ؟ فَاسْتَبَقْنَا، فَسَبَقْتُهُ، فَأَتَيْتُهُ بِجَرِيدَةٍ، فَكَسَرَهَا نِصْفَيْنِ، فَأَلْقَى عَلَى ذَا الْقَبْرِ قِطْعَةً، وَعَلَى ذَا الْقَبْرِ قِطْعَةً، وَقَالَ: إِنَّهُ يُهَوَّنُ عَلَيْهِمَا مَا كَانَتَا رَطْبَتَيْنِ وَمَا يُعَذَّبَانِ إِلَّا فِي الْبَوْلِ وَالْغِيبَةِ."],"takhrij":"حسن: رواه أحمد (20373) عن أبي سعيد مولى بني هاشم، والبزَّار (3636)، من طريق مسلم بن إبراهيم، كلاهما –أعني أبا سعيد ومسلم بن إبراهيم– عن الأسود بن شيبان، عن بحر بن مَرَّار، عن عبد الرحمن بن أبي بكرة، عن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب في نجاسة البول ووجوب الاستبراء منه","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (20373) and al-Bazzār (3636).","chapter_en":"The Impurity of Urine and the Obligation to Guard Oneself From It","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":43,"content":{"translation":{"en":["Abū Bakrah, may Allah be pleased with him, reported: While I was walking with the Messenger of Allah ﷺ, with him holding my hand and another man walking on his left, we came upon two graves. The Messenger of Allah ﷺ said: “They are certainly being punished, and they are not being punished for something they considered great—yet indeed it is serious. Which of you will bring me a fresh palm branch?” We raced to bring one, and I reached it first. I brought him a branch, and he broke it into two halves, placing one piece upon each grave. He said: “Their punishment will be eased for as long as these two pieces remain fresh. They are being punished only because of urine and backbiting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20373)، والبزار (3636)."},{"num":1427,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصَبِيٍّ فَبَالَ عَلَى ثَوْبِهِ، فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَاءٍ فَأَتْبَعَهُ إِيَّاهُ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (109) عن هشام بن عروة، عن أبيه، عن عائشة، فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب حكم بول الطفل الرضيع وكيفية غسله","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Ṭahārah (109), al-Bukhārī (222), and Muslim (286).","chapter_en":"The Ruling on the Urine of a Nursing Infant and How It Is Cleansed","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":44,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: A young boy was brought to the Messenger of Allah ﷺ and urinated on his garment. The Messenger of Allah ﷺ called for water and poured it over the affected area."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (109)، والبخاري (222)، ومسلم (286)."},{"num":1428,"demo":false,"sanad":"","matn":["عَنْ أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ، أَنَّهَا أَتَتْ بِابْنٍ لَهَا صَغِيرٍ لَمْ يَأْكُلِ الطَّعَامَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَجْلَسَهُ فِي حِجْرِهِ، فَبَالَ عَلَى ثَوْبِهِ، فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَاءٍ فَنَضَحَهُ وَلَمْ يَغْسِلْهُ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (110) عن ابن شهاب، عن عبيدالله بن عبدالله بن عُتْبة بن مسعود، عن أم قيس به.","grade":"متفق عليه","chapter_ar":"باب حكم بول الطفل الرضيع وكيفية غسله","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Ṭahārah (110), al-Bukhārī (223), and Muslim (287).","chapter_en":"The Ruling on the Urine of a Nursing Infant and How It Is Cleansed","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":44,"content":{"translation":{"en":["Umm Qays bint Miḥṣan, may Allah be pleased with her, brought her young son, who had not yet begun eating solid food, to the Messenger of Allah ﷺ. He placed the child in his lap, and the boy urinated on his garment. The Messenger of Allah ﷺ called for water and sprinkled it over the affected area without washing it thoroughly."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (110)، والبخاري (223)، ومسلم (287)."},{"num":1429,"demo":false,"sanad":"","matn":["عَنْ لُبَابَةَ بِنْتِ الْحَارِثِ قَالَتْ: كَانَ الْحُسَيْنُ بْنُ عَلِيٍّ فِي حِجْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَالَ عَلَيْهِ، فَقُلْتُ: الْبَسْ ثَوْبًا وَأَعْطِنِي إِزَارَكَ حَتَّى أَغْسِلَهُ، قَالَ: إِنَّمَا يُغْسَلُ مِنْ بَوْلِ الْأُنْثَى، وَيُنْضَحُ مِنْ بَوْلِ الذَّكَرِ."],"takhrij":"حسن: رواه أبو داود (375) واللفظ له، وابن ماجه (522) كلاهما من طريق أبي الأحوص، عن سماك بن حرب، عن قابوس بن أبي المخارق، عن لُبابة بنت الحارث.","grade":"حسن","chapter_ar":"باب حكم بول الطفل الرضيع وكيفية غسله","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (375), whose wording is cited here, Ibn Mājah (522).","chapter_en":"The Ruling on the Urine of a Nursing Infant and How It Is Cleansed","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":44,"content":{"translation":{"en":["Lubābah bint al-Ḥārith, may Allah be pleased with her, reported: Al-Ḥusayn ibn ʿAlī, may Allah be pleased with them, was in the lap of the Messenger of Allah ﷺ and urinated on him. I said: “Put on another garment and give me your waist-wrapper so that I may wash it.” He said: “The urine of a female infant is washed, while the urine of a male infant is treated by sprinkling water over it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (375)، واللفظ له، وابن ماجه (522)."},{"num":1430,"demo":false,"sanad":"","matn":["عَنْ أَبِي السَّمْحِ قَالَ: كُنْتُ أَخْدِمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ إِذَا أَرَادَ أَنْ يَغْتَسِلَ قَالَ: وَلِّنِي قَفَاكَ، فَأُوَلِّيهِ قَفَايَ فَأَسْتُرُهُ بِهِ، فَأُتِيَ بِحَسَنٍ أَوْ حُسَيْنٍ، فَبَالَ عَلَى صَدْرِهِ، فَجِئْتُ أَغْسِلُهُ فَقَالَ: يُغْسَلُ مِنْ بَوْلِ الْجَارِيَةِ، وَيُرَشُّ مِنْ بَوْلِ الْغُلَامِ."],"takhrij":"حسن: رواه أبو داود (376) واللفظ له، والنسائي (304) وابن ماجه (526، 613) كلهم عن مجاهد بن موسى، عن عبد الرحمن بن مهدي، حدثني يحيى بن الوليد، حدثني مُحِلُّ بن خليفة، حدثني أبو السمح، فذكر الحديث.","grade":"حسن","chapter_ar":"باب حكم بول الطفل الرضيع وكيفية غسله","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (376), al-Nasāʾī (304), and Ibn Mājah (526, 613). The wording is that of Abū Dāwūd.","chapter_en":"The Ruling on the Urine of a Nursing Infant and How It Is Cleansed","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":44,"content":{"translation":{"en":["Abū al-Samḥ may Allah be pleased with him reported: I used to serve the Prophet ﷺ. When he intended to bathe, he would say: “Turn your back toward me.” So I would turn my back toward him and screen him. Then al-Ḥasan or al-Ḥusayn, may Allah be pleased with them, was brought and urinated on his chest. I came to wash it, but he said: “The urine of a baby girl is washed, while the urine of a baby boy is treated by sprinkling water over it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (376)، والنسائي (304)، وابن ماجه (526، 613)، واللفظ لأبي داود."},{"num":1431,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ فِي بَوْلِ الْغُلَامِ الرَّضِيعِ: يُنْضَحُ بَوْلُ الْغُلَامِ، وَيُغْسَلُ بَوْلُ الْجَارِيَةِ."],"takhrij":"صحيح: رواه أبو داود (378) واللفظ له، والترمذي (610) وابن ماجه (525) كلهم من طريق مُعاذ بن هشام، حدثني أبي، عن قتادة، عن أبي حرب بن أبي الأسود الدِّيلي، عن أبيه، عن عليّ قال: فذكره.","grade":"صحيح","chapter_ar":"باب حكم بول الطفل الرضيع وكيفية غسله","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (378), al-Tirmidhī (610), and Ibn Mājah (525).","chapter_en":"The Ruling on the Urine of a Nursing Infant and How It Is Cleansed","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":44,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said concerning the urine of a nursing infant boy: “The urine of a baby boy is treated by sprinkling water over it, while the urine of a baby girl is washed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (378)، والترمذي (610)، وابن ماجه (525)."},{"num":1432,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: جَاءَ أَعْرَابِيٌّ فَبَالَ فِي طَائِفَةِ الْمَسْجِدِ فَزَجَرَهُ النَّاسُ، فَنَهَاهَمْ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا قَضَى بَوْلَهُ أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَنُوبٍ مِنْ مَاءٍ، فَأُهْرِيقَ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (221) ومسلم في الطهارة (284) كلاهما من طريق يحيى بن سعيد الأنصاري، أنه سمع أنس بن مالك، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب صب الماء على البول في المسجد","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (221) and Muslim in al-Ṭahārah (284).","chapter_en":"Pouring Water Over Urine in the Mosque","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":45,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: A Bedouin came and urinated in one part of the mosque. The people rebuked him, but the Prophet ﷺ stopped them. When the man had finished urinating, the Prophet ﷺ ordered that a bucket of water be brought and poured over the spot."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (221)، ومسلم (284)."},{"num":1433,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَامَ أَعْرَابِيٌّ فَبَالَ فِي الْمَسْجِدِ فَتَنَاوَلَهُ النَّاسُ، فَقَالَ لَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَعُوهُ وَهَرِيقُوا عَلَى بَوْلِهِ سَجْلًا مِنْ مَاءٍ أَوْ ذَنُوبًا مِنْ مَاءٍ، فَإِنَّمَا بُعِثْتُمْ مُيَسِّرِينَ وَلَمْ تُبْعَثُوا مُعَسِّرِينَ."],"takhrij":"صحيح: رواه البخاري في الوضوء (220) عن أبي اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرنا عبيدالله بن عبدالله بن عتبة بن مسعود، أنَّ أبا هريرة قال.. فذكره.","grade":"صحيح","chapter_ar":"باب صب الماء على البول في المسجد","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (220).","chapter_en":"Pouring Water Over Urine in the Mosque","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":45,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: A Bedouin stood and urinated in the mosque, and the people moved toward him. The Prophet ﷺ said to them: “Leave him, and pour a bucket of water over his urine, for you have been sent to make things easy and have not been sent to make things difficult.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (220)."},{"num":1434,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كَانَتِ الْكِلَابُ تَبُولُ وَتُقْبِلُ وَتُدْبِرُ فِي الْمَسْجِدِ فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يَكُونُوا يَرُشُّونَ شَيْئًا مِنْ ذَلِكَ."],"takhrij":"صحيح: رواه البخاري (174) إلاَّ أنَّه قال: قال أحمد بن شبيب، ثنا أبي، عن يونس، عن ابن شهاب، قال: حدثني حمزة بن عبدالله، عن أبيه.. فذكر الحديث.","grade":"صحيح","chapter_ar":"باب طهارة الأرض بجفافها","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (174).","chapter_en":"The Ground Becoming Pure by Drying","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":46,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported: Dogs used to urinate and come and go through the mosque during the time of the Messenger of Allah ﷺ, and they would not sprinkle water over any of that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (174)."},{"num":1435,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كُنْتُ أَغْسِلُ الْجَنَابَةَ مِنْ ثَوْبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَخْرُجُ إِلَى الصَّلَاةِ وَإِنَّ بُقَعَ الْمَاءِ فِي ثَوْبِهِ.","وَفِي رِوَايَةِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْسِلُ الْمَنِيَّ، ثُمَّ يَخْرُجُ إِلَى الصَّلَاةِ فِي ذَلِكَ الثَّوْبِ، وَأَنَا أَنْظُرُ إِلَى أَثَرِ الْغَسْلِ فِيهِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (229، 230، 231، 232) ومسلم في الطهارة (289) كلاهما من طريق عمرو بن ميمون قال: سألت سليمان بن يسار عن المنيّ يصيب ثوب الرجل أيغسله أم يغسل الثوب؟ فقال: أخبرتني عائشة، فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب غسل المني","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (229, 230, 231, 232) and Muslim (289).","chapter_en":"Washing Semen","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":47,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: I used to wash the traces of janābah from the garment of the Messenger of Allah ﷺ, and he would go out to prayer while the marks of water were still visible on his garment.","In another narration: The Messenger of Allah ﷺ would wash semen from his garment and then go out to pray in that same garment while I could still see the traces of washing upon it."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (229، 230، 231، 232)، ومسلم (289)."},{"num":1436,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كُنْتُ أَفْرُكُ الْمَنِيَّ مِنْ ثَوْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","وَفِي رِوَايَةِ: فِي الْمَنِيِّ قَالَتْ: كُنْتُ أَفْرُكُهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أحمد (26024) عن يزيد , قال: أخبرنا هشام بن حسان , عن أبي معشر، عن الأسود وهمام، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في فرك المني","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ṭahārah (288:106).","chapter_en":"What Has Been Reported Concerning Scraping Semen","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":48,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: I used to scrape semen from the garment of the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (288: 106)."},{"num":1437,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ شِهَابٍ الْخَوْلَانِيِّ قَالَ: كُنْتُ نَازِلًا عَلَى عَائِشَةَ، فَاحْتَلَمْتُ فِي ثَوْبَيَّ، فَغَمَسْتُهُمَا فِي الْمَاءِ، فَرَأَتْنِي جَارِيَةٌ لِعَائِشَةَ فَأَخْبَرَتْهَا، فَبَعَثَتْ إِلَيَّ عَائِشَةُ فَقَالَتْ: مَا حَمَلَكَ عَلَى مَا صَنَعْتَ بِثَوْبَيْكَ؟ قَالَ: قُلْتُ: رَأَيْتُ مَا يَرَى النَّائِمُ فِي مَنَامِهِ، قَالَتْ: هَلْ رَأَيْتَ فِيهِمَا شَيْئًا؟ قُلْتُ: لَا، قَالَتْ: فَلَوْ رَأَيْتَ شَيْئًا غَسَلْتَهُ، لَقَدْ رَأَيْتُنِي وَإِنِّي لَأَحُكُّهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَابِسًا بِظُفُرِي."],"takhrij":"صحيح: رواه مسلم في الطهارة (290) عن أحمد بن جوص الحنفي، حدّثنا أبو الأحوص، عن شبيب بن غرقدة، عن عبدالله بن شهاب الخولاني، أنَّه قال.. فذكر الحديث. وفي رواية عنده muslim(288): أن رجلاً نزل بعائشة فأصبح يغسل ثوبه، فقالت عائشة: إنما كان يجزئك إن رأيته أن تغسل مكانه، فإن لم تر نضحت حوله، ولقد رأيتني أفركه من ثوب رسول الله صلى الله عليه وسلم فركا، فيصلي فيه.","grade":"صحيح","chapter_ar":"باب ما جاء في فرك المني","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ṭahārah (290).","chapter_en":"What Has Been Reported Concerning Scraping Semen","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":48,"content":{"translation":{"en":["ʿAbdullāh ibn Shihāb al-Khawlānī reported: I was staying with ʿĀʾishah, may Allah be pleased with her, and had a wet dream in my garment, so I immersed it in water. A servant-girl of ʿĀʾishah saw me and informed her. ʿĀʾishah then sent for me and said: “What made you do that to your garment?” I replied: “I experienced what a sleeping person experiences in his dream.” She asked: “Did you actually see anything on it?” I said: “No.” She said: “If you had seen something, you would have washed it. I have seen myself scraping it from the garment of the Messenger of Allah ﷺ when it was dry, using my fingernail.”"]},"buhuth":{"en":["In another narration of Muslim (288):","A man stayed with ʿĀʾishah, may Allah be pleased with her, and began washing his garment in the morning. She said:","“If you had seen it, it would have been sufficient for you to wash the affected place. If you did not see it, you could sprinkle water around it. I have certainly seen myself rubbing it from the garment of the Messenger of Allah ﷺ, and he would pray in it.”","Al-Tirmidhī (116) and Ibn Mājah (538) also narrated from Hammām ibn al-Ḥārith that a guest stayed with ʿĀʾishah. She had a yellow blanket provided for him, and he slept in it and had a wet dream. He was embarrassed to send it back with the trace of the emission on it, so he immersed it in water and then sent it. ʿĀʾishah said: “Why did he spoil our garment? It would have been enough for him to rub it with his fingers. I would sometimes rub it from the garment of the Messenger of Allah ﷺ with my fingers.”","Al-Tirmidhī said: “Ḥasan ṣaḥīḥ.” It may be that this guest was ʿAbdullāh ibn Shihāb al-Khawlānī.","There is no contradiction between the report of washing and the report of rubbing. On the view that semen is pure, the two are reconciled by understanding washing as recommended for cleanliness rather than obligatory, since semen is comparable to saliva and mucus, as Ibn ʿAbbās said.","This was the view of al-Shāfiʿī, Aḥmad, and the scholars of hadith.","Al-Bayhaqī said that semen may be washed for cleanliness just as mucus and similar substances are washed from clothing for cleaning rather than because of impurity. See al-Sunan al-Kubrā (2/419).","Those who held that semen is impure understood washing to apply when it is wet and rubbing to apply when it is dry; this is the Ḥanafī position. For more, see Fatḥ al-Bārī (1/333)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (290)."},{"num":1438,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: أَنَّ النَّبِي َّصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي عِنْدَ الْبَيْتِ وَأَبُو جَهْلٍ وَأَصْحَابٌ لَهُ جُلُوسٌ، إِذْ قَالَ بَعْضُهُمْ لِبَعْض، أَيُّكُمْ يَجِيءُ بِسَلَى جَزُورِ بَنِي فُلَانٍ فَيَضَعُهُ عَلَى ظَهْرِ مُحَمَّدٍ إِذَا سَجَدَ؟ فَانْبَعَثَ أَشْقَى الْقَوْمِ فَجَاءَ بِهِ، فَنَظَرَ حَتَّى إِذَا سَجَدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَضَعَهُ عَلَى ظَهْرِهِ بَيْنَ كَتِفَيْهِ وَأَنَا أَنْظُرُ لَا أُغَيَّرُ شَيْئًا لَوْ كَانَ لِي مَنَعَةٌ، قَالَ: فَجَعَلُوا يَضْحَكُونَ وَيُحِيلُ بَعْضُهُمْ عَلَى بَعْضٍ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَاجِدٌ لَا يَرْفَعُ رَأْسَهُ حَتَّى جَاءَتْهُ فَاطِمَةُ، فَطَرَحَتْ عَنْ ظَهْرِهِ، فَرَفَعَ رَأْسَهُ ثُمَّ قَالَ: اللَّهُمَّ عَلَيْكَ بِقُرَيْشٍ ثَلَاثَ مَرَّاتٍ، فَشَقَّ عَلَيْهِمْ إِذْ دَعَا عَلَيْهِمْ قَالَ: وَكَانُوا يَرَوْنَ أَنَّ الدَّعْوَةَ فِي ذَلِكَ الْبَلَدِ مُسْتَجَابَةٌ، ثُمَّ سَمَّى اللَّهُمَّ عَلَيْكَ بِأَبِي جَهْلٍ، وَعَلَيْكَ بِعُتْبَةَ بْنِ رَبِيعَةَ، وَشَيْبَةَ بْنِ رَبِيعَةَ، وَالْوَلِيدِ بْنِ عُتْبَةَ، وَأُمَيَّةَ بْنِ خَلَفٍ، وَعُقْبَةَ بْنِ أَبِي مُعَيْطٍ، وَعَدَّ السَّابِعَ، فَلَمْ يَحْفَظْ، قَالَ: فَوَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ رَأَيْتُ الَّذِينَ عَدَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَرْعَى فِي الْقَلِيبِ قَلِيبِ بَدْرٍ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (240) ومسلم في الجهاد (1794) كلاهما من حديث شعبة قال: سمعت أبا إسحاق يحدث عن عمرو بن ميمون، عن عبدالله بن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا ألقي على ظهر المصلي قذر أو جيفة لم تفسد صلاته","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (240) and Muslim in al-Jihād (1794).","chapter_en":"If Filth or a Carcass Is Placed on the Back of One Who Is Praying, His Prayer Is Not Invalidated","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":49,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported: While the Messenger of Allah ﷺ was praying near the Kaʿbah, Abū Jahl and some of his companions were sitting nearby. Some of them said to one another: “Which of you will bring the afterbirth of the slaughtered camel of such-and-such a clan and place it on Muḥammad’s back when he prostrates?” The most wretched of them went and brought it. He waited until the Prophet ﷺ prostrated, then placed it on his back between his shoulders. I was watching but could do nothing; if only I had possessed the strength to protect him. They began laughing and leaning against one another, while the Messenger of Allah ﷺ remained in prostration and did not raise his head until Fāṭimah, may Allah be pleased with her, came and removed it from his back. The Messenger of Allah ﷺ then raised his head and said three times: “O Allah, deal with Quraysh.” His supplication against them distressed them, and they believed that supplication in that place was answered. Then he named them: “O Allah, deal with Abū Jahl; deal with ʿUtbah ibn Rabīʿah, Shaybah ibn Rabīʿah, al-Walīd ibn ʿUtbah, Umayyah ibn Khalaf, and ʿUqbah ibn Abī Muʿayṭ.” He named a seventh person whom the narrator did not retain. Ibn Masʿūd, may Allah be pleased with him, said: “By the One in Whose Hand is my soul, I later saw those whom the Messenger of Allah ﷺ had named lying dead in the well—the well of Badr.”"]},"buhuth":{"en":["Al-Bukhārī said: “Ibn ʿUmar, if he saw blood on his garment while praying, would remove it and continue his prayer. Ibn al-Musayyib and al-Shaʿbī said: If someone prays while there is blood or janābah on his garment, or facing other than the qiblah, or performs tayammum and then finds water within the prayer time, he does not repeat the prayer.”","By analogy, carrying a child in prayer while the child is wearing a diaper containing urine or feces does not invalidate the prayer so long as nothing escapes from it and none of the impurity reaches the worshipper’s clothing or body; its impurity is then like impurity contained within the body. If the child is not wearing a diaper, it is likely that impurity will reach the worshipper, in which case the prayer is invalid."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (240)، ومسلم (1794)."},{"num":1439,"demo":false,"sanad":"","matn":["عَنْ امْرَأَةٍ مِنْ بَنِي عَبْدِ الْأَشْهَلِ، قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ لَنَا طَرِيقًا إِلَى الْمَسْجِدِ مُنْتِنَةً، فَكَيْفَ نَفْعَلُ إِذَا مُطِرْنَا؟ قَالَ: أَلَيْسَ بَعْدَهَا طَرِيقٌ هِيَ أَطْيَبُ مِنْهَا؟ . قَالَتْ: قُلْتُ: بَلَى، قَالَ: فَهَذِهِ بِهَذِهِ."],"takhrij":"صحيح: رواه أبو داود (384) وابن ماجه (533) كلاهما من طريق عبدالله بن عيسى، عن موسى بن عبدالله بن يزيد، عن امرأة من بني عبد الأشهل، ذكر الحديث.","grade":"صحيح","chapter_ar":"باب في الأذى يصيب الذيل والنعال","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (384) and Ibn Mājah (533).","chapter_en":"Filth That Affects the Hem of Clothing or Footwear","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":50,"content":{"translation":{"en":["A woman from Banū ʿAbd al-Ashhal, may Allah be pleased with her, reported: I said: “O Messenger of Allah, we have a foul road leading to the mosque. What should we do when it rains?” He asked: “Is there not another road after it that is cleaner than it?” She replied: “Yes.” He said: “Then what you pick up from the filthy road will be cleansed by walking on the cleaner one.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (384)، وابن ماجه (533)."},{"num":1440,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: كُنَّا لَا نَتَوَضَّأُ مِنْ مَوْطِئٍ، وَلَا نَكُفُّ شَعْرًا وَلَا ثَوْبًا."],"takhrij":"حسن: رواه أبو داود (204) واللفظ له، ورواه أيضاً ابن ماجه (1041) ولفظه: أُمرنا ألاّ نكف شعراً ولا ثوباً، ولا نتوضأ من موْطأٍ، كلاهما من حديث عبدالله بن إدريس، وقرنه أبو داود بشريك وجرير، كلهم عن الأعمش، عن شقيق أبي وائل، عن عبدالله بن مسعود، فذكر الحديث. وأخرجه الحاكم (610) من طريق عبدالله بن إدريس وأبي بكر بن أبي شيبة – كلاهما عن شريك وجرير به مثله، وقال: صحيح على شرط الشيخين ولم يخرجا ذكر الموطئ، وأخرج أيضاً (1/139) من طريق سفيان، عن الأعمش به ولفظه: كنا نصلي مع النبي صلى الله عليه وسلم فلا نتوضأ من موطئ، وقال: تابعه أبو معاوية وعبدالله بن إدريس، عن الأعمش به وقال: صحيح على شرط الشيخين.","grade":"حسن","chapter_ar":"باب في الأذى يصيب الذيل والنعال","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (204), whose wording is cited here.","chapter_en":"Filth That Affects the Hem of Clothing or Footwear","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":50,"content":{"translation":{"en":["Ibn Masʿūd, may Allah be pleased with him, reported: “We did not renew wuḍūʾ merely because of something we stepped upon, and we did not hold back our hair or clothing.”"]},"buhuth":{"en":["Ibn Mājah (1041) narrated:","“We were commanded not to hold back our hair or clothing and not to renew wuḍūʾ merely because of something we stepped upon.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (204)، واللفظ له."},{"num":1441,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: بَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِأَصْحَابِهِ إِذْ خَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عَنْ يَسَارِهِ، فَلَمَّا رَأَى ذَلِكَ الْقَوْمُ أَلْقَوْا نِعَالَهُمْ، فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ قَالَ: مَا حَمَلَكُمْ عَلَى إِلْقَاءِ نِعَالِكُمْ؟ قَالُوا: رَأَيْنَاكَ أَلْقَيْتَ نَعْلَيْكَ فَأَلْقَيْنَا نِعَالَنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ جِبْرِيلَ عَلَيْهِ السلام أَتَانِي فَأَخْبَرَنِي أَنَّ فِيهِمَا قَذَرًا أَوْ قَالَ: أَذًى، وَقَالَ: إِذَا جَاءَ أَحَدُكُمْ إِلَى الْمَسْجِدِ فَلْيَنْظُرْ، فَإِنْ رَأَى فِي نَعْلَيْهِ قَذَرًا أَوْ أَذًى فَلْيَمْسَحْهُ وَلْيُصَلِّ فِيهِمَا."],"takhrij":"صحيح: رواه أبو داود (650) عن موسى بن إسماعيل، حدثنا حماد، عن أبي نعامة السعدي، عن أبي نضرة، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب في الأذى يصيب الذيل والنعال","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (650), Ibn Khuzaymah (1017), and al-Ḥākim (1/260).","chapter_en":"Filth That Affects the Hem of Clothing or Footwear","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":50,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, reported: While the Messenger of Allah ﷺ was praying with his Companions, he removed his sandals and placed them to his left. When the people saw this, they removed their sandals as well. After the Messenger of Allah ﷺ completed his prayer, he asked: “What caused you to remove your sandals?” They replied: “We saw you remove your sandals, so we removed ours.” The Messenger of Allah ﷺ said: “Jibrīl came to me and informed me that there was filth in them,” or he said: “something harmful.” He then said: “When one of you comes to the mosque, let him inspect his sandals. If he sees filth or impurity on them, let him wipe it away and then pray in them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (650)، وابن خزيمة (1017)، والحاكم (1/260)."},{"num":1442,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَامِلَ الْحُسَيْنِ بْنِ عَلِيٍّ عَلَى عَاتِقِهِ وَلُعَابُهُ يَسِيلُ عَلَيْهِ."],"takhrij":"صحيح: رواه ابن ماجه (658) قال: حدثنا علي بن محمد، ثنا وكيع، عن حماد بن سلمة، عن محمد بن زياد، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب اللعاب يصيب الثوب","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (658).","chapter_en":"Saliva Getting Onto Clothing","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":51,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: I saw the Prophet ﷺ carrying al-Ḥasan ibn ʿAlī, may Allah be pleased with them, on his shoulder while the child’s saliva was running onto him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (658)."},{"num":1443,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَجُلًا مَرَّ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبُولُ، فَسَلَّمَ، فَلَمْ يَرُدَّ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الحيض (370) من طريق سفيان، عن الضحاك بن عثمان، عن نافع، عن ابن عمر فذكره، وهو حديث مختصر وسيأتي في التيمم أنه تيمم ورد عليه.","grade":"صحيح","chapter_ar":"باب كراهية السلام على من يبول","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (370).","chapter_en":"The Dislike of Greeting Someone While He Is Urinating","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":52,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported: A man passed by while the Messenger of Allah ﷺ was urinating and greeted him with salām, but he did not return the greeting."]}},"tuhfa":{},"full":1,"rep":[1720,14246],"tks":"صحيح: رواه مسلم (370)."},{"num":1444,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَجُلًا مَرَّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَبُولُ، فَسَلَّمَ عَلَيْهِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا رَأَيْتَنِي عَلَى مِثْلِ هَذِهِ الْحَالَةِ فَلَا تُسَلِّمْ عَلَيَّ، فَإِنَّكَ إِنْ فَعَلْتَ ذَلِكَ لَمْ أَرُدَّ عَلَيْكَ."],"takhrij":"حسن: رواه ابن ماجه (352) قال: حدثنا سويد بن سعيد، ثنا عيسى بن يونس، عن هاشم بن البريد، عن عبدالله بن محمد بن عقيل، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب كراهية السلام على من يبول","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (352).","chapter_en":"The Dislike of Greeting Someone While He Is Urinating","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":52,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: A man passed by the Prophet ﷺ while he was urinating and greeted him. The Messenger of Allah ﷺ said to him: “If you see me in a condition like this, do not greet me. If you do so, I will not return your greeting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (352)."},{"num":1445,"demo":false,"sanad":"","matn":["عَنِ الْمُهَاجِرِ بْنِ قُنْفُذٍ، أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيْهِ حَتَّى تَوَضَّأَ، ثُمَّ اعْتَذَرَ إِلَيْهِ فَقَالَ: إِنِّي كَرِهْتُ أَنْ أَذْكُرَ اللَّهَ عَزَّ وَجَلَّ إِلا عَلَى طُهْرٍ أَوْ قَالَ: عَلَى طَهَارَةٍ."],"takhrij":"صحيح: رواه أبو داود (17)، والنسائي (38)، وابن ماجه (350)، وصحّحه ابن خزيمة (206)، وابن حبان (803)، والحاكم (596) كلهم من طريق سعيد بن أبي عروبة، عن قتادة، عن الحسن، عن حضين بن المنذر، عن المهاجر بن قُنفذ قال: فذكره.","grade":"صحيح","chapter_ar":"باب كراهية السلام على من يبول","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (17), al-Nasāʾī (38), and Ibn Mājah (350), and authenticated by Ibn Khuzaymah (206), Ibn Ḥibbān (803), and al-Ḥākim (592).","chapter_en":"The Dislike of Greeting Someone While He Is Urinating","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":52,"content":{"translation":{"en":["Al-Muhājir ibn Qunfudh, may Allah be pleased with him, reported: He came to the Prophet ﷺ while he was urinating and greeted him, but the Prophet ﷺ did not return his greeting until he had performed wuḍūʾ. He then apologized and said: “I disliked to mention Allah, Mighty and Majestic, except while in a state of purity.”"]},"buhuth":{"en":["The wording is that of Abū Dāwūd and al-Nasāʾī. In other versions it states: “I came to the Prophet ﷺ while he was performing wuḍūʾ and greeted him, but he did not return my greeting. When he finished his wuḍūʾ, he said: Nothing prevented me from returning your greeting except that I was without wuḍūʾ.”","It appears that this wording is abridged and that the phrase “while he was urinating” was omitted from it.","Its chain is ṣaḥīḥ. Saʿīd ibn Abī ʿArūbah was trustworthy and a ḥāfiẓ, though he became confused late in life; ʿAbd al-Aʿlā ibn ʿAbd al-Aʿlā narrated it from him before that change, as indicated in some sources. Al-Ḥasan is the well-known al-Baṣrī, though he practiced tadlīs from the Companions; Ḥuḍayn ibn al-Mundhir ibn al-Ḥārith al-Raqāshī was among the trustworthy Successors, so it is most likely that al-Ḥasan heard it from him.","The hadith indicates that remembering Allah while in a state of purification is better; it does not mean that remembrance without purification was disliked. It is authentically established that the Prophet ﷺ remembered Allah in all of his circumstances."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1678,10797],"tks":"صحيح: رواه أبو داود (17)، والنسائي (38)، وابن ماجه (350)، وصححه ابن خزيمة (206)، وابن حبان (803)، والحاكم (596)."},{"num":1446,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَجُلًا مَرَّ بِرَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُهْرِيقُ الْمَاءَ فَسَلَّمَ عَلَيْهِ الرَّجُلُ فَرَدَّ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: إِذَا رَأَيْتَنِي هَكَذَا فَلَا تُسَلِّمْ عَلَيَّ فَإِنَّكَ إِنْ تَفْعَلْ لَا أَرُدُّ عَلَيْكَ السَّلَامَ."],"takhrij":"حسن: رواه البزار (5984)، وابن الجارود في المنتقى (37) كلاهما من طريق سعيد بن سلمة، حدثنا أبو بكر،، هو ابن عمر بن عبد الرحمن بن عبدالله بن عمر بن الخطاب،، عن نافع، عن ابن عمر قال: فذكره..","grade":"حسن","chapter_ar":"باب كراهية السلام على من يبول","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār (5984) and Ibn al-Jārūd in al-Muntaqā (37).","chapter_en":"The Dislike of Greeting Someone While He Is Urinating","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":52,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported: A man passed by the Messenger of Allah ﷺ while he was urinating and greeted him. The Messenger of Allah ﷺ returned his greeting, then said: “If you see me in this condition, do not greet me; for if you do so, I will not return the greeting to you.”"]},"buhuth":{"en":["ʿAbd al-Ḥaqq al-Ishbīlī said regarding this Abū Bakr: “As far as I know, he is Ibn ʿUmar ibn ʿAbd al-Raḥmān ibn ʿAbd Allāh ibn ʿUmar. Mālik and others narrated from him, and there is no problem with him.” He then said: “But Muslim’s hadith is sounder because it is through al-Ḍaḥḥāk ibn ʿUthmān, from Nāfiʿ, from Ibn ʿUmar, and al-Ḍaḥḥāk is more reliable than Abū Bakr. Perhaps this occurred on two separate occasions.” See al-Aḥkām al-Wusṭā (1/131).","Al-Aʿẓamī said: This identification is explicitly stated in Musnad al-Sarrāj (21), and al-Zaylaʿī also mentioned it.","Its chain is ḥasan because of Saʿīd ibn Salamah, namely Ibn Abī al-Ḥusām al-ʿAdawī, their client. Scholars differed over him: al-Nasāʾī weakened him, while others considered him passable. He has the hadith of Umm Zarʿ in Ṣaḥīḥ Muslim; al-Bukhārī cited him in support and narrated one hadith from him.","The two reports can be reconciled by understanding that on one occasion the Prophet ﷺ returned the greeting and on another he did not, while in both situations he instructed that he should not be greeted in that state; if someone did so thereafter, he would not return the greeting."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (5984)، وابن الجارود في المنتقى (37)."},{"num":1447,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ قَالَ: سَأَلْتُ رَسُولَ اللَّه ِصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ الرَّجُلِ يُصِيبُ مِنَ الْمَرْأَةِ، ثُمَّ يُكْسِلُ؟ فَقَالَ: يَغْسِلُ مَا أَصَابَهُ مِنَ الْمَرْأَةِ، ثُمَّ يَتَوَضَّأُ، وَيُصَلِّي."],"takhrij":"متفق عليه: رواه البخاري في الغسل (293) ومسلم في الحيض (346) واللفظ له، كلاهما من حديث هشام بن عروة، عن أبيه، عن أبي أيوب، عن أُبَي بن كعب، فذكر الحديث. وفي لفظ: إذا جامع الرجل المرأةَ فلم يُنزِل؟ قال: يغسلُ ما مسّ المرأة منه، ثم يتوضأ ويُصلي. هكذا في لفظ البخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء: إنما الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Ghusl (293) and Muslim in al-Ḥayḍ (346); the wording is that of Muslim.","chapter_en":"What Has Been Reported Concerning the Statement: “Water Is Only Required From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ubayy ibn Kaʿb , may Allah be pleased with him, reported: I asked the Messenger of Allah ﷺ about a man who has intercourse with a woman but does not ejaculate. He said: “He should wash whatever of him came into contact with the woman, then perform wuḍūʾ and pray.”"]},"buhuth":{"en":["In al-Bukhārī’s wording:","“If a man has intercourse with a woman but does not ejaculate, he should wash whatever of him came into contact with the woman, then perform wuḍūʾ and pray.”","Al-Bukhārī said: “Ghusl is safer, and that is the later position; we only set out their disagreement.” As al-Ḥāfiẓ explained, this means that if the abrogating evidence is not established and no preference becomes clear, then performing ghusl is the safer course for one’s religion.","The meaning of this is that al-Bukhārī did not regard ghusl as obligatory except with ejaculation.","This is also indicated by his narration from Abū Hurayrah: “When he sits between her four parts and exerts himself with her, ghusl becomes obligatory” (no. 291), with “exerts himself” understood here as ejaculation. His purpose was to show the disagreement of the Companions and Successors: at the beginning of Islam the practice followed the reports of ʿUthmān and Ubayy ibn Kaʿb, while ghusl was safer—that is, recommended. Since the forthcoming abrogating report of Ubayy ibn Kaʿb was not established for him because of the disagreement in its transmission from al-Zuhrī, he did not include it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (293)، ومسلم (346)، واللفظ له."},{"num":1448,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ، أَنَّهُ سَأَلَ عُثْمَانَ بْنَ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ، قُلْتُ: أَرَأَيْتَ إِذَا جَامَعَ فَلَمْ يُمْنِ، قَالَ عُثْمَانُ: يَتَوَضَّأُ كَمَا يَتَوَضَّأُ لِلصَّلَاةِ وَيَغْسِلُ ذَكَرَهُ، قَالَ عُثْمَانُ: سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلْتُ عَنْ ذَلِكَ عَلِيًّا، وَالزُّبَيْرَ، وَطَلْحَةَ، وَأُبَيَّ بْنَ كَعْبٍ رَضِيَ اللَّهُ عَنْهُمْ، فَأَمَرُوهُ بِذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (179) واللفظ له، ومسلم في الحيض (347)كلاهما من حديث يحيى بن أبي كثير، عن أبي سلمة، أنَّ عطاء بن يسار أخبره، أنَّ زيد بن خالدٍ أخبره فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء: إنما الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (179), whose wording is cited here, and Muslim (347).","chapter_en":"What Has Been Reported Concerning the Statement: “Water Is Only Required From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Zayd ibn Khālid al-Juhanī , may Allah be pleased with him, reported that he asked ʿUthmān ibn ʿAffān , may Allah be pleased with him: “What do you say about a man who has intercourse but does not ejaculate?” He replied: “He should perform wuḍūʾ as he does for prayer and wash his private part.” ʿUthmān , may Allah be pleased with him, said: “I heard this from the Messenger of Allah ﷺ.” Zayd then asked ʿAlī, al-Zubayr, Ṭalḥah, and Ubayy ibn Kaʿb , may Allah be pleased with them, about it, and they gave the same ruling."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (179)، واللفظ له، ومسلم (347)."},{"num":1449,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ، عَنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، نَحْوُ حَدِيثِ عُثْمَانَ."],"takhrij":"صحيح: رواه مسلم في الحيض (347) عن عبد الوارث بن عبد الصّمد، حدّثني أبي، عن جدّي، عن الحسين، قال يحيى (وهو ابن أبي كثير): وأخبرني أبو سلمة، أنّ عروة بن الزّبير أخبره، أنّ أبا أيوب أخبره أنه سمع ذلك من رسول الله صلى الله عليه وسلم، ولم يسق مسلم لفظه، وإنما أحاله على حديث عثمان. وأبو أيوب يرويه أيضاً عن أبي بن كعب الذي ســـأل رسول الله صلى الله عليه وسلم عن الرّجل الذي جامع امرأته ولم ينزل... إلخ الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء: إنما الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ḥayḍ (347).","chapter_en":"What Has Been Reported Concerning the Statement: “Water Is Only Required From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abū Ayyūb al-Anṣārī , may Allah be pleased with him, reported from the Messenger of Allah ﷺ a narration similar to the report of ʿUthmān , may Allah be pleased with him."]},"buhuth":{"en":["Abū Ayyūb , may Allah be pleased with him, also narrated it from Ubayy ibn Kaʿb , may Allah be pleased with him, who asked the Messenger of Allah ﷺ about a man who had intercourse with his wife but did not ejaculate; he then mentioned the report.","Abū Ayyūb continued to give this ruling after the Prophet ﷺ because the abrogation had not reached him.","As for what Ibn Mājah (607) and others narrated with the wording, “Water is only required because of water,” its chain is not strong. It contains ʿAbd al-Raḥmān ibn Suʿād, concerning whom al-Bukhārī said, “There is some question about him.” Ibn Ḥibbān nevertheless included him in al-Thiqāt (5/93), while al-Ḥāfiẓ called him “acceptable,” meaning when corroborated; otherwise his hadith is soft."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (347)."},{"num":1450,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: خَرَجْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الِاثْنَيْنِ إِلَى قُبَاءَ، حَتَّى إِذَا كُنَّا فِي بَنِي سَالِمٍ، وَقَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى بَابِ عِتْبَانَ، فَصَرَخَ بِهِ، فَخَرَجَ يَجُرُّ إِزَارَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْجَلْنَا الرَّجُلَ، فَقَالَ عِتْبَانُ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ الرَّجُلَ يُعْجَلُ عَنِ امْرَأَتِهِ، وَلَمْ يُمْنِ، مَاذَا عَلَيْهِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا الْمَاءُ مِنَ الْمَاءِ."],"takhrij":"متفق عليه: رواه مسلم في الحيض (343) عن عبدالرحمن بن أبي سعيد، عن أبيه. ورواه أيضاً عن أبي سلمة بن عبدالرحمن عن أبي سعيد، ولم يذكر القصة، وإنما ذكر لفظ الحديث فقط، وهو: إنما الماء من الماء.","grade":"متفق عليه","chapter_ar":"باب ما جاء: إنما الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ḥayḍ (343).","chapter_en":"What Has Been Reported Concerning the Statement: “Water Is Only Required From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī , may Allah be pleased with him, reported: I went out with the Messenger of Allah ﷺ on Monday toward Qubāʾ. When we reached Banū Sālim, the Messenger of Allah ﷺ stopped at the door of ʿItbān and called out to him. He came out dragging his lower garment. The Messenger of Allah ﷺ said: “We have made the man hurry.” ʿItbān , may Allah be pleased with him, asked: “O Messenger of Allah, what do you say about a man who is interrupted during intercourse with his wife and does not ejaculate? What is required of him?” The Messenger of Allah ﷺ said: “Water is only required because of water.”"]},"buhuth":{"en":["In another narration of Muslim, and in al-Bukhārī in al-Wuḍūʾ (180), through al-Ḥakam from Dhakwān from Abū Saʿīd al-Khudrī, the Messenger of Allah ﷺ passed by a man of the Anṣār and sent for him. He came out with his head dripping. The Prophet ﷺ said: “Perhaps we made you hurry?” He replied: “Yes, O Messenger of Allah.” He said: “If you were made to hurry, or if you had intercourse without ejaculating, then no ghusl is required of you; you must perform wuḍūʾ.” The wording is Muslim’s.","The expression “aqḥaṭta” comes from qaḥṭ, drought or lack of rain. A man is said to have “aqḥaṭa” when he has intercourse without ejaculating. It has the same meaning as iksāl in the hadith of Ubayy ibn Kaʿb.","As for “Water is only required because of water,” the first “water” means the purifying water used for ghusl, while the second means semen. It is evidence for those who did not consider ghusl obligatory merely from the meeting of the circumcised parts, but this ruling was abrogated by the hadith of ʿĀʾishah and others in which the Prophet ﷺ said: “When he sits between her four parts and the circumcised parts meet, ghusl becomes obligatory.” This follows in the next chapter."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (343)."},{"num":1451,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا جَلَسَ بَيْنَ شُعَبِهَا الْأَرْبَعِ، ثُمَّ جَهَدَهَا فَقَدْ وَجَبَ الْغَسْلُ."],"takhrij":"متفق عليه: رواه البخاري في الغسل (291) ومسلم في الحيض (348) كلاهما من حديث هشام الدستوائي، عن قتادة، عن الحسن، عن أبي رافع، عن أبي هريرة. وزاد مسلم من طريق مطر، عن الحسن: وإن لم يُنزِل.","grade":"متفق عليه","chapter_ar":"باب ما يوجب الغسل ونسخ أن الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Ghusl (291) and Muslim in al-Ḥayḍ (348).","chapter_en":"What Makes Ghusl Obligatory and the Abrogation of “Water Is From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah , may Allah be pleased with him, reported that the Prophet ﷺ said: “When a man sits between a woman’s four parts and then exerts himself with her, ghusl has become obligatory.”"]},"buhuth":{"en":["Muslim added:","“Even if he does not ejaculate.”","The expression “the two circumcised parts” refers to the circumcision of the man and the woman. Female circumcision was described as the cutting of a small fold of skin at the upper part of the vulva, resembling a rooster’s comb, with a thin membrane between it and the vaginal opening."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (291)، ومسلم (348)."},{"num":1452,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: اخْتَلَفَ فِي ذَلِكَ رَهْطٌ مِنَ الْمُهَاجِرِينَ وَالأَنْصَارِ، فَقَالَ الأَنْصَارِيُّونَ: لَا يَجِبُ الْغُسْلُ إِلَّا مِنَ الدَّفْقِ أَوْ مِنَ الْمَاءِ، وَقَالَ الْمُهَاجِرُونَ: بَلْ إِذَا خَالَطَ فَقَدْ وَجَبَ الْغُسْلُ قَالَ: قَالَ أَبُو مُوسَى: فَأَنَا أَشْفِيكُمْ مِنْ ذَلِكَ، فَقُمْتُ فَاسْتَأْذَنْتُ عَلَى عَائِشَةَ، فَأُذِنَ لِي، فَقُلْتُ لَهَا: يَا أُمَّاهْ، أَوْ يَا أُمَّ الْمُؤْمِنِينَ، إِنِّي أُرِيدُ أَنْ أَسْأَلَكِ عَنْ شَيْءٍ، وَإِنِّي أَسْتَحْيِيكِ، فَقَالَتْ: لَا تَسْتَحْيِي أَنْ تَسْأَلَنِي عَمَّا كُنْتَ سَائِلًا عَنْهُ أُمَّكَ الَّتِي وَلَدَتْكَ، أَنَا أُمُّكَ، قُلْتُ: فَمَا يُوجِبُ الْغُسْلَ؟ قَالَتْ: عَلَى الْخَبِيرِ سَقَطْتَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا جَلَسَ بَيْنَ شُعَبِهَا الأَرْبَعِ، وَمَسَّ الْخِتَانُ الْخِتَانَ فَقَدْ وَجَبَ الْغُسْلُ."],"takhrij":"صحيح: رواه مسلم (349). من طرق عن هشام بن حسان، عن حميد بن هلال، عن أبي بردة، عن أبي موسى فذكره. وجاء في آخر الإسناد: ولا أعلمه إلا عن أبي بردة.","grade":"صحيح","chapter_ar":"باب ما يوجب الغسل ونسخ أن الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (349).","chapter_en":"What Makes Ghusl Obligatory and the Abrogation of “Water Is From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī , may Allah be pleased with him, reported: A group of the Muhājirūn and Anṣār disagreed concerning this matter. The Anṣār said: “Ghusl becomes obligatory only because of ejaculation or the emission of semen.” The Muhājirūn said: “Rather, once intercourse occurs, ghusl becomes obligatory.” Abū Mūsā said: “I will settle this matter for you.” I stood and sought permission to enter upon ʿĀʾishah , may Allah be pleased with her, and she permitted me. I said: “O Mother of the Believers, I want to ask you about something, but I feel shy before you.” She replied: “Do not be shy to ask me what you would have asked the mother who gave birth to you, for I am only your mother.” I asked: “What makes ghusl obligatory?” She said: “You have come to one who knows.” The Messenger of Allah ﷺ said: “When he sits between her four parts and the circumcised part touches the circumcised part, ghusl has become obligatory.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (349)."},{"num":1453,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: إِنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يُجَامِعُ أَهْلَهُ ثُمَّ يُكْسِلُ، هَلْ عَلَيْهِمَا الْغُسْلُ؟ وَعَائِشَةُ جَالِسَةٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي لَأَفْعَلُ ذَلِكَ أَنَا وَهَذِهِ، ثُمَّ نَغْتَسِلُ."],"takhrij":"صحيح: رواه مسلم (350) من طريق جابر بن عبدالله، عن أم كلثوم، عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب ما يوجب الغسل ونسخ أن الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (350).","chapter_en":"What Makes Ghusl Obligatory and the Abrogation of “Water Is From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿĀʾishah , may Allah be pleased with her, reported: A man asked the Messenger of Allah ﷺ about a man who has intercourse with his wife but stops without ejaculating: “Is ghusl required of her?” ʿĀʾishah , may Allah be pleased with her, was sitting there. The Messenger of Allah ﷺ said: “I do that—I and this one—then we perform ghusl.”"]},"buhuth":{"en":["Regarding the Prophet’s ﷺ statement, “I do that—I and this one—then we perform ghusl,” al-Nawawī said that his action here indicates obligation; otherwise it would not have answered the questioner."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (350)."},{"num":1454,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: إِذَا جَاوَزَ الْخِتَانُ الْخِتَانَ فَقَدْ وَجَبَ الْغُسْلُ، فَعَلْتُهُ أَنَا وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاغْتَسَلْنَا."],"takhrij":"صحيح: رواه الترمذي (108) وابن ماجه (608) كلاهما من طريق الوليد بن مسلم، قال: حدثنا الأوزاعي، قال: أنبانا عبدالرحمن بن القاسم، قال: أخبرنا القاسم بن محمد، عن عائشة فذكرت مثله. هكذا صرَّح الوليد بن مسلم بالتحديث إلى آخر الإسناد عند ابن ماجه. قال الترمذي: حسن صحيح.","grade":"صحيح","chapter_ar":"باب ما يوجب الغسل ونسخ أن الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (108) and Ibn Mājah (608).","chapter_en":"What Makes Ghusl Obligatory and the Abrogation of “Water Is From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿĀʾishah , may Allah be pleased with her, said: “When the circumcised part passes the circumcised part, ghusl becomes obligatory. The Messenger of Allah ﷺ and I did this, and we performed ghusl.”"]},"buhuth":{"en":["Al-Aʿẓamī said: Ibn Ḥibbān also authenticated it (2/356).","Al-Tirmidhī (109) also narrated it through Hannād, from Wakīʿ, from Sufyān, from ʿAlī ibn Yazīd, from Saʿīd ibn al-Musayyib, from ʿĀʾishah, who reported that the Prophet ﷺ said: “When the circumcised part passes the circumcised part, ghusl becomes obligatory.” ʿAlī ibn Yazīd ibn Judʿān is weak. The hadith of Muslim conveys the same meaning."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (108)، وابن ماجه (608)."},{"num":1455,"demo":false,"sanad":"","matn":["عَنْ حَرَامِ بْنِ حَكِيمٍ، عَنْ عَمِّهِ عَبْدِ اللَّهِ بْنِ سَعْدٍ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَمَّا يُوجِبُ الْغُسْلَ، وَعَنِ الْمَاءِ يَكُونُ بَعْدَ الْمَاءِ، وَعَنِ الصَّلَاةِ فِي بَيْتِي، وَعَنِ الصَّلَاةِ فِي الْمَسْجِدِ، وَعَنْ مُؤَاكَلَةِ الْحَائِضِ، فَقَالَ: إِنَّ اللَّهَ لَا يَسْتَحْيِي مِنَ الْحَقِّ، أَمَّا أَنَا فَإِذَا فَعَلْتُ كَذَا وَكَذَا فَذَكَرَ الْغُسْلَ، قَالَ: أَتَوَضَّأُ وُضُوئِي لِلصَّلَاةِ أَغْسِلُ فَرْجِي ثُمَّ ذَكَرَ الْغُسْلَ، وَأَمَّا الْمَاءُ يَكُونُ بَعْدَ الْمَاءِ فَذَلِكَ الْمَذْيُ، وَكُلُّ فَحْلٍ يُمْذِي، فَأَغْسِلُ مِنْ ذَلِكَ فَرْجِي وَأَتَوَضَّأُ، وَأَمَّا الصَّلَاةُ فِي الْمَسْجِدِ وَالصَّلَاةُ فِي بَيْتِي، فَقَدْ تَرَى مَا أَقْرَبَ بَيْتِي مِنَ الْمَسْجِدِ، وَلَأَنْ أُصَلِّيَ فِي بَيْتِي أَحَبُّ إِلَيَّ مِنْ أَنْ أُصَلِّيَ فِي الْمَسْجِدِ إِلَّا أَنْ تَكُونَ صَلَاةً مَكْتُوبَةً، وَأَمَّا مُؤَاكَلَةُ الْحَائِضِ فوَآكِلْهَا."],"takhrij":"حسن: رواه أحمد (19007) عن عبدالرحمن بن مهدي، عن معاوية، يعني ابن صالح، عن العلاء، يعني ابن الحارث، عن حرام بن حكيم، عن عمِّه عبدالله بن سعد فذكره.","grade":"حسن","chapter_ar":"باب ما يوجب الغسل ونسخ أن الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (19007), al-Tirmidhī (133), and Ibn Mājah (651).","chapter_en":"What Makes Ghusl Obligatory and the Abrogation of “Water Is From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ḥarām ibn Ḥakīm reported from his uncle, ʿAbdullāh ibn Saʿd , may Allah be pleased with him, that he asked the Messenger of Allah ﷺ about what makes ghusl obligatory, about fluid that comes afterward, about prayer in his house compared with prayer in the mosque, and about eating together with a menstruating woman. The Prophet ﷺ said: “Indeed, Allah is not shy of the truth.” He then described ghusl and said: “I perform wuḍūʾ as I do for prayer, and I wash my private part.” Regarding the fluid that comes afterward, he said: “As for the fluid that comes afterward, that is madhy. Every male emits madhy, so I wash my private part because of it and perform wuḍūʾ.” Regarding prayer, he said: “As for prayer in the mosque and prayer in my house, you can see how close my house is to the mosque. Yet for me to pray in my house is more beloved to me than to pray in the mosque, except when it is an obligatory prayer.” Regarding eating with a menstruating woman, he said: “Eat with her.”"]},"buhuth":{"en":["Abū Dāwūd (212) also narrated that he asked:","“What is permissible for me with my wife while she is menstruating?”","The Messenger of Allah ﷺ replied:","“You may have what is above the waist-wrapper.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (19007)، والترمذي (133)، وابن ماجه (651)."},{"num":1456,"demo":false,"sanad":"","matn":["عَنْ أُبَيَّ بْنَ كَعْبٍ أَخْبَرَهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا جُعِلَ ذَلِكَ رُخْصَةً لِلنَّاسِ فِي أَوَّلِ الْإِسْلَامِ لِقِلَّةِ الثِّيَابِ، ثُمَّ أَمَرَ بِالْغُسْلِ وَنَهَى عَنْ ذَلِكَ، قَالَ أَبُو دَاوُد: يَعْنِي الْمَاءَ مِنَ الْمَاءِ."],"takhrij":"صحيح: أخرجه أبو داود (214) من حديث عمرو بن الحارث، عن ابن شهاب الزهري، قال: حدثني بعض من أرضى، أنَّ سهل بن سعد الساعدي أخبره أنَّ أُبَي بن كعب أخبره، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما يوجب الغسل ونسخ أن الماء من الماء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (214).","chapter_en":"What Makes Ghusl Obligatory and the Abrogation of “Water Is From Water”","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ubayy ibn Kaʿb , may Allah be pleased with him, reported: The Messenger of Allah ﷺ permitted that ruling as a concession for the people at the beginning of Islam because clothing was scarce. Later, he commanded ghusl and prohibited acting upon that earlier concession. Abū Dāwūd said: He meant the ruling expressed in the statement, “Water is only required because of water.”"]},"buhuth":{"en":["Its chain is connected except that it contains an unnamed man.","Ibn Khuzaymah (1/114) said that the unnamed man through whom ʿAmr ibn al-Ḥārith transmitted this appears to have been Abū Ḥāzim Salamah ibn Dīnār, because Mubashshir ibn Ismāʿīl narrated this report from Abū Ghassān Muḥammad ibn Muṭarrif, from Abū Ḥāzim, from Sahl ibn Saʿd. Abū Dāwūd (215) also narrated the route mentioned by Ibn Khuzaymah.","After transmitting the report through Abū Dāwūd by way of ʿAmr ibn al-Ḥārith from Ibn Shihāb, who said, “A person whom I trust narrated to me,” al-Bayhaqī said: “We have also narrated it through another connected, authentic chain from Sahl ibn Saʿd.” That route is through Abū Ḥāzim, from Sahl ibn Saʿd, from Ubayy ibn Kaʿb, stating that the ruling “water is only required because of water” was a concession granted by the Messenger of Allah ﷺ at the beginning of Islam, after which he commanded ghusl. Another wording says: “Then we were commanded to perform ghusl.”","Al-Aʿẓamī said: The narrators of this chain are trustworthy except Mubashshir ibn Ismāʿīl al-Ḥalabī, who is ṣadūq.","It is therefore possible that al-Zuhrī first heard it from Abū Ḥāzim, then hesitated or doubted his name and said, “A person whom I trust narrated to me,” and later was able to hear it directly from Sahl himself. Yūnus narrated from al-Zuhrī that he said, “Sahl narrated to me,” and in another version Sahl ibn Saʿd al-Sāʿidī said, “Ubayy ibn Kaʿb informed us,” and he mentioned the report.","Ibn Mājah (609) narrated this latter route, and al-Tirmidhī (110) narrated it through Yūnus ibn Yazīd, from al-Zuhrī, from Sahl ibn Saʿd, with similar wording. Al-Tirmidhī said: “A ḥasan ṣaḥīḥ hadith.” Maʿmar also narrated it from al-Zuhrī through the same chain.","Thus Yūnus ibn Yazīd and Maʿmar both narrated it from al-Zuhrī directly from Sahl ibn Saʿd without an intermediary. In all these forms, the chain is ṣaḥīḥ.","This establishes the abrogation of the report, “Water is only required because of water.” Al-Tirmidhī said that this ruling applied at the beginning of Islam and was later abrogated; more than one Companion, including Ubayy ibn Kaʿb and Rāfiʿ ibn Khadīj, narrated this, and the majority of the scholars acted upon the later ruling that intercourse obligates ghusl upon both spouses even if neither ejaculates.","Al-Aʿẓamī said: The hadith of Ubayy ibn Kaʿb has already been documented. As for the report of Rāfiʿ ibn Khadīj, it is weak. Aḥmad (17288) narrated it with Rushdayn ibn Saʿd in its chain, and he is very weak; the route also contains an unidentified son of Rāfiʿ ibn Khadīj, while Mūsā ibn Ayyūb was criticized. Al-Haythamī cited it in Majmaʿ al-Zawāʾid (1/264–265) and said: “It contains Rushdayn ibn Saʿd, who is weak.” Al-Ṭabarānī also narrated it in al-Kabīr (4347) and al-Awsaṭ (6509), naming Rāfiʿ’s son as Sahl, who is unknown.","There are also reports in this chapter from Abū Hurayrah and Bilāl, but none of them is established."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (214)."},{"num":1457,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُنْتُ قَائِمًا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ حِبْرٌ مِنْ أَحْبَارِ الْيَهُودِ فَقَالَ: السَّلَامُ عَلَيْكَ يَا مُحَمَّدُ! فَدَفَعْتُهُ دَفْعَةً كَادَ يُصْرَعُ مِنْهَا، فَقَالَ: لِمَ تَدْفَعُنِي؟ فَقُلْتُ: أَلَا تَقُولُ يَا رَسُولَ اللَّهِ؟ فَقَالَ الْيَهُودِيُّ: إِنَّمَا نَدْعُوهُ بِاسْمِهِ الَّذِي سَمَّاهُ بِهِ أَهْلُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اسْمِي مُحَمَّدٌ الَّذِي سَمَّانِي بِهِ أَهْلِي، فَقَالَ الْيَهُودِيُّ: جِئْتُ أَسْأَلُكَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيَنْفَعُكَ شَيْءٌ إِنْ حَدَّثْتُكَ؟ قَالَ: أَسْمَعُ بِأُذُنَيَّ، فَنَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعُودٍ مَعَهُ، فَقَالَ: سَلْ، فَقَالَ الْيَهُودِيُّ: أَيْنَ يَكُونُ النَّاسُ يَوْمَ تُبَدَّلُ الأَرْضُ غَيْرَ الأَرْضِ وَالسَّمَوَاتُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُمْ فِي الظُّلْمَةِ دُونَ الْجِسْرِ، قَالَ: فَمَنْ أَوَّلُ النَّاسِ إِجَازَةً؟ قَالَ: فُقَرَاءُ الْمُهَاجِرِينَ، قَالَ الْيَهُودِيُّ: فَمَا تُحْفَتُهُمْ حِينَ يَدْخُلُونَ الْجَنَّةَ؟ قَالَ: زِيَادَةُ كَبِدِ النُّونِ، قَالَ: فَمَا غِذَاؤُهُمْ عَلَى إِثْرِهَا؟ قَالَ: يُنْحَرُ لَهُمْ ثَوْرُ الْجَنَّةِ الَّذِي كَانَ يَأْكُلُ مِنْ أَطْرَافِهَا، قَالَ: فَمَا شَرَابُهُمْ عَلَيْهِ؟ قَالَ: مِنْ عَيْنٍ فِيهَا، تُسَمَّى سَلْسَبِيلًا، قَالَ: صَدَقْتَ، قَال: وَجِئْتُ أَسْأَلُكَ عَنْ شَيْءٍ لَا يَعْلَمُهُ أَحَدٌ مِنْ أَهْلِ الأَرْضِ إِلَّا نَبِيٌّ أَوْ رَجُلٌ أَوْ رَجُلَانِ، قَالَ: يَنْفَعُكَ إِنْ حَدَّثْتُكَ، قَالَ: أَسْمَعُ بِأُذُنَيَّ، قَالَ: جِئْتُ أَسْأَلُكَ عَنِ الْوَلَدِ، قَالَ: مَاءُ الرَّجُلِ أَبْيَضُ، وَمَاءُ الْمَرْأَةِ أَصْفَرُ، فَإِذَا اجْتَمَعَا فَعَلَا مَنِيُّ الرَّجُلِ مَنِيَّ الْمَرْأَةِ، أَذْكَرَا بِإِذْنِ اللَّهِ، وَإِذَا عَلَا مَنِيُّ الْمَرْأَةِ مَنِيَّ الرَّجُلِ آنَثَا بِإِذْنِ اللَّهِ، قَالَ الْيَهُودِيُّ: لَقَدْ صَدَقْتَ وَإِنَّكَ لَنَبِيٌّ، ثُمَّ انْصَرَفَ فَذَهَبَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ سَأَلَنِي هَذَا عَنِ الَّذِي سَأَلَنِي عَنْهُ، وَمَا لِي عِلْمٌ بِشَيْءٍ مِنْهُ حَتَّى أَتَانِيَ اللَّهُ بِهِ."],"takhrij":"صحيح: رواه مسلم في الحيض (315) عن الحسن بن علي الحُلواني، ثنا أبو توبة، ثنا مُعاوية بن سلام، عن زيدٍ، أنَّه سمِع أبا سلامٍ قال: حدَّثني أبو أسماء الرحبي، أنَّ ثوبان مولى رسول الله صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة ماء الرجل وماء المرأة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ḥayḍ (315).","chapter_en":"What Has Been Reported Concerning the Characteristics of the Man’s Fluid and the Woman’s Fluid","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Thawbān , may Allah be pleased with him, the freedman of the Messenger of Allah ﷺ, reported: I was standing with the Messenger of Allah ﷺ when a Jewish rabbi came and said: “Peace be upon you, O Muḥammad.” I pushed him with a shove that nearly made him fall. He asked: “Why did you push me?” I replied: “Why did you not say, ‘O Messenger of Allah’?” The Jewish man said: “We call him only by the name his family gave him.” The Messenger of Allah ﷺ said: “My name is Muḥammad—the name my family gave me.” The Jewish man said: “I have come to ask you.” The Messenger of Allah ﷺ asked: “Will it benefit you if I tell you?” He replied: “I will listen with my own ears.” The Messenger of Allah ﷺ tapped the ground with a stick he had and said: “Ask.” The Jewish man asked: “Where will the people be on the Day when the earth is changed into another earth, and the heavens as well?” He replied: “They will be in darkness before the Bridge.” He asked: “Who will be the first people permitted to cross?” He replied: “The poor among the Muhājirūn.” He asked: “What will be their welcoming delicacy when they enter Paradise?” He replied: “The extra lobe of the liver of the fish.” He asked: “What will their food be after that?” He replied: “The bull of Paradise that used to graze around its edges will be slaughtered for them.” He asked: “What will they drink with it?” He replied: “From a spring therein called Salsabīl.” The Jewish man said: “You have spoken the truth.” He then said: “I have also come to ask you about something that no one on earth knows except a prophet, or one or two men.” The Prophet ﷺ asked: “Will it benefit you if I tell you?” He replied: “I will listen with my own ears.” He said: “I have come to ask you about the child.” The Messenger of Allah ﷺ said: “The man’s fluid is white and the woman’s fluid is yellow. When they come together, if the man’s fluid prevails over the woman’s fluid, they produce a male by Allah’s permission; and if the woman’s fluid prevails over the man’s fluid, they produce a female by Allah’s permission.” The Jewish man said: “You have indeed spoken the truth, and you are certainly a prophet.” Then he turned and departed. The Messenger of Allah ﷺ said: “This man asked me about matters of which I had no knowledge until Allah brought me knowledge of them.”"]},"buhuth":{"en":["Regarding the phrase “What will be their welcoming delicacy?”, tuḥfah—with the ḥāʾ still—means something presented to a person as a special gift and kindness.","Regarding “the extra lobe of the fish’s liver,” al-nūn means a fish, with nīnān as its plural. The extra lobe of the liver means its tip, which is considered its finest part.","Regarding “they produce a male by Allah’s permission” and “they produce a female by Allah’s permission,” the first means that the child is male and the second that the child is female. Al-Nawawī mentioned this in his commentary on Muslim.","The relevance of this hadith to the chapter is its description of the man’s and woman’s fluids, the emission of which necessitates ghusl. The hadith is also cited in the Book describing Paradise and Hell."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13654],"tks":"صحيح: رواه مسلم (315)."},{"num":1458,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، أَنَّ أُمَّ سُلَيْمٍ قَالَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمَرْأَةُ تَرَى فِي الْمَنَامِ مِثْلَ مَا يَرَى الرَّجُلُ أَتَغْتَسِلُ؟ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ، فَلْتَغْتَسِلْ. فَقَالَتْ لَهَا عَائِشَةُ: أُفٍّ لَكِ وَهَلْ تَرَى ذَلِكَ الْمَرْأَةُ؟ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَرِبَتْ يَمِينُكِ، وَمِنْ أَيْنَ يَكُونُ الشَّبَهُ ؟."],"takhrij":"متفق عليه: أخرجه مالك في الطهارة (84) عن ابن شهاب، عن عروة بن الزبير فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب الغسل على المرأة إذا رأت في المنام مثل ما يرى الرجل","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Ṭahārah (84).","chapter_en":"Ghusl Is Obligatory for a Woman if She Sees in a Dream What a Man Sees","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr reported: Umm Sulaym , may Allah be pleased with her, the wife of Abū Ṭalḥah , may Allah be pleased with him, said to the Messenger of Allah ﷺ: “A woman sees in a dream what a man sees. Should she perform ghusl?” The Messenger of Allah ﷺ replied: “Yes, let her perform ghusl.” ʿĀʾishah , may Allah be pleased with her, said to her: “Uff to you! Does a woman see that?” The Messenger of Allah ﷺ said to her: “May your right hand be dusted! Then from where does resemblance come?”"]},"buhuth":{"en":["Al-Bukhārī (130, 282, 3328) and Muslim (310, 311, 312, 313, 314) also narrated it.","In some narrations of Muslim, ʿĀʾishah said to Umm Sulaym: “May your hands be dusted and may you be afflicted.” The Messenger of Allah ﷺ said: “Leave her. From what else would resemblance come? If her fluid prevails over the man’s fluid, the child resembles his maternal uncles; and if the man’s fluid prevails over hers, the child resembles his paternal uncles.”","In another narration, the Prophet ﷺ said to ʿĀʾishah: “Rather, you—may your right hand be dusted! Yes, let Umm Sulaym perform ghusl if she sees that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (84)."},{"num":1459,"demo":false,"sanad":"","matn":["عن أُمُّ سَلَمَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا رَأَتِ الرَّطْبَ فَلْتَغْتَسِلْ."],"takhrij":"حسن: رواه إسحاق في مسنده (1951) قال: أخبرنا محمد بن بكر، أنا ابن جريج، أخبرني ابن خُثَيم، أنَّ سليمان بن عتيق أخبره أنَّ امرأة جاءتْ إلى أم سلمة فقالت: إني رأيتُ في المنام كأنّ فلاناً ينكحني، فذكرت أم سلمة ذلك لرسول الله صلى الله عليه وسلم، فقال، فذكر الحديث.","grade":"حسن","chapter_ar":"باب وجوب الغسل على المرأة إذا رأت في المنام مثل ما يرى الرجل","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ḥasan: Narrated by Isḥāq in his Musnad (4/168–169, no. 1951).","chapter_en":"Ghusl Is Obligatory for a Woman if She Sees in a Dream What a Man Sees","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah , may Allah be pleased with her, reported that the Messenger of Allah ﷺ said: “If she sees wetness, then let her perform ghusl.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه إسحاق في مسنده (1951)."},{"num":1460,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اغْتَسَلَ مِنَ الْجَنَابَةِ، بَدَأَ بِغَسْلِ يَدَيْهِ ثُمَّ تَوَضَّأَ كَمَا يَتَوَضَّأُ لِلصَّلَاةِ، ثُمَّ يُدْخِلُ أَصَابِعَهُ فِي الْمَاءِ فَيُخَلِّلُ بِهَا أُصُولَ شَعَرِهِ، ثُمَّ يَصُبُّ عَلَى رَأْسِهِ ثَلَاثَ غَرَفَاتٍ بِيَدَيْهِ، ثُمَّ يُفِيضُ الْمَاءَ عَلَى جِلْدِهِ كُلِّهِ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (67) عن هشام بن عروة، عن أبيه، عن عائشة، ومن طريقه البخاري في الغسل (248) وفي رواية عنده bukhari(272) من طريق عبدالله بن المبارك، عن هشام بن عروة به قالت: كان رسول الله صلى الله عليه وسلم إذا اغتسل من الجنابة غسل يديه، وتوضأ وضؤه للصلاة، ثم اغتسل، ثم يخلِّلُ بيده شعَره، حتى إذا ظنَّ أنه قد أروَى بشرتَه أفاض عليه الماء ثلاث مرات، ثم غسل سائر جسده، ورواه مسلم في الحيض (316) من أوجه عن هشام، وفيه: كان رسول الله صلى الله عليه وسلم إذا اغتسل من الجنابة يبدأ فيغسل يديه، ثم يُفرغ بيمينه على شماله فيغسلُ فرجَه، ثم يتوضّأ وضوءه للصلاة، ثم يأخذ الماء فيدخل أصابعه في أصول الشعر، حتى إذا رأى أنْ قد استبرأ حفن على رأسه ثلاث حفنات، ثم أفاض على سائر جسده، ثم غسل رجليه. وفي البخاري: حتى إذا ظنَّ أنه قد أروَى بشرته أفاض عليها الماء ثلاث مرات، ثم غسل سائر جسده.","grade":"متفق عليه","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Ṭahārah (67), and through him by al-Bukhārī in al-Ghusl (248).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["The Mother of the Believers ʿĀʾishah , may Allah be pleased with her, reported: When the Messenger of Allah ﷺ performed ghusl from janābah, he would begin by washing his hands, then perform wuḍūʾ as he did for prayer. He would then put his fingers into the water and run them through the roots of his hair, then pour three handfuls of water over his head with his hands, and afterward pour water over all of his skin."]},"buhuth":{"en":["In another narration of al-Bukhārī (272):","“When the Messenger of Allah ﷺ performed ghusl from janābah, he washed his hands and performed wuḍūʾ as he did for prayer, then bathed. He would run his hand through his hair until he thought the water had reached the skin, then pour water over it three times, then wash the rest of his body.”","Muslim narrated it in al-Ḥayḍ (316), with the wording:","“When the Messenger of Allah ﷺ performed ghusl from janābah, he would begin by washing his hands. Then he would pour water with his right hand onto his left and wash his private part, perform wuḍūʾ as he did for prayer, then take water and insert his fingers into the roots of the hair. When he saw that the water had reached thoroughly, he would pour three handfuls over his head, then pour water over the rest of his body, then wash his feet.”","And in al-Bukhārī:","“When he thought the water had reached his skin, he poured water over it three times, then washed the rest of his body.”","In another narration of al-Bukhārī (321), the Messenger of Allah ﷺ began with his right hand when performing ghusl, poured water over it and washed it, then poured water over the impurity and washed it away with his left hand. When he had finished that, he poured water over his head. ʿĀʾishah added: “The Messenger of Allah ﷺ and I used to perform ghusl from one vessel while we were both in a state of janābah.”","In another narration, she and the Prophet ﷺ performed ghusl from one vessel holding three mudds, or approximately that amount.","Abū Dāwūd (242) reports that if any water remained, he poured it over his head.","Her statement, “then he poured water over the impurity,” probably refers to the private part."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (67)، ومن طريقه البخاري (248)."},{"num":1461,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كُنَّا إِذَا أَصَابَتْ إِحْدَانَا جَنَابَةٌ أَخَذَتْ بِيَدَيْهَا ثَلَاثًا فَوْقَ رَأْسِهَا، ثُمَّ تَأْخُذُ بِيَدِهَا عَلَى شِقِّهَا الْأَيْمَنِ وَبِيَدِهَا الْأُخْرَى عَلَى شِقِّهَا الْأَيْسَرِ."],"takhrij":"صحيح: رواه البخاري في الغسل (277) من طريق صفيَّة بنت شيبة، عن عائشة قالت، فذكرته.","grade":"صحيح","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī in al-Ghusl (277).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿĀʾishah , may Allah be pleased with her, reported: When one of us became junub, she would take water with both hands three times over her head, then pass one hand over her right side and the other hand over her left side."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (277)."},{"num":1462,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: حَدَّثَتْنِي خَالَتِي مَيْمُونَةُ قَالَتْ: أَدْنَيْتُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غُسْلَهُ مِنَ الْجَنَابَةِ، فَغَسَلَ كَفَّيْهِ مَرَّتَيْنِ أَوْ ثَلَاثًا، ثُمَّ أَدْخَلَ يَدَهُ فِي الإِنَاءِ، ثُمَّ أَفْرَغَ بِهِ عَلَى فَرْجِهِ وَغَسَلَهُ بِشِمَالِهِ، ثُمَّ ضَرَبَ بِشِمَالِهِ الأَرْضَ، فَدَلَكَهَا دَلْكًا شَدِيدًا، ثُمَّ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ أَفْرَغَ عَلَى رَأْسِهِ ثَلَاثَ حَفَنَاتٍ مِلْءَ كَفِّهِ، ثُمَّ غَسَلَ سَائِرَ جَسَدِهِ، ثُمَّ تَنَحَّى عَنْ مَقَامِهِ ذَلِكَ، فَغَسَلَ رِجْلَيْهِ، ثُمَّ أَتَيْتُهُ بِالْمِنْدِيلِ فَرَدَّهُ.","وفي رواية: أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِمِنْدِيلٍ، فَلَمْ يَمَسَّهُ، وَجَعَلَ يَقُولُ: بِالْمَاءِ هَكَذَا، يَعْنِي يَنْفُضُهُ.","وفي رواية: فَأَتَيْتُهُ بِخِرْقَةٍ فَلَمْ يُرِدْهَا، فَجَعَلَ يَنْفُضُ بِيَدِهِ."],"takhrij":"متفق عليه: رواه البخاري في الغسل (274، 257، 259) ومسلم في الحيض (317) واللفظ له، كلاهما من طريق الأعمش، عن سالم بن أبي الجعد، عن كريب، عن ابن عباس، عن خالته ميمونة فذكرت الحديثَ.","grade":"متفق عليه","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Ghusl (257, 259) and Muslim in al-Ḥayḍ (317). The wording is that of Muslim.","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās , may Allah be pleased with them, reported from his maternal aunt Maymūnah , may Allah be pleased with her: I brought the Messenger of Allah ﷺ water for his ghusl from janābah. He washed his hands two or three times, then put his hand into the vessel, poured water over his private part and washed it with his left hand. He then struck his left hand against the ground and rubbed it thoroughly, performed wuḍūʾ as for prayer, poured three full handfuls over his head, washed the rest of his body, moved from where he had been standing and washed his feet. I then brought him a towel, but he refused it.","In one narration: “A towel was brought to the Prophet ﷺ, but he did not touch it; instead, he shook the water off.” In another narration: “I brought him a cloth, but he did not want it, and he began shaking the water off with his hand.”"]},"buhuth":{"en":["Al-Nasāʾī (253) also narrated: “A towel was brought to the Prophet ﷺ, but he did not touch it, and he began doing this with the water.”","The phrase “he began doing this with the water” means that he shook or wiped the remaining water from his body with his hand."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (257، 259)، ومسلم (317)، واللفظ لمسلم."},{"num":1463,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ حَدَّثَهُمْ: أَنَّهُمُ اسْتَفْتَوْا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ فَقَالَ: أَمَّا الرَّجُلُ فَلْيَنْشُرْ رَأْسَهُ فَلْيَغْسِلْهُ حَتَّى يَبْلُغَ أُصُولَ الشَّعْرِ، وَأَمَّا الْمَرْأَةُ فَلَا عَلَيْهَا أَنْ لَا تَنْقُضَهُ لِتَغْرِفْ عَلَى رَأْسِهَا ثَلَاثَ غَرَفَاتٍ بِكَفَّيْهَا."],"takhrij":"حسن: رواه أبو داود (255) قال: حدثنا محمد بن عوف، قال: قرأتُ في أصل إسماعيل بن عَيَّاش، قال ابن عوف: حدثنا محمد بن إسماعيل، عن أبيه (يعني إسماعيل بن عياش)، حدثني ضَمْضَمُ بن زُرْعة، عن شُرَيح بن عُبيد، قال: أفتاني جُبَيْرُ بن نُفَير، عن الغُسل من الجنابة أنَّ ثوبانَ حدَّثهم، أنهم اسْتَفْتَوْا النبيَّ صلى الله عليه وسلم، فذكره","grade":"حسن","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (255).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Thawbān , may Allah be pleased with him, reported: The people asked the Prophet ﷺ for a ruling concerning ghusl from janābah. He said: “As for the man, let him loosen his hair and wash it until the water reaches the roots of the hair. As for the woman, she is not required to undo her hair; rather, let her pour three handfuls of water over her head with her hands.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (255)."},{"num":1464,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ وَ ابْنِ عُمَرَ، أَنَّ عُمَرَ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْغُسْلِ مِنَ الْجَنَابَةِ، وَاتَّسَقَتِ الْأَحَادِيثُ عَلَى هَذَا: يَبْدَأُ فَيُفْرِغُ عَلَى يَدِهِ الْيُمْنَى مَرَّتَيْنِ أَوْ ثَلَاثًا، ثُمَّ يُدْخِلُ يَدَهُ الْيُمْنَى فِي الْإِنَاءِ فَيَصُبُّ بِهَا عَلَى فَرْجِهِ وَيَدُهُ الْيُسْرَى عَلَى فَرْجِهِ فَيَغْسِلُ مَا هُنَالِكَ حَتَّى يُنْقِيَهُ، ثُمَّ يَضَعُ يَدَهُ الْيُسْرَى عَلَى التُّرَابِ إِنْ شَاءَ، ثُمَّ يَصُبُّ عَلَى يَدِهِ الْيُسْرَى حَتَّى يُنْقِيَهَا، ثُمَّ يَغْسِلُ يَدَيْهِ ثَلَاثًا وَيَسْتَنْشِقُ وَيُمَضْمِضُ وَيَغْسِلُ وَجْهَهُ وَذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا، حَتَّى إِذَا بَلَغَ رَأْسَهُ لَمْ يَمْسَحْ وَأَفْرَغَ عَلَيْهِ الْمَاءَ. فَهَكَذَا كَانَ غُسْلُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا ذُكِرَ."],"takhrij":"حسن: رواه النسائي (422) قال: أخبرنا عمران بن يزيد بن خالد، قال: حدثنا إسماعيل بن عبدالله، وهو ابن سماعة، قال: أنبأنا الأوزاعي، عن يحيى بن أبي كثير، عن أبي سلمة، عن عائشة. وعمرو بن سعد، عن نافع، عن ابن عمر، أنَّ عمر سأل رسول الله صلى الله عليه وسلم عن الغُسْلِ من الجنابة، واتسقت الأحاديث على هذا. فذكره.","grade":"حسن","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Nasāʾī (422).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["It is reported from ʿĀʾishah and Ibn ʿUmar , may Allah be pleased with them, that ʿUmar , may Allah be pleased with him, asked the Messenger of Allah ﷺ about ghusl from janābah. The narrations agree upon the following description: He begins by pouring water over his right hand two or three times. He then places his right hand into the vessel and pours water over his private part while washing it with his left hand until it is clean. Then, if he wishes, he rubs his left hand upon the ground. He pours water over his left hand until it is clean. He then washes his hands three times, rinses his mouth and nose, and washes his face and forearms three times each. When he reaches his head, he does not wipe it as in wuḍūʾ; rather, he pours water over it. This was the ghusl of the Messenger of Allah ﷺ as described in the report."]},"buhuth":{"en":["The expression “the narrations agree” means that their descriptions were consistent and harmonious."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (422)."},{"num":1465,"demo":false,"sanad":"","matn":["عَنْ جُبَيْرُ بْنُ مُطْعِمٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا أَنَا فَأُفِيضُ عَلَى رَأْسِي ثَلَاثًا، وَأَشَارَ بِيَدَيْهِ كِلْتَيْهِمَا."],"takhrij":"متفق عليه: رواه البخاري في الغسل (254) ومسلم في الحيض (327) كلاهما من طريق أبي إسحاق، عن سليمان بن صُرَدٍ، عن جبير بن مُطْعِم، فذكر الحديث. وفي رواية مسلم: قال: تَمارَوْا في الغُسْل عند رسول الله صلى الله عليه وسلم، فقال بعضُ القوم: أمَّا أنا فإني أغْسِلُ رأسي كذا وكذا، فقال رسولُ الله صلى الله عليه وسلم: أمَّا أنا فإنّي أُفيض على رأسي ثلاث أكُفٍّ.","grade":"متفق عليه","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (254) and Muslim (327).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Jubayr ibn Muṭʿim , may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “As for me, I pour water over my head three times.” He gestured with both hands."]},"buhuth":{"ar":["وفي رواية مسلم:","تماروا في الغسل عند رسول الله ﷺ، فقال بعض القوم:","أما أنا فإني أغسل رأسي كذا وكذا.","فقال رسول الله ﷺ:","«أَمَّا أَنَا فَإِنِّي أُفِيضُ عَلَى رَأْسِي ثَلَاثَ أَكُفٍّ»."],"en":["In Muslim’s narration:","The people discussed the manner of ghusl in the presence of the Messenger of Allah ﷺ.","One of them said:","“As for me, I wash my head such-and-such a number of times.”","The Messenger of Allah ﷺ said:","“As for me, I pour three handfuls of water over my head.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (254)، ومسلم (327)."},{"num":1466,"demo":false,"sanad":"","matn":["عَنْ أَبِي جَعْفَرٍ مُحَمَّدُ الْبَاقِرِ قَالَ: قَالَ لِي جَابِرُ: وَأَتَانِي ابْنُ عَمِّكَ يُعَرِّضُ بِالْحَسَنِ بْنِ مُحَمَّدِ بْنِ الْحَنَفِيَّةِ، قَالَ: كَيْفَ الْغُسْلُ مِنَ الْجَنَابَةِ؟ فَقُلْتُ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْخُذُ ثَلَاثَةَ أَكُفٍّ وَيُفِيضُهَا عَلَى رَأْسِهِ، ثُمَّ يُفِيضُ عَلَى سَائِرِ جَسَدِهِ، فَقَالَ لِي الْحَسَنُ: إِنِّي رَجُلٌ كَثِيرُ الشَّعَرِ، فَقُلْتُ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثَرَ مِنْكَ شَعَرًا.","وفي رواية: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُفْرِغُ عَلَى رَأْسِهِ ثَلَاثًا."],"takhrij":"متفق عليه: أخرجه البخاري في الغسل (256) من طريق معمر بن يحيى بن سام، حدثني أبو جعفر به، ورواه مسلم في الحيض (329) من وجه آخر عن جعفر، عن أبيه (وهو محمد المعروف بالباقر) عن جابر وفيه: كان رسول الله صلى الله عليه وسلم إذا اغتسل من الجنابة صَبَّ على رأسه ثلاث حَفناتٍ من ماء. فقال له الحسن بن محمد (بن الحنفية): إنَّ شعري كثير. قال جابر: فقلت له: يا ابن أخي! كان شعرُ رسول الله صلى الله عليه وسلم أكثر من شعرك وأطيبَ. وعند البخاري (255) من طريق مِخْولِ بن راشد، عن محمد بن علي، عن جابر: كان النبي صلى الله عليه وسلم يُفْرِغُ على رأسه ثلاثاً.","grade":"متفق عليه","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (256) and Muslim (329).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū Jaʿfar Muḥammad al-Bāqir may Allah have mercy on him reported: Jābir ibn ʿAbdullāh , may Allah be pleased with them, said to me: “Your cousin came to me”—meaning al-Ḥasan ibn Muḥammad ibn al-Ḥanafiyyah—and asked: “How is ghusl from janābah performed?” I replied: “The Messenger of Allah ﷺ used to take three handfuls of water and pour them over his head, then pour water over the rest of his body.” Al-Ḥasan said: “I am a man with a great deal of hair.” I replied: “The Prophet ﷺ had more hair than you.”","In another wording: “The Prophet ﷺ used to pour water over his head three times.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (256)، ومسلم (329)."},{"num":1467,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ وَفْدَ ثَقِيفٍ قَالُوا: يَا رَسُولَ اللَّهِ، إِنَّ أَرْضَنَا أَرْضٌ بَارِدَةٌ، فَمَا يَكْفِينَا مِنْ غُسْلِ الْجَنَابَةِ؟ قَالَ: أَمَّا أَنَا فَأُفِيضُ عَلَى رَأْسِي ثَلَاثًا."],"takhrij":"صحيح: رواه أبو يعلى في مسنده (3739) قال: حدثنا ابن أبي سمينة البصري، ثنا معتمر بن سليمان، عن حميد الطويل، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Yaʿla in his Musnad (3739).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Anas reported that the delegation of Thaqif said: “O Messenger of Allah, our land is cold, so what is sufficient for us in the ritual bath from janābah?” He said: “As for me, I pour water over my head three times.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى في مسنده (3739)."},{"num":1468,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، سَأَلَهُ رَجُلٌ كَمْ أُفِيضُ عَلَى رَأْسِي وَأَنَا جُنُبٌ؟ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْثُو عَلَى رَأْسِهِ ثَلَاثَ حَثَيَاتٍ، قَالَ الرَّجُلُ: إِنَّ شَعْرِي طَوِيلٌ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثَرَ شَعْرًا مِنْكَ وَأَطْيَبَ."],"takhrij":"حسن: رواه ابن ماجه (578) قال: حدثنا أبو بكر بن أبي شيبة، ثنا أبو خالد الأحْمرُ، عن ابن عَجْلان، عن سعيد بن أبي سعيد، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (578).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["A man asked Abū Hurayrah: “How much water should I pour over my head while I am in a state of janābah?” He replied: “The Messenger of Allah ﷺ used to pour three handfuls of water over his head.” The man said: “My hair is long.” Abū Hurayrah replied: “The Messenger of Allah ﷺ had more hair than you, and it was better.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (578)."},{"num":1469,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يَغْتَسِلَ مِنَ الْجَنَابَةِ، بَدَأَ بِكَفَّيْهِ فَغَسَلَهُمَا، ثُمَّ غَسَلَ مَرَافِغَهُ وَأَفَاضَ عَلَيْهِ الْمَاءَ، فَإِذَا أَنْقَاهُمَا أَهْوَى بِهِمَا إِلَى حَائِطٍ، ثُمَّ يَسْتَقْبِلُ الْوُضُوءَ وَيُفِيضُ الْمَاءَ عَلَى رَأْسِهِ."],"takhrij":"صحيح: رواه أبو داود (243) عن عمرو بن علي الباهلي، حدثنا محمد بن أبي عدي، حدثني سعيد، عن أبي مَعْشَرٍ، عن النَّخَعي، عن الأسْود، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (243).","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿĀʾishah, the wife of the Prophet ﷺ, reported: When the Messenger of Allah ﷺ intended to perform ghusl from janābah, he would begin by washing his hands, then wash the folds of his body and pour water over them. When he had cleaned them, he would rub his hands against a wall, then proceed with wuḍūʾ and pour water over his head."]},"buhuth":{"en":["The word marāfigh is the plural of rufgh and refers to folds of the body where dirt gathers, such as the armpits and the upper inner thighs.","The meaning of the report is that when he intended to perform ghusl from janābah, he began by washing his hands, then washed these body-fold areas and poured water over his private part. Once the folds and private part were clean, he moved his hands to a wall and rubbed them with earth to clean them, then proceeded with wuḍūʾ, poured water over his head, and thereafter over his entire body.","This explanation is distilled from the reports mentioned in this chapter."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (243)."},{"num":1470,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: كُنَّا فِي سَفَرٍ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنَّا أَسْرَيْنَا حَتَّى كُنَّا فِي آخِرِ اللَّيْلِ، وَقَعْنَا وَقْعَةً وَلَا وَقْعَةَ أَحْلَى عِنْدَ الْمُسَافِرِ مِنْهَا، فَمَا أَيْقَظَنَا إِلَّا حَرُّ الشَّمْسِ، وَكَانَ أَوَّلَ مَنِ اسْتَيْقَظَ فُلَانٌ، ثُمَّ فُلَانٌ، ثُمَّ فُلَانٌ يُسَمِّيهِمْ أَبُو رَجَاءٍ فَنَسِيَ عَوْفٌ، ثُمَّ عُمَرُ بْنُ الْخَطَّابِ الرَّابِعُ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا نَامَ لَمْ يُوقَظْ حَتَّى يَكُونَ هُوَ يَسْتَيْقِظُ، لِأَنَّا لَا نَدْرِي مَا يَحْدُثُ لَهُ فِي نَوْمِهِ، فَلَمَّا اسْتَيْقَظَ عُمَرُ وَرَأَى مَا أَصَابَ النَّاسَ، وَكَانَ رَجُلًا جَلِيدًا، فَكَبَّرَ وَرَفَعَ صَوْتَهُ بِالتَّكْبِيرِ، فَمَا زَالَ يُكَبِّرُ وَيَرْفَعُ صَوْتَهُ بِالتَّكْبِيرِ حَتَّى اسْتَيْقَظَ لِصَوْتِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا اسْتَيْقَظَ شَكَوْا إِلَيْهِ الَّذِي أَصَابَهُمْ، قَالَ: لَا ضَيْرَ أَوْ لَا يَضِيرُ، ارْتَحِلُوا، فَارْتَحَلَ، فَسَارَ غَيْرَ بَعِيدٍ، ثُمَّ نَزَلَ فَدَعَا بِالْوَضُوءِ فَتَوَضَّأَ وَنُودِيَ بِالصَّلَاةِ، فَصَلَّى بِالنَّاس، فَلَمَّا انْفَتَلَ مِنْ صَلَاتِهِ إِذَا هُوَ بِرَجُلٍ مُعْتَزِلٍ لَمْ يُصَلِّ مَعَ الْقَوْمِ، قَالَ: مَا مَنَعَكَ يَا فُلَانُ أَنْ تُصَلِّيَ مَعَ الْقَوْمِ؟ قَالَ: أَصَابَتْنِي جَنَابَةٌ وَلَا مَاءَ، قَالَ: عَلَيْكَ بِالصَّعِيدِ فَإِنَّهُ يَكْفِيكَ، ثُمَّ سَارَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاشْتَكَى إِلَيْهِ النَّاسُ مِنَ الْعَطَشِ، فَنَزَلَ فَدَعَا فُلَانًا كَانَ يُسَمِّيهِ أَبُو رَجَاءٍ نَسِيَهُ عَوْفٌ وَدَعَا عَلِيًّا، فَقَالَ: اذْهَبَا فَابْتَغِيَا الْمَاءَ، فَانْطَلَقَا، فَتَلَقَّيَا امْرَأَةً بَيْنَ مَزَادَتَيْنِ أَوْ سَطِيحَتَيْنِ مِنْ مَاءٍ عَلَى بَعِيرٍ لَهَا، فَقَالَا لَهَا: أَيْنَ الْمَاءُ؟ قَالَتْ: عَهْدِي بِالْمَاءِ أَمْسِ هَذِهِ السَّاعَةَ، وَنَفَرُنَا خُلُوفًا، قَالَا لَهَا: انْطَلِقِي، إِذًا قَالَتْ: إِلَى أَيْنَ؟ قَالَا: إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: الَّذِي يُقَالُ لَهُ الصَّابِئُ؟ قَالَا: هُوَ الَّذِي تَعْنِينَ، فَانْطَلِقِي فَجَاءَا بِهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحَدَّثَاهُ الْحَدِيثَ، قَالَ: فَاسْتَنْزَلُوهَا عَنْ بَعِيرِهَا، وَدَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِنَاءٍ فَفَرَّغَ فِيهِ مِنْ أَفْوَاهِ الْمَزَادَتَيْنِ أَوْ سَطِيحَتَيْنِ، وَأَوْكَأَ أَفْوَاهَهُمَا وَأَطْلَقَ الْعَزَالِيَ وَنُودِيَ فِي النَّاسِ اسْقُوا وَاسْتَقُوا، فَسَقَى مَنْ شَاءَ وَاسْتَقَى مَنْ شَاءَ، وَكَانَ آخِرَ ذَاكَ أَنْ أَعْطَى الَّذِي أَصَابَتْهُ الْجَنَابَةُ إِنَاءً مِنْ مَاءٍ، قَالَ: اذْهَبْ فَأَفْرِغْهُ عَلَيْكَ... (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاري في التيمم (344) ومسلم في المساجد (312:682) كلاهما من حديث عوف بن أبي جميلة الأعرابي، عن أبي رجاء العطاردي، عن عمران بن الحصين فذكره. واللفظ للبخاري. والحديث بطوله مذكور في دلائل النبوة.","grade":"متفق عليه","chapter_ar":"باب صفة غسل الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Tayammum (344) and Muslim in al-Masājid (312:682). The wording is that of al-Bukhārī.","chapter_en":"The Manner of Performing Ghusl From Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn , may Allah be pleased with him, reported: We were traveling with the Prophet ﷺ and continued by night until near the end of the night, when we stopped and fell into a sleep—and no sleep is sweeter to a traveler than that. Nothing awakened us except the heat of the sun. The first to awaken was so-and-so, then so-and-so, then so-and-so—Abū Rajāʾ used to name them, but ʿAwf forgot—and ʿUmar ibn al-Khaṭṭāb was the fourth. When the Prophet ﷺ slept, we would not awaken him until he himself awoke, because we did not know what might occur to him in his sleep. When ʿUmar awoke and saw what had happened to the people—and he was a strong man—he began saying the takbīr loudly until the Prophet ﷺ awoke. When he awoke, they complained to him about what had happened. He said: “There is no harm,” or, “It will cause no harm. Move on.” They moved on a short distance, then he stopped, called for water for wuḍūʾ and performed wuḍūʾ. The call to prayer was given and he led the people in prayer. When he finished, he saw a man apart who had not prayed with the people. He asked: “What prevented you, O so-and-so, from praying with the people?” He replied: “I became junub and there is no water.” He said: “Use the clean earth, for it is sufficient for you.” The Prophet ﷺ then continued traveling. The people complained of thirst, so he stopped and summoned a man—Abū Rajāʾ used to name him but ʿAwf forgot his name—and summoned ʿAlī, saying: “Go and search for water.” They went and encountered a woman with two large water-skins, or two water containers, on her camel. They asked her where the water was. She said that she had last been at the water at that same hour the previous day and that her people had gone away. They told her to come with them. She asked where, and they replied: “To the Messenger of Allah ﷺ.” She said: “The one whom they call the Ṣābiʾ?” They replied: “He is the one you mean. Come along.” They brought her to the Prophet ﷺ and told him what had happened. They helped her down from her camel, and the Prophet ﷺ called for a vessel. He poured into it from the mouths of the two water-skins, tied their openings, opened their lower spouts, and it was announced among the people: “Drink and draw water.” Whoever wished drank and whoever wished drew water. Finally, he gave the man who had become junub a vessel of water and said: “Go and pour it over yourself.”"]},"buhuth":{"ar":["والحديث بطوله مذكور في دلائل النبوة.","وهي قائمة تنظر إلى ما يفعل بمائها، وأيم الله لقد أقلع عنها وإنه ليخيل إلينا أنها أشد ملأة منها حين ابتدأ فيها. فقال النبي ﷺ: «اجْمَعُوا لَهَا». فجمعوا لها من بين عجوة ودقيقة وسويقة حتى جمعوا لها طعامًا، فجعلوه في ثوب، وحملوها على بعيرها، ووضعوا الثوب بين يديها.","قال لها: «تَعْلَمِينَ مَا رَزِئْنَا مِنْ مَائِكِ شَيْئًا، وَلَكِنَّ اللهَ هُوَ الَّذِي أَسْقَانَا». فأتت أهلها وقد احتبست عنهم، قالوا: ما حبسك يا فلانة؟ قالت: العجب! لقيني رجلان فذهبا بي إلى هذا الذي يقال له الصابئ، ففعل كذا وكذا. فوالله، إنه لأسحر الناس من بين هذه وهذه - وقالت بإصبعيها الوسطى والسبابة، فرفعتهما إلى السماء تعني السماء والأرض - أو إنه لرسول الله حقًّا.","فكان المسلمون بعد ذلك يغيرون على من حولها من المشركين، ولا يصيبون الصرم الذي هي منه. فقالت يومًا لقومها: ما أرى أن هؤلاء القوم يدعونكم عمدًا، فهل لكم في الإسلام؟ فأطاعوها فدخلوا في الإسلام."],"en":["The full ḥadīth is mentioned in Dalāʾil al-Nubuwwah.","The woman stood watching what they were doing with her water. By Allah, when they finished with her water-skins, it appeared to us that they contained more water than when they had begun. The Prophet ﷺ then said: “Collect something for her.” They gathered dates, flour, and roasted grain until they had collected food for her. They placed it in a cloth, loaded her onto her camel, and put the bundle before her.","He said to her: “Know that we have not diminished your water at all. Rather, Allah is the One who gave us water.” She returned to her people after having been delayed. They asked: “What kept you, O so-and-so?” She replied: “Something astonishing! Two men met me and took me to the man whom they call the Ṣābiʾ, and he did such-and-such. By Allah, he is either the greatest magician between these two”—and she raised her middle and index fingers toward the sky, indicating the heaven and earth—“or he is truly the Messenger of Allah.”","After that, the Muslims would raid the polytheists around her people but would leave untouched the settlement to which she belonged. One day she said to her people: “I think these people are deliberately leaving you alone. Would you accept Islam?” They obeyed her, and they entered Islam."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (344)، ومسلم (312:682)، واللفظ للبخاري."},{"num":1471,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْتَسِلُ وَيُصَلِّي الرَّكْعَتَيْنِ وَصَلَاةَ الْغَدَاةِ، وَلَا أَرَاهُ يُحْدِثُ وُضُوءًا بَعْدَ الْغُسْلِ."],"takhrij":"صحيح: رواه أبو داود (250)، واللفظ له، والترمذي (107)، والبيهقي (851) كلهم من حديث أبي إسحاق، عن الأسود، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ترك الوضوء بعد الغسل","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (250), whose wording is cited here, al-Tirmidhī (107), and al-Bayhaqī (1/179).","chapter_en":"Leaving Wuḍūʾ after Ghusl","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿĀʾishah , may Allah be pleased with her, reported: The Messenger of Allah ﷺ used to perform ghusl and then pray two rakʿahs and the dawn prayer, and I did not see him renew wuḍūʾ after the ghusl."]},"buhuth":{"en":["In another narration recorded by al-Tirmidhī (107), Ibn Mājah (579), and Aḥmad (24389), ʿĀʾishah said: “The Messenger of Allah ﷺ would not perform wuḍūʾ after performing ghusl from janābah.” Al-Bayhaqī titled a chapter concerning it: “Leaving Wuḍūʾ after Ghusl.”","The author said: These reports indicate that ghusl encompasses wuḍūʾ and more. For this reason, the Prophet ﷺ did not command a person in a state of janābah to perform wuḍūʾ after ghusl. The scholars differed, however, regarding rinsing the mouth and nose, as these are among the actions of wuḍūʾ. Those who held them obligatory said that both must be performed, while those who did not relied upon the report of ʿImrān ibn Ḥuṣayn, the report of Jubayr ibn Muṭʿim, and the previously mentioned report of Jābir ibn ʿAbdullāh.","Shaykh Ibn ʿUthaymīn, may Allah have mercy on him, was asked whether ghusl from janābah without a separate wuḍūʾ suffices so that a person may pray immediately. He replied that it does, provided the mouth and nose are rinsed, citing the verse: “And if you are in a state of janābah, then purify yourselves.” [al-Māʾidah 5:6] Allah did not separately mention wuḍūʾ.","He also cited the lengthy account of ʿImrān ibn Ḥuṣayn in Ṣaḥīḥ al-Bukhārī, in which the Prophet ﷺ told the man who had remained apart from the prayer: “Take this and pour it over yourself.” This shows that if a person performing ghusl from janābah causes water to reach his whole body, it suffices regardless of the exact manner. Thus, if a person immerses himself in a pool or pond intending ghusl from janābah, then comes out, rinses his mouth and nose, and prays, that suffices."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1676],"tks":"صحيح: رواه أبو داود (250)، واللفظ له، والترمذي (107)، والبيهقي (851)."},{"num":1472,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اغْتَسَلَ مِنَ الْجَنَابَةِ دَعَا بِشَيْءٍ نَحْوَ الْحِلَابِ، فَأَخَذَ بِكَفِّهِ فَبَدَأَ بِشِقِّ رَأْسِهِ الْأَيْمَنِ، ثُمَّ الْأَيْسَرِ، فَقَالَ: بِهِمَا عَلَى وَسَطِ رَأْسِهِ."],"takhrij":"متفق عليه: رواه البخاري في الغسل (258) ومسلم في الحيض (318) كلاهما عن محمد بن المثنَّى، ثنا أبو عاصم، عن حنظلة بن أبي سفيان، عن القاسم، عن عائشة فذكرت الحديث. واللفظ للبخاري، ولفظ مسلمٍ نحوه، إلا أنه قال بعد قوله ثم الأيسر: ثم أخذ بكفيه فقال بهما على رأسه.","grade":"متفق عليه","chapter_ar":"باب القدر المستحب من الماء للغسل والوضوء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Ghusl (258) and Muslim in al-Ḥayḍ (318). The wording is that of al-Bukhārī.","chapter_en":"The Recommended Amount of Water for Ghusl and Wuḍūʾ","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah , may Allah be pleased with her, reported: When the Prophet ﷺ performed ghusl from janābah, he would call for something like a ḥilāb vessel, take water with his hand, begin with the right side of his head, then the left, and then pour with both hands over his head."]},"buhuth":{"en":["Muslim’s wording is similar, except that after “then the left” it says: “Then he took water with both hands and poured it over his head.”","The word ḥilāb, with a kasrah on the letter ḥāʾ, refers to a vessel holding approximately the amount obtained from milking one she-camel."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (258)، ومسلم (318)، واللفظ للبخاري."},{"num":1473,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْتَسِلُ مِنْ إِنَاءٍ، هُوَ الْفَرَقُ مِنَ الْجَنَابَةِ."],"takhrij":"صحيح: رواه مالك في الطهارة (68) عن ابن شهاب، عن عروة، عن عائشة.","grade":"صحيح","chapter_ar":"باب القدر المستحب من الماء للغسل والوضوء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik in al-Ṭahārah (68).","chapter_en":"The Recommended Amount of Water for Ghusl and Wuḍūʾ","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah , may Allah be pleased with her, reported that the Messenger of Allah ﷺ used to perform ghusl from janābah using a vessel called a faraq."]},"buhuth":{"en":["Muslim (319) also narrated it.","A faraq equals three ṣāʿs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (68)."},{"num":1474,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْتَسِلُ بِالصَّاعِ وَيَتَوَضَّأُ بِالْمُدِّ."],"takhrij":"صحيح: رواه أبو داود (92) والنسائي (347) وابن ماجه (268) كلهم من حديث قتادة، عن صفية بنت شيبة، عن عائشة، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب القدر المستحب من الماء للغسل والوضوء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (92), al-Nasāʾī (347), and Ibn Mājah (268).","chapter_en":"The Recommended Amount of Water for Ghusl and Wuḍūʾ","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah reported that the Prophet ﷺ used to perform ghusl with one ṣāʿ of water and perform wuḍūʾ with one mudd."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (92)، والنسائي (347)، وابن ماجه (268)."},{"num":1475,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْسِلُ أَوْ كَانَ يَغْتَسِلُ بِالصَّاعِ إِلَى خَمْسَةِ أَمْدَادٍ وَيَتَوَضَّأُ بِالْمُدِّ.","وَفِي لَفْظُ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَغْتَسِلُ بِخَمْسِ مَكَاكِيكَ، وَيَتَوَضَّأُ بِمَكُّوكٍ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (201) ومسلم في الحيض (325) كلاهما من طريق مِسْعر، حدثني عبدالله بن عبدالله بن جَبْرٍ قال: سمعت أنساً، فذكره.","grade":"متفق عليه","chapter_ar":"باب القدر المستحب من الماء للغسل والوضوء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (201) and Muslim in al-Ḥayḍ (325).","chapter_en":"The Recommended Amount of Water for Ghusl and Wuḍūʾ","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik , may Allah be pleased with him, reported: The Prophet ﷺ used to perform ghusl with one ṣāʿ up to five mudds of water and perform wuḍūʾ with one mudd.","In another wording: “He used to perform ghusl with five makkūks and wuḍūʾ with one makkūk.”"]},"buhuth":{"en":["Al-Nawawī said that what is intended by makkūk here may be the mudd, as stated in another narration: “He would perform wuḍūʾ with a mudd and ghusl with a ṣāʿ up to five mudds.” It is also narrated in the Sunan: “He would perform wuḍūʾ with a vessel holding two raṭls and perform ghusl with a ṣāʿ.”","Abū Dāwūd said in his Sunan (95): I heard Aḥmad ibn Ḥanbal say: “The ṣāʿ is five raṭls. It is the ṣāʿ of Ibn Abī Dhiʾb, and it is the ṣāʿ of the Prophet ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (201)، ومسلم (325)."},{"num":1476,"demo":false,"sanad":"","matn":["عَنْ سَفِينَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُغَسِّلُهُ الصَّاعُ مِنَ الْمَاءِ مِنَ الْجَنَابَةِ، وَيُوَضِّؤُهُ الْمُدُّ.","وَفِي رِوَايَةِ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَغْتَسِلُ بِالصَّاعِ، وَيَتَطَهَّرُ بِالْمُدِّ."],"takhrij":"صحيح: رواه مسلم في الحيض (326) من طريق بشر بن المُفضَّل، ثنا أبو رَيحانة، عن سفينة. والرواية الثانية رواها من طريق علي بن حُجْرٍ، ثنا إسماعيل، عن أبي ريحانة عنه.قال مسلمٌ: قال أبو ريحانة: وقدْ كان كبِر، وما كنتُ أثق بحديثه. (يقصد به سفينة).","grade":"صحيح","chapter_ar":"باب القدر المستحب من الماء للغسل والوضوء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ḥayḍ (326).","chapter_en":"The Recommended Amount of Water for Ghusl and Wuḍūʾ","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Safīnah , may Allah be pleased with him, reported: One ṣāʿ of water sufficed the Messenger of Allah ﷺ for ghusl from janābah, and one mudd sufficed him for wuḍūʾ.","In another narration: The Messenger of Allah ﷺ used to perform ghusl with a ṣāʿ and purify himself with a mudd."]},"buhuth":{"en":["Muslim transmitted from Abū Rayḥānah: “He had grown old, and I did not place confidence in his narration,” referring to Safīnah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (326)."},{"num":1477,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْتَسِلُ بِالصَّاعِ، وَيَتَوَضَّأُ بِالْمُدِّ."],"takhrij":"حسن: رواه أبو داود (93) عن الإمام أحمد وهو في مسنده ahmad(4250)، وصحّحه ابنُ خزيمة (117) كلهم من طريق يزيد بن أبي زياد، عن سالم بن أبي الجعد، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب القدر المستحب من الماء للغسل والوضوء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (93) and Aḥmad (14250); Ibn Khuzaymah authenticated it (117).","chapter_en":"The Recommended Amount of Water for Ghusl and Wuḍūʾ","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Prophet ﷺ used to perform ghusl with one ṣāʿ and perform wuḍūʾ with one mudd."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (93)، وأحمد (14250)، وصححه ابن خزيمة (117)."},{"num":1478,"demo":false,"sanad":"","matn":["عَنْ أُمُّ عُمَارَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ فَأُتِيَ بِإِنَاءٍ فِيهِ مَاءٌ قَدْرُ ثُلُثَيِ الْمُدِّ."],"takhrij":"صحيح: رواه أبو داود (94) والنسائي (74) عن محمد بن بشار، ثنا محمد بن جعفر، ثنا شعبة، عن حبيب الأنصاري، قال: سمعت عبّادَ بن تميم، عن جدته، وهي أم عُمارة بنت كعب قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب القدر المستحب من الماء للغسل والوضوء","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (94) and al-Nasāʾī (74).","chapter_en":"The Recommended Amount of Water for Ghusl and Wuḍūʾ","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Umm ʿUmārah , may Allah be pleased with her, reported that the Prophet ﷺ performed wuḍūʾ and was brought a vessel containing about two-thirds of a mudd of water."]},"buhuth":{"en":["In al-Nasāʾī’s narration (74), Shuʿbah said: “I remember that he washed his forearms and rubbed them, and wiped the inner parts of his ears; I do not remember that he wiped their outer parts.”","Ibn Khuzaymah (118) and Ibn Ḥibbān (1083) also narrated from ʿAbdullāh ibn Zayd , may Allah be pleased with him: “The Prophet ﷺ was brought two-thirds of a mudd, and he rubbed his forearm while performing wuḍūʾ.” Its chain is ṣaḥīḥ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (94)، والنسائي (74)."},{"num":1479,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: قُلْتُ يَا رَسُولَ اللَّهِ! إِنِّي امْرَأَةٌ أَشُدُّ ضَفْرَ رَأْسِي، فَأَنْقُضُهُ لِغُسْلِ الْجَنَابَةِ؟ قَالَ: لَا، إِنَّمَا يَكْفِيكِ أَنْ تَحْثِي عَلَى رَأْسِكِ ثَلَاثَ حَثَيَاتٍ، ثُمَّ تُفِيضِينَ عَلَيْكِ الْمَاءَ فَتَطْهُرِينَ.","وَفِي رِوَايَةِ: فَأَنْقُضُهُ لِلْحَيْضَةِ وَالْجَنَابَةِ، فَقَالَ: لَا.."],"takhrij":"صحيح: رواه مسلم في الحيض (330) من طريق أيوب بن موسى، عن سعيد بن أبي سعيد المقبري، عن عبدالله بن رافع – مولى أمِّ سلمة، عن أمِّ سلمة فذكرته","grade":"صحيح","chapter_ar":"باب ترك المرأة نقض ضفر رأسها عند اغتسالها من الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (330).","chapter_en":"A Woman Not Undoing Her Braided Hair When Performing Ghusl from Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah said: I said: “O Messenger of Allah, I am a woman who tightly braids the hair of my head. Must I undo it for ghusl from janābah?” He said: “No. It is sufficient for you to pour three handfuls of water over your head, then pour water over yourself, and you will be purified.” In another narration, she asked: “Must I undo it for menstruation and janābah?” He replied: “No.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (330)."},{"num":1480,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدِ بْنِ عُمَيْرٍ قَالَ: بَلَغَ عَائِشَةَ أَنَّ عَبْدَ اللَّهِ بْنَ عَمْرٍو، يَأْمُرُ النِّسَاءَ إِذَا اغْتَسَلْنَ، أَنْ يَنْقُضْنَ رُءُوسَهُنَّ، فَقَالَتْ: يَا عَجَبًا لِابْنِ عَمْرٍ وَهَذَا! يَأْمُرُ النِّسَاءَ إِذَا اغْتَسَلْنَ أَنْ يَنْقُضْنَ رُءُوسَهُنَّ، أَفَلَا يَأْمُرُهُنَّ أَنْ يَحْلِقْنَ رُءُوسَهُنَّ؟ لَقَدْ كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ، وَلَا أَزِيدُ عَلَى أَنْ أُفْرِغَ عَلَى رَأْسِي ثَلَاثَ إِفْرَاغَاتٍ."],"takhrij":"صحيح: رواه مسلم في الحيض (331) من طريق إسماعيل بن عُليَّة، عن أيُّوب، عن أبي الزبير، عن عبيد بن عميرٍ فذكر مثله.","grade":"صحيح","chapter_ar":"باب ترك المرأة نقض ضفر رأسها عند اغتسالها من الجنابة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ḥayḍ (331).","chapter_en":"A Woman Not Undoing Her Braided Hair When Performing Ghusl from Janābah","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿUbayd ibn ʿUmayr said: It reached ʿĀʾishah that ʿAbdullāh ibn ʿAmr used to instruct women to undo their hair when performing ghusl. She said: “How astonishing is this Ibn ʿAmr! He tells women to undo their hair when they perform ghusl. Why does he not tell them to shave their heads? I used to perform ghusl with the Messenger of Allah ﷺ from a single vessel, and I would do no more than pour water over my head three times.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (331)."},{"num":1481,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: خَرَجْنَا مُوَافِينَ لِهِلَالِ ذِي الْحِجَّةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَحَبَّ أَنْ يُهِلَّ بِعُمْرَةٍ فَلْيُهْلِلْ، فَإِنِّي لَوْلَا أَنِّي أَهْدَيْتُ لَأَهْلَلْتُ بِعُمْرَةٍ، فَأَهَلَّ بَعْضُهُمْ بِعُمْرَةٍ، وَأَهَلَّ بَعْضُهُمْ بِحَجٍّ، وَكُنْتُ أَنَا مِمَّنْ أَهَلَّ بِعُمْرَةٍ فَأَدْرَكَنِي يَوْمُ عَرَفَةَ وَأَنَا حَائِضٌ، فَشَكَوْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: دَعِي عُمْرَتَكِ وَانْقُضِي رَأْسَكِ وَامْتَشِطِي وَأَهِلِّي بِحَجٍّ، فَفَعَلْتُ حَتَّى إِذَا كَانَ لَيْلَةُ الْحَصْبَةِ أَرْسَلَ مَعِي أَخِي عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ، فَخَرَجْتُ إِلَى التَّنْعِيمِ فَأَهْلَلْتُ بِعُمْرَةٍ مَكَانَ عُمْرَتِي."],"takhrij":"متفق عليه: رواه البخاري في الحيض (317) من طريق أبي أُسامة، ومسلم في الحج (1211/116) من طريق ابن نُمَير، كلاهما عن هشام بن عروة، عن أبيه عن عائشة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نقض المرأة شعرها عند اغتسالها من المحيض","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (317) and Muslim (116/1211). This wording is that of al-Bukhārī. Ibn Mājah (641) additionally narrates: “And perform ghusl.”","chapter_en":"What Has Been Narrated Concerning a Woman Undoing Her Hair When Bathing after Menstruation","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿĀʾishah said: We set out at the appearance of the crescent of Dhū al-Ḥijjah. The Messenger of Allah ﷺ said: “Whoever wishes to enter iḥrām for ʿumrah should do so. Had I not brought the sacrificial animals with me, I would have entered iḥrām for ʿumrah.” Some of them entered iḥrām for ʿumrah and others for ḥajj, and I was among those who entered iḥrām for ʿumrah. The Day of ʿArafah came while I was menstruating, so I complained about that to the Prophet ﷺ. He said: “Leave your ʿumrah, undo your hair, comb it, and enter iḥrām for ḥajj.” I did so. Then, on the night of al-Ḥaṣbah, he sent my brother ʿAbd al-Raḥmān ibn Abī Bakr with me. I went out to al-Tanʿīm and entered iḥrām for another ʿumrah in place of my original ʿumrah."]},"buhuth":{"en":["Al-Bukhārī titled a chapter concerning this report: “A Woman Undoing Her Hair When Performing Ghusl after Menstruation.” This indicates that he regarded undoing the hair as obligatory for ghusl after menstruation. Al-Ḥasan and Ṭāwūs also held this view regarding a menstruating woman, but not one performing ghusl from janābah.","ʿAbdullāh ibn ʿAmr held that the hair should be undone in both cases, as related in Ṣaḥīḥ Muslim, and ʿĀʾishah objected to his view.","The majority held that undoing the hair is not obligatory, based upon the hadith of Umm Salamah in Ṣaḥīḥ Muslim in which she asked: “Must I undo it for menstruation and janābah?” and he replied: “No.” They therefore interpreted the instruction in the hadith of ʿĀʾishah as a recommendation, thereby reconciling the two reports.","Ibn Rajab, in his commentary on al-Bukhārī, Fatḥ al-Bārī (1/476), held that the hadith of ʿĀʾishah does not prove that she was commanded to undo her hair for ghusl after menstruation. The ghusl that the Prophet ﷺ commanded her to perform was not a ghusl marking the end of menstruation. She was still menstruating at that time. Had her menstruation ended, she would have performed ṭawāf for her ʿumrah and would not have needed to raise this issue. Rather, he instructed her to bathe while she was still menstruating and then enter iḥrām for ḥajj. Thus, it was a ghusl for iḥrām while menstruating, just as Asmāʾ bint ʿUmays was instructed to perform ghusl and enter iḥrām when she experienced postnatal bleeding at Dhū al-Ḥulayfah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (317)، ومسلم (1211/116)، واللفظ للبخاري. وزاد ابن ماجه (641): «واغتسلي»."},{"num":1482,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ امْرَأَةً سَأَلَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنْ غُسْلِهَا مِنَ الْمَحِيضِ؟ فَأَمَرَهَا كَيْفَ تَغْتَسِلُ، قَالَ: خُذِي فِرْصَةً مِنْ مَسْكٍ فَتَطَهَّرِي بِهَا، قَالَتْ: كَيْفَ أَتَطَهَّرُ؟ قَالَ: تَطَهَّرِي بِهَا، قَالَتْ: كَيْفَ؟ قَالَ: سُبْحَانَ اللَّهِ تَطَهَّرِي، فَاجْتَبَذْتُهَا إِلَيَّ، فَقُلْتُ: تَتَبَّعِي بِهَا أَثَرَ الدَّمِ."],"takhrij":"متفق عليه: رواه البخاري في الحيض (314، 315) ومسلم في الحيض (332) كلاهما من طريق منصور بن صفية، عن أمه صفية، عن عائشة.","grade":"متفق عليه","chapter_ar":"باب كيفية غسل الحائض","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (314, 315) and Muslim (332).","chapter_en":"How a Menstruating Woman Performs Ghusl","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿĀʾishah said: A woman from the Anṣār asked the Prophet ﷺ about how she should perform ghusl after menstruation. He instructed her how to bathe and said: “Take a piece of cloth or cotton scented with musk and cleanse yourself with it.” She asked: “How should I cleanse myself with it?” He said: “Cleanse yourself with it.” She asked again: “How should I cleanse myself with it?” He said: “Glory be to Allah! Cleanse yourself with it.” I then drew her toward me and said: “Follow the trace of the blood with it.”"]},"buhuth":{"en":["In another narration in Muslim, ʿĀʾishah reported that Asmāʾ bint Shakal asked the Prophet ﷺ about ghusl after menstruation. He said:","“One of you should take her water and lote leaves and purify herself, performing the purification thoroughly. Then she should pour water over her head and rub it vigorously until the water reaches the roots and divisions of her hair. Then she should pour water over herself. After that, she should take a piece of cloth or cotton scented with musk and purify herself with it.”","Asmāʾ asked: “How should she purify herself with it?”","He said: “Glory be to Allah! Purify yourself with it.”","ʿĀʾishah said, as though discreetly explaining it to her: “Follow the trace of the blood with it.”","She also asked him about ghusl from janābah. He said:","“She should take water and purify herself, performing the purification thoroughly—or completing the purification—then pour water over her head and rub it until the water reaches the roots and divisions of her hair, and then pour water over herself.”","ʿĀʾishah said: “How excellent were the women of the Anṣār! Modesty did not prevent them from gaining understanding of the religion.”","In another narration, Asmāʾ bint Shakal entered upon the Prophet ﷺ and asked: “O Messenger of Allah, how should one of us perform ghusl when she becomes pure after menstruation?” The narration then continues with the same account, without mentioning ghusl from janābah. All of these narrations are in Ṣaḥīḥ Muslim.","A firṣah is a piece of wool or cotton. The meaning is that, after the menstrual bleeding ends and she has performed ghusl, she takes a piece scented with musk and wipes the places affected by the blood so that its odor is removed.","The “divisions of the head” refers to the roots and pathways of the hair where it gathers and from which water runs. The intent is to ensure that the water thoroughly reaches the roots of the hair and the scalp."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (314، 315)، ومسلم (332)."},{"num":1483,"demo":false,"sanad":"","matn":["عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ تَقُولُ: ذَهَبْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ، فَوَجَدْتُهُ يَغْتَسِلُ، وَفَاطِمَةُ ابْنَتُهُ تَسْتُرُهُ بِثَوْبٍ."],"takhrij":"متفق عليه: رواه مالك في كتاب قصر الصلاة (28) عن أبي النَّضْر مولى عمر بن عبيد الله، أنَّ أبا مُرَّة مولى عقيل بن أبي طالب أخبره أنه سمع أم هانئ بنت أبي طالب تقول، فذكرت الحديث في سياق أطول سيأتي في كتاب صلاة الضحى. ومن طريقه رواه البخاري (280) ومسلم في الحيض (336) مختصراً كما ذكرته.","grade":"متفق عليه","chapter_ar":"باب الاستتار في الغسل والبول والبراز","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (28), al-Bukhārī (280), and Muslim (336).","chapter_en":"Concealment While Bathing, Urinating, and Relieving Oneself","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Umm Hāniʾ bint Abī Ṭālib said: I went to the Messenger of Allah ﷺ in the year of the Conquest and found him performing ghusl while his daughter Fāṭimah screened him with a cloth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (28)، والبخاري (280)، ومسلم (336)."},{"num":1484,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ قَالَتْ: وَضَعْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَاءً وَسَتَرْتُهُ فَاغْتَسَلَ."],"takhrij":"متفق عليه: رواه البخاري في الغسل (276)، ومسلم في الحيض (337) كلاهما من طريق الأعمش، عن سالم بن أبي الجعد، عن كُريب، عن ابن عبَّاسٍ، عن ميمونةَ فذكرته. واللفظ لمسلم. وهو طرف من حديثها المذكور في كيفية الغسل.","grade":"متفق عليه","chapter_ar":"باب الاستتار في الغسل والبول والبراز","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (276) and Muslim (337).","chapter_en":"Concealment While Bathing, Urinating, and Relieving Oneself","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Maymūnah said: I placed water for the Prophet ﷺ and screened him while he performed ghusl."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (276)، ومسلم (337)."},{"num":1485,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ قَالَ: أَرْدَفَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ خَلْفَهُ، فَأَسَرَّ إِلَيَّ حَدِيثًا لَا أُحَدِّثُ بِهِ أَحَدًا مِنَ النَّاسِ، وَكَانَ أَحَبَّ مَا اسْتَتَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِحَاجَتِهِ هَدَفٌ، أَوْ حَائِشُ نَخْلٍ.","وَفِي رِوَايَةِ: يَعْنِي حَائِطَ نَخْلٍ."],"takhrij":"صحيح: أخرجه مسلم في الحيض (342) من طريق مهدي بن ميمون، ثنا محمد ابن عبدالله بن أبي يعقوب، عن الحسن بن سعد، عن عبدالله بن جعفر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الاستتار في الغسل والبول والبراز","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (342).","chapter_en":"Concealment While Bathing, Urinating, and Relieving Oneself","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn Jaʿfar , may Allah be pleased with them, said: One day, the Messenger of Allah ﷺ had me ride behind him, and he confided something to me that I will not disclose to anyone. The thing behind which the Messenger of Allah ﷺ most liked to conceal himself when relieving himself was a raised bank of earth or an enclosure of date-palms. In another narration: meaning a date-palm garden enclosed by a wall."]},"buhuth":{"en":["A hadaf is something elevated above the ground, and the word is also used for a target set up for shooting.","A ḥāʾish of date-palms is a date-palm garden; the narrator explained it as meaning an enclosed date-palm garden."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (342)."},{"num":1486,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ ابْنِ حَسَنَةَ قَالَ: انْطَلَقْتُ أَنَا وَعَمْرُو بْنُ الْعَاصِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَخَرَجَ وَمَعَهُ دَرَقَةٌ ثُمَّ اسْتَتَرَ بِهَا ثُمَّ بَالَ، فَقُلْنَا: انْظُرُوا إِلَيْهِ، يَبُولُ كَمَا تَبُولُ الْمَرْأَةُ، فَسَمِعَ ذَلِكَ فَقَالَ: أَلَمْ تَعْلَمُوا مَا لَقِيَ صَاحِبُ بَنِي إِسْرَائِيلَ؟ كَانُوا إِذَا أَصَابَهُمُ الْبَوْلُ قَطَعُوا مَا أَصَابَهُ الْبَوْلُ مِنْهُمْ، فَنَهَاهُمْ، فَعُذِّبَ فِي قَبْرِهِ."],"takhrij":"صحيح: أخرجه أبو داود (22) والنسائي (30) وابن ماجه (346) كلهم من طريق الأعمش، عن زيد بن وهب، عنه به. واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب الاستتار في الغسل والبول والبراز","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (22), al-Nasāʾī (30), and Ibn Mājah (346). This wording is that of Abū Dāwūd.","chapter_en":"Concealment While Bathing, Urinating, and Relieving Oneself","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Ḥasanah , may Allah be pleased with him, said: ʿAmr ibn al-ʿĀṣ and I went to the Prophet ﷺ. He came out carrying a leather shield, concealed himself behind it, and then urinated. We said: “Look at him; he urinates as a woman urinates.” He heard this and said: “Did you not know what happened to the man from the Children of Israel? Whenever urine touched them, they would cut away whatever the urine had touched. He forbade them from doing that, so he was punished in his grave.”"]},"buhuth":{"en":["A daraqah is a shield made of leather, sometimes strengthened with wood and sinew.","The words “we said, ‘Look at him’” appear in al-Nasāʾī and Ibn Mājah as: “Some of the people said.” Thus, the narrator’s expression “we said” relates what some of those present said.","The statement “he urinates as a woman urinates” may refer to his concealing himself, or it may refer to urinating while seated. Al-Nasāʾī placed the report under concealment while urinating, Abū Dāwūd under taking precautions against urine, and Ibn Mājah under strictness concerning urine.","The words “they would cut away whatever the urine had touched from them” refer to whatever part of their clothing had been affected by urine. Some narrations mention the skin or body; this has been understood as referring to clothing attached to the body, since taking the wording literally as mutilating the body would entail an unbearable hardship."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (22)، والنسائي (30)، وابن ماجه (346)، واللفظ لأبي داود."},{"num":1487,"demo":false,"sanad":"","matn":["عَنْ يَعْلَى بْنِ أُمَيَّةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يَغْتَسِلُ بِالْبَرَازِ بِلَا إِزَارٍ، فَصَعَدَ الْمِنْبَرَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ حَيِيٌّ سِتِّيرٌ يُحِبُّ الْحَيَاءَ وَالسَّتْرَ، فَإِذَا اغْتَسَلَ أَحَدُكُمْ فَلْيَسْتَتِرْ."],"takhrij":"حسن: رواه أبو داود (4012) والنسائي (406) كلاهما عن عبدالله بن محمد بن علي بن نُفَيل، قال: ثنا زهير، عن عبد الملك بن أبي سليمان العرزمي، عن عطاء، عن يعلى، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الاستتار في الغسل والبول والبراز","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (4012) and al-Nasāʾī (406).","chapter_en":"Concealment While Bathing, Urinating, and Relieving Oneself","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Yaʿlā ibn Umayyah , may Allah be pleased with him, reported that the Messenger of Allah ﷺ saw a man bathing in an open place without a lower garment. He ascended the pulpit, praised Allah and extolled Him, then said: “Indeed, Allah, Mighty and Majestic, is Modest and Concealing; He loves modesty and concealment. So when one of you bathes, let him conceal himself.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4012)، والنسائي (406)."},{"num":1488,"demo":false,"sanad":"","matn":["عَنْ أَبِي السَّمْحِ قَالَ: كُنْتُ أَخْدُمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَانَ إِذَا أَرَادَ أَنْ يَغْتَسِلَ قَالَ: وَلِّنِي، فَأُوَلِّيهِ قَفَايَ، وَأَنْشُرُ الثَّوْبَ فَأَسْتُرُهُ بِهِ."],"takhrij":"حسن: رواه أبو داود (376) والنسائي (224) وابن ماجه (613) واللفظ له كلهم من طريق عبدالرحمن بن مهدي، حدثني يحيى بن وليد، حدثني مُحِلُّ بن خليفة، حدثني أبو السمح فذكر الحديث، ورواه أبو داود وغيره مع زيادة: فأُتِيَ بِحَسَن أَوحُسَين رضي الله عنهما فبال على صدره، فجئت أغسله فقال: يُغْسلُ من بولِ الجارية، ويُرشُّ من بول الغلام. انظر: كتاب الطهارة، باب بول الطفل الرضيع.","grade":"حسن","chapter_ar":"باب الاستتار في الغسل والبول والبراز","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (376), al-Nasāʾī (224), and Ibn Mājah (613). This wording is that of Ibn Mājah.","chapter_en":"Concealment While Bathing, Urinating, and Relieving Oneself","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Abū al-Samḥ , may Allah be pleased with him, said: I used to serve the Prophet ﷺ. When he wished to perform ghusl, he would say: “Turn your back toward me.” So I would turn my back toward him, spread out a cloth, and screen him with it."]},"buhuth":{"ar":["وفي رواية أبي داود: فأُتي بحسن أو حسين رضي الله عنهما فبال على صدره، فجئت أغسله، فقال:","«يُغْسَلُ مِنْ بَوْلِ الْجَارِيَةِ، وَيُرَشُّ مِنْ بَوْلِ الْغُلَامِ»."],"en":["In a narration of Abū Dāwūd, al-Ḥasan or al-Ḥusayn , may Allah be pleased with them, was brought to him and urinated on his chest. I came to wash it, but he said:","“The urine of a girl is to be washed, while the urine of a boy is to be sprinkled with water.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه أبو داود (376)، والنسائي (224)، وابن ماجه (613)، واللفظ له."},{"num":1489,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمَلِيحِ قَالَ: دَخَلَ نِسْوَةٌ مِنْ أَهْلِ الشَّامِ عَلَى عَائِشَةَ فَقَالَتْ: مِمَّنْ أَنْتُنَّ؟ قُلْنَ: مِنْ أَهْلِ الشَّامِ، قَالَتْ: لَعَلَّكُنَّ مِنَ الْكُورَةِ الَّتِي تَدْخُلُ نِسَاؤُهَا الْحَمَّامَاتِ؟ قُلْنَ: نَعَمْ، قَالَتْ: أَمَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: مَا مِنَ امْرَأَةٍ تَخْلَعُ ثِيَابَهَا فِي غَيْرِ بَيْتِهَا إِلَّا هَتَكَتْ مَا بَيْنَهَا وَبَيْنَ اللَّهِ تَعَالَى."],"takhrij":"صحيح: رواه أبو داود (4010) والترمذي (2803) وابن ماجه (3750) كلهم من طرق عن منصور، قال سمعتُ سالم بن أبي الجعد، يحدث عن أبي المليح الهذلي فذكر مثله. واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب في منع النساء من دخول الحمامات العامة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4010), al-Tirmidhī (2803), and Ibn Mājah (3750). This wording is that of Abū Dāwūd.","chapter_en":"Preventing Women from Entering Public Bathhouses","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abū al-Malīḥ reported: Some women from Syria entered upon ʿĀʾishah , may Allah be pleased with her. She asked: “Where are you from?” They replied: “From Syria.” She said: “Perhaps you are from the district whose women enter public bathhouses?” They said: “Yes.” She said: “I heard the Messenger of Allah ﷺ say: ‘No woman removes her clothes in a place other than her own house except that she tears away the covering between herself and Allah Most High.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4010)، والترمذي (2803)، وابن ماجه (3750)، واللفظ لأبي داود."},{"num":1490,"demo":false,"sanad":"","matn":["عَنْ أُمِّ الدَّرْدَاءِ أَنَّها حَدَّثَتْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقِيَهَا يَوْمًا، فَقَالَ: مِنْ أَيْنَ جِئْتِ يَا أُمَّ الدَّرْدَاءِ؟ فَقَالَتْ: مِنَ الْحَمَّامِ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنَ امْرَأَةٍ تَنْزِعُ ثِيَابَهَا، إِلَّا هَتَكَتْ مَا بَيْنَهَا وَبَيْنَ اللَّهِ عَزَّ وَجَلَّ مِنْ سِتْرٍ."],"takhrij":"حسن: رواه الإمام أحمد (27041) والطبراني في الكبير (24/ح 652) كلاهما من طريق عبدالله بن وهب، قال: أخبرني حيوة بن شريح، قال: حدثني أبو صخر أنَّ يُحَنِّس أبا موسى حدَّثه، أنَّ أم الدرداء حدثته فذكر الحديث.","grade":"حسن","chapter_ar":"باب في منع النساء من دخول الحمامات العامة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (27041) and al-Ṭabarānī in al-Muʿjam al-Kabīr (24/255, no. 652).","chapter_en":"Preventing Women from Entering Public Bathhouses","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Umm al-Dardāʾ , may Allah be pleased with her, reported that the Messenger of Allah ﷺ met her one day and asked: “Where have you come from, O Umm al-Dardāʾ?” She replied: “From the public bathhouse.” The Messenger of Allah ﷺ said to her: “No woman removes her clothes in a place other than her own house except that she tears away a covering that exists between herself and Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27041)، والطبراني في المعجم الكبير (24/255، رقم 652)."},{"num":1491,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَدْخُلِ الْحَمَّامَ بِغَيْرِ إِزَارٍ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُدْخِلْ حَلِيلَتَهُ الْحَمَّامَ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَجْلِسْ عَلَى مَائِدَةٍ يُدَارُ عَلَيْهَا بِالْخَمْرِ."],"takhrij":"حسن: رواه الترمذي (2801) عن القاسم بن دينار الكوفي، حدَّثنا مصعب بن المقدام، عن الحسن بن صالح، عن ليث بن أبي سُليم، عن عطاء، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب في منع النساء من دخول الحمامات العامة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Good: Narrated by al-Tirmidhī (2801), who said: “Ḥasan gharīb.”","chapter_en":"Preventing Women from Entering Public Bathhouses","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jābir , may Allah be pleased with him, reported that the Prophet ﷺ said: “Whoever believes in Allah and the Last Day must not enter a public bathhouse without a waist-wrapper. Whoever believes in Allah and the Last Day must not allow his wife to enter a public bathhouse. And whoever believes in Allah and the Last Day must not sit at a table around which wine is being passed.”"]},"buhuth":{"en":["In a narration of Aḥmad:","“Whoever believes in Allah and the Last Day must not sit at a table where wine is being drunk. And whoever believes in Allah and the Last Day must never be alone with a woman when she has no maḥram with her, for the third of them is Satan.”","Narrated by Aḥmad (14651)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2801)، وقال: حسن غريب."},{"num":1492,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَتْ بَنُو إِسْرَائِيلَ يَغْتَسِلُونَ عُرَاةً يَنْظُرُ بَعْضُهُمْ إِلَى بَعْضٍ، وَكَانَ مُوسَى يَغْتَسِلُ وَحْدَهُ، فَقَالُوا: وَاللَّهِ مَا يَمْنَعُ مُوسَى أَنْ يَغْتَسِلَ مَعَنَا إِلَّا أَنَّهُ آدَرُ، فَذَهَبَ مَرَّةً يَغْتَسِلُ فَوَضَعَ ثَوْبَهُ عَلَى حَجَرٍ فَفَرَّ الْحَجَرُ بِثَوْبِهِ، فَخَرَجَ مُوسَى فِي إِثْرِهِ، يَقُولُ: ثَوْبِي يَا حَجَرُ، حَتَّى نَظَرَتْ بَنُو إِسْرَائِيلَ إِلَى مُوسَى، فَقَالُوا: وَاللَّهِ مَا بِمُوسَى مِنْ بَأْسٍ وَأَخَذَ ثَوْبَهُ فَطَفِقَ بِالْحَجَرِ ضَرْبًا.","فَقَالَ أَبُو هُرَيْرَةَ: وَاللَّهِ إِنَّهُ لَنَدَبٌ بِالْحَجَرِ سِتَّةٌ أَوْ سَبْعَةٌ ضَرْبًا بِالْحَجَرِ."],"takhrij":"متفق عليه: أخرجه البخاري في الغسل (278) واللفظ له، ومسلم في الحيض (339) كلاهما من طريق عبد الرزاق، عن معمر، عن همام بن منبه، عن أبي هريرة، فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب جواز الاغتسال عريانًا في الخلوة، والتستر أفضل","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (278), whose wording this is, and Muslim (339).","chapter_en":"The Permissibility of Bathing Unclothed in Private, While Covering Oneself Is Better","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah , may Allah be pleased with him, reported that the Prophet ﷺ said: “The Children of Israel used to bathe naked, looking at one another, whereas Mūsā used to bathe alone. They said: ‘By Allah, nothing prevents Mūsā from bathing with us except that he has a swelling of the testicles.’ One time he went to bathe and placed his garment upon a stone. The stone fled with his garment, so Mūsā ran after it saying: ‘My garment, O stone! My garment, O stone!’ until the Children of Israel looked at Mūsā and said: ‘By Allah, there is nothing wrong with Mūsā.’ He took his garment and began striking the stone.” Abū Hurayrah , may Allah be pleased with him, said: “By Allah, there were six or seven marks on the stone from his striking it.”"]},"buhuth":{"en":["Ādar refers to one who has swelling of the testicles.","Nadab refers to marks remaining from blows."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13109],"tks":"متفق عليه: رواه البخاري (278)، واللفظ له، ومسلم (339)."},{"num":1493,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَا أَيُّوبُ يَغْتَسِلُ عُرْيَانًا فَخَرَّ عَلَيْهِ جَرَادٌ مِنْ ذَهَبٍ، فَجَعَلَ أَيُّوبُ يَحْتَثِي فِي ثَوْبِهِ، فَنَادَاهُ رَبُّهُ: يَا أَيُّوبُ، أَلَمْ أَكُنْ أَغْنَيْتُكَ عَمَّا تَرَى؟ قَالَ: بَلَى وَعِزَّتِكَ، وَلَكِنْ لَا غِنَى بِي عَنْ بَرَكَتِكَ."],"takhrij":"صحيح: رواه البخاري في الغسل (279) بالإسناد السابق.","grade":"صحيح","chapter_ar":"باب جواز الاغتسال عريانًا في الخلوة، والتستر أفضل","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (279).","chapter_en":"The Permissibility of Bathing Unclothed in Private, While Covering Oneself Is Better","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah , may Allah be pleased with him, reported that the Prophet ﷺ said: “While Ayyūb was bathing naked, locusts of gold suddenly fell upon him. Ayyūb began gathering them into his garment. His Lord called to him: ‘O Ayyūb, had I not made you independent of what you see?’ He replied: ‘Yes, by Your Might, but I can never be independent of Your blessing.’”"]},"buhuth":{"en":["Al-Nawawī said: As for a man uncovering his private parts while alone, where no human being can see him, if there is a need for doing so, it is permissible. If there is no need, the scholars differed as to whether it is disliked or prohibited; the sounder view in our school is that it is prohibited."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (279)."},{"num":1494,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ دِينَارٍ قَالَ: سَمِعْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْقُلُ مَعَهُمُ الْحِجَارَةَ لِلْكَعْبَةِ وَعَلَيْهِ إِزَارُهُ، فَقَالَ لَهُ الْعَبَّاسُ عَمُّهُ: يَا ابْنَ أَخِي لَوْ حَلَلْتَ إِزَارَكَ فَجَعَلْتَ عَلَى مَنْكِبَيْكَ دُونَ الْحِجَارَةِ، قَالَ: فَحَلَّهُ فَجَعَلَهُ عَلَى مَنْكِبَيْهِ فَسَقَطَ مَغْشِيًّا عَلَيْهِ، فَمَا رُئِيَ بَعْدَ ذَلِكَ عُرْيَانًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: البخاري في الصلاة (364) واللفظ له، ومسلم في الحيض (340) كلاهما من طريق رَوْحِ بن عُبادة، حدثنا زكريا بن إسحاق، حدثنا عمرو بن دينار به مثله.","grade":"متفق عليه","chapter_ar":"باب الاعتناء بحفظ العورة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (364), whose wording this is, and Muslim (340).","chapter_en":"Taking Care to Guard One’s Private Parts","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAmr ibn Dīnār said: I heard Jābir ibn ʿAbdullāh , may Allah be pleased with them, report that the Messenger of Allah ﷺ was carrying stones with them for the Kaʿbah while wearing his waist-wrapper. His uncle al-ʿAbbās said to him: “O son of my brother, why do you not loosen your waist-wrapper and place it over your shoulders beneath the stones?” He loosened it and placed it over his shoulders, whereupon he fell unconscious. He was never seen naked after that."]},"buhuth":{"en":["This hadith demonstrates part of the honor with which Allah, Glorified and Exalted, favored the Messenger of Allah ﷺ: He protected him from disgraceful conduct and the customs of the pre-Islamic period. This was stated by al-Nawawī."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (364)، واللفظ له، ومسلم (340)."},{"num":1495,"demo":false,"sanad":"","matn":["عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ قَالَ: أَقْبَلْتُ بِحَجَرٍ أَحْمِلُهُ ثَقِيلٍ، وَعَلَيَّ إِزَارٌ خَفِيفٌ، قَالَ: فَانْحَلَّ إِزَارِي وَمَعِيَ الْحَجَرُ، لَمْ أَسْتَطِعْ أَنْ أَضَعَهُ حَتَّى بَلَغْتُ بِهِ إِلَى مَوْضِعِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْجِعْ إِلَى ثَوْبِكَ فَخُذْهُ، وَلَا تَمْشُوا عُرَاةً."],"takhrij":"صحيح: رواه مسلم في الحيض (341) عن سعيد بن يحيى الأُمَوي، حدثني أبي، حدثنا عثمان بن حكيم بن عَبّاد بن حُنيفٍ الأنصاري، أخبرني أبو أمامة بن سَهْل بن حُنيف، عن المِسْور بن مَخْرَمة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الاعتناء بحفظ العورة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (341).","chapter_en":"Taking Care to Guard One’s Private Parts","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Al-Miswar ibn Makhramah , may Allah be pleased with him, said: I came carrying a heavy stone while wearing a light waist-wrapper. My waist-wrapper came loose while I was carrying the stone, and I was unable to put the stone down until I reached its place. The Messenger of Allah ﷺ said: “Go back to your garment and put it on, and do not walk about naked.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (341)."},{"num":1496,"demo":false,"sanad":"","matn":["عَنْ بَهْزِ بْنِ حَكِيمٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: قُلْتُ يَا رَسُولَ اللَّهِ! عَوْرَاتُنَا مَا نَأْتِي مِنْهَا وَمَا نَذَرُ؟ قَالَ: احْفَظْ عَوْرَتَكَ إِلَّا مِنْ زَوْجَتِكَ أَوْ مَا مَلَكَتْ يَمِينُكَ، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ! إِذَا كَانَ الْقَوْمُ بَعْضُهُمْ فِي بَعْضٍ؟ قَالَ: إِنِ اسْتَطَعْتَ أَنْ لَا يَرَيَنَّهَا أَحَدٌ فَلَا يَرَيَنَّهَا، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ! إِذَا كَانَ أَحَدُنَا خَالِيًا؟ قَالَ: اللَّهُ أَحَقُّ أَنْ يُسْتَحْيَا مِنْهُ مِنَ النَّاسِ."],"takhrij":"حسن: رواه أبو داود (4017) والترمذي (2769) وابن ماجه (1920) كلهم من طريق بهز بن حكيم به مثله.","grade":"حسن","chapter_ar":"باب الاعتناء بحفظ العورة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (4017), al-Tirmidhī (2769), and Ibn Mājah (1920).","chapter_en":"Taking Care to Guard One’s Private Parts","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Bahz ibn Ḥakīm reported from his father, from his grandfather , may Allah be pleased with him, who said: I asked: “O Messenger of Allah, regarding our private parts, what may we expose and what must we conceal?” He said: “Guard your private parts except from your wife or those whom your right hand possesses.” I asked: “O Messenger of Allah, what if people are together with one another?” He said: “If you are able to prevent anyone from seeing them, then do not let anyone see them.” I asked: “O Messenger of Allah, what if one of us is alone?” He said: “Allah has a greater right that one should feel modest before Him than before people.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6357,12870],"tks":"حسن: رواه أبو داود (4017)، والترمذي (2769)، وابن ماجه (1920)."},{"num":1497,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيَّ، أَنَّهُ مَرَّ وَصَاحِبٌ لَهُ بِأَيْمَنَ وَفِتْيَةٍ مِنْ قُرَيْشٍ قَدْ حَلُّوا أُزُرَهُمْ، فَجَعَلُوهَا مَخَارِيقَ يَجْتَلِدُونَ بِهَا وَهُمْ عُرَاةٌ . قَالَ عَبْدُ اللَّهِ: فَلَمَّا مَرَرْنَا بِهِمْ قَالُوا: إِنَّ هَؤُلَاءِ قِسِّيسِينَ فَدَعُوهُمْ، ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَيْهِمْ، فَلَمَّا أَبْصَرُوهُ تَبَدَّدُوا، فَرَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُغْضَبًا، حَتَّى دَخَلَ، وَكُنْتُ أَنَا وَرَاءَ الْحُجْرَةِ، فَسَمِعْتُهُ يَقُولُ: سُبْحَانَ اللَّهِ، لَا مِنَ اللَّهِ اسْتَحْيَوْا، وَلَا مِنْ رَسُولِهِ اسْتَتَرُوا. وَأُمُّ أَيْمَنَ عِنْدَهُ تَقُولُ: اسْتَغْفِرْ لَهُمْ يَا رَسُولَ اللَّهِ . قَالَ عَبْدُ اللَّهِ فَبِلَأْيٍ مَا أَسْتَغْفرَ لَهُمْ."],"takhrij":"صحيح: رواه أحمد (17711)، وأبو يعلى (1540) كلاهما عن هارون بن معروف، حدثنا عبدالله بن وهب، حدثنا عمرو (هو ابن الحارث المصري)، أن سليمان بن زياد الحضرمي حدثه، أن عبد الله بن الحارث بن جزء حدثه فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الاعتناء بحفظ العورة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17711) and Abū Yaʿlā (1540).","chapter_en":"Taking Care to Guard One’s Private Parts","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn al-Ḥārith ibn Jazʾ al-Zubaydī , may Allah be pleased with him, reported that he and a companion passed by Ayman and some young men from Quraysh who had removed their waist-wrappers and made them into twisted cloths with which they struck one another while they were naked. ʿAbdullāh said: When we passed them, they said: “These men are like priests, so leave them alone.” Then the Messenger of Allah ﷺ came out to them. When they saw him, they scattered. The Messenger of Allah ﷺ returned angrily and entered. I was behind the chamber and heard him say: “Glory be to Allah! They felt no modesty before Allah, nor did they conceal themselves from His Messenger.” Umm Ayman, who was with him, kept saying: “Seek forgiveness for them, O Messenger of Allah.” ʿAbdullāh said: Only after difficulty did he seek forgiveness for them."]},"buhuth":{"en":["Makhārīq is the plural of mikhrāq: a piece of cloth rolled or twisted up and used by boys to strike one another.","Tabaddadū means that they scattered.","The expression “fa-bi-laʾyin mā istaghfara lahum” means that he sought forgiveness for them only after difficulty."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17711)، وأبو يعلى (1540)."},{"num":1498,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَنْظُرُ الرَّجُلُ إِلَى عَوْرَةِ الرَّجُلِ، وَلَا الْمَرْأَةُ إِلَى عَوْرَةِ الْمَرْأَةِ، وَلَا يُفْضِي الرَّجُلُ إِلَى الرَّجُلِ فِي ثَوْبٍ وَاحِدٍ، وَلَا تُفْضِي الْمَرْأَةُ إِلَى الْمَرْأَةِ فِي الثَّوْبِ الْوَاحِدِ.","وَفِي رِوَايَةِ: مَكَانَ عَوْرَةِ، عُرْيَةِ الرَّجُلِ، وَعُرْيَةِ الْمَرْأَةِ."],"takhrij":"صحيح: رواه مسلم في الحيض (338) من طريق زيد بن أسلم، عن عبدالرحمن بن أبي سعيدٍ الخدري، عن أبيه فذكر الحديث.","grade":"صحيح","chapter_ar":"باب تحريم النظر إلى العورات","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (338).","chapter_en":"The Prohibition of Looking at Private Parts","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī , may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “A man must not look at the private parts of another man, nor a woman at the private parts of another woman. A man must not lie in bodily contact with another man under a single garment, nor a woman with another woman under a single garment.” In another narration, the word “ʿuryah” is used in place of “ʿawrah” for the nakedness of the man and the woman."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (338)."},{"num":1499,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَطُوفُ عَلَى نِسَائِهِ بِغُسْلٍ وَاحِدٍ."],"takhrij":"صحيح: رواه مسلم في الحيض (309) من طريق شعبة، عن هشام بن زيد، عن أنس، فذكر الحديثَ.","grade":"صحيح","chapter_ar":"باب في الرجل يطوف على نسائه بغسل واحد","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (309).","chapter_en":"A Man Visiting His Wives With a Single Ghusl","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas , may Allah be pleased with him, reported that the Prophet ﷺ used to visit his wives while performing only one ghusl."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (309)."},{"num":1500,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ قَالَ: سَأَلْتُ عَائِشَةَ عَنْ وِتْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ الْحَدِيثَ قُلْتُ: كَيْفَ كَانَ يَصْنَعُ فِي الْجَنَابَةِ؟ أَكَانَ يَغْتَسِلُ قَبْلَ أَنْ يَنَامَ، أَمْ يَنَامُ قَبْلَ أَنْ يَغْتَسِلَ؟ قَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ، رُبَّمَا اغْتَسَلَ فَنَامَ، وَرُبَّمَا تَوَضَّأَ فَنَامَ، قُلْتُ: الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الأَمْرِ سَعَةً."],"takhrij":"صحيح: رواه مسلم في الحيض (307) عن قتيبة بن سعيد، حدثنا الليث، عن معاوية بن صالح، عن عبدالله بن أبي قيس فذكر مثله. وسيأتي ذكر هذا الحديث في صلاة الليل وفي صلاة الوتر مُفَرَّقاً.","grade":"صحيح","chapter_ar":"باب ما جاء في غسل الجنابة قبل النوم وبعده","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (307).","chapter_en":"What Has Been Reported Concerning Ghusl from Janābah Before Sleeping and Afterwards","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullāh ibn Abī Qays said: I asked ʿĀʾishah , may Allah be pleased with her, about the witr prayer of the Messenger of Allah ﷺ, and he mentioned the hadith. I asked: “What did he do when he was in a state of janābah? Did he perform ghusl before sleeping, or did he sleep before performing ghusl?” She replied: “He did both. Sometimes he performed ghusl and then slept, and sometimes he performed wuḍūʾ and then slept.” I said: “All praise belongs to Allah, who has placed flexibility in this matter.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (307)."},{"num":1501,"demo":false,"sanad":"","matn":["عَنْ غُضَيْفِ بْنِ الْحَارِثِ قَالَ: قُلْتُ لِعَائِشَةَ: أَرَأَيْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْتَسِلُ مِنَ الْجَنَابَةِ فِي أَوَّلِ اللَّيْلِ، أَوْ فِي آخِرِهِ؟ قَالَتْ: رُبَّمَا اغْتَسَلَ فِي أَوَّلِ اللَّيْلِ، وَرُبَّمَا اغْتَسَلَ فِي آخِرِهِ، قُلْتُ: اللَّهُ أَكْبَرُ! الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً، قُلْتُ: أَرَأَيْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ أَوَّلَ اللَّيْلِ، أَمْ فِي آخِرِهِ؟ قَالَتْ: رُبَّمَا أَوْتَرَ فِي أَوَّلِ اللَّيْلِ، وَرُبَّمَا أَوْتَرَ فِي آخِرِهِ، قُلْتُ: اللَّهُ أَكْبَرُ! الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً، قُلْتُ: أَرَأَيْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْهَرُ بِالْقُرْآنِ، أَمْ يَخْفُتُ بِهِ؟ قَالَتْ: رُبَّمَا جَهَرَ بِهِ، وَرُبَّمَا خَفَتَ، قُلْتُ: اللَّهُ أَكْبَرُ! الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً."],"takhrij":"حسن:  أبو داود (226) واللفظ له، والنسائي (222، 223) مقتصرا على الجزء الأول من الحديث، وهو ما يخص بالغسل، وابن ماجه (1354) مقتصرا على قراءة القرآن فقط، كلهم من طريق بُرد بن سِنان، عن عُبادة بن نُسيّ، عن غُضَيفِ بن الحارثِ، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في غسل الجنابة قبل النوم وبعده","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (226), whose wording this is, al-Nasāʾī (222, 223), and Ibn Mājah (1354).","chapter_en":"What Has Been Reported Concerning Ghusl from Janābah Before Sleeping and Afterwards","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ghuḍayf ibn al-Ḥārith said: I asked ʿĀʾishah , may Allah be pleased with her: “Tell me, did the Messenger of Allah ﷺ perform ghusl from janābah at the beginning of the night or at its end?” She replied: “Sometimes he performed ghusl at the beginning of the night, and sometimes he performed ghusl at its end.” I said: “Allah is the Greatest! All praise belongs to Allah, who has placed flexibility in this matter.” I asked: “Tell me, did the Messenger of Allah ﷺ perform witr at the beginning of the night or at its end?” She replied: “Sometimes he performed witr at the beginning of the night, and sometimes he performed witr at its end.” I said: “Allah is the Greatest! All praise belongs to Allah, who has placed flexibility in this matter.” I asked: “Tell me, did the Messenger of Allah ﷺ recite the Qurʾān aloud or quietly?” She replied: “Sometimes he recited it aloud, and sometimes he recited it quietly.” I said: “Allah is the Greatest! All praise belongs to Allah, who has placed flexibility in this matter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (226)، واللفظ له، والنسائي (222، 223)، وابن ماجه (1354)."},{"num":1502,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أُقِيمَتِ الصَّلَاةُ وَعُدِّلَتِ الصُّفُوفُ قياما، فَخَرَجَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا قَامَ فِي مُصَلَّاهُ ذَكَرَ أَنَّهُ جُنُبٌ، فَقَالَ لَنَا: مَكَانَكُمْ، ثُمَّ رَجَعَ فَاغْتَسَلَ، ثُمَّ خَرَجَ إِلَيْنَا وَرَأْسُهُ يَقْطُرُ فَكَبَّرَ فَصَلَّيْنَا مَعَهُ.","وَفِي رِوَايَةِ: فَعَدَّلْنَا الصُّفُوفَ، قَبْلَ أَنْ يَخْرُجَ."],"takhrij":"متفق عليه: رواه البخاري في الغسل (275) واللفظ له، ومسلم في المساجد (605) كلاهما من طريق يونس، عن الزهري، عن أبي سلمة، عن أبي هريرة، فذكر الحديث. وفي رواية لمسلم: قبل أن يُكَبِّر ذكر فانصرف.","grade":"متفق عليه","chapter_ar":"باب الجنب لم يتذكر أنه جنب إلا بعد أن أقيمت الصلاة","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (275), whose wording this is, and Muslim (605).","chapter_en":"One Who Remembers That He Is Junub Only After the Prayer Has Been Established","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah , may Allah be pleased with him, said: The prayer was established and the rows were straightened while we were standing. The Messenger of Allah ﷺ came out to us, and when he stood in his place of prayer, he remembered that he was in a state of janābah. He said to us: “Remain where you are.” He then returned, performed ghusl, and came back to us with his head dripping with water. He pronounced the takbīr, and we prayed with him.","In another narration: “We had straightened the rows before he came out.”"]},"buhuth":{"en":["In another narration of Muslim: “Before pronouncing the takbīr, he remembered and went away.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2252],"tks":"متفق عليه: رواه البخاري (275)، واللفظ له، ومسلم (605)."},{"num":1503,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْلًا قِبَلَ نَجْدٍ، فَجَاءَتْ بِرَجُلٍ مِنْ بَنِي حَنِيفَةَ يُقَالُ لَهُ ثُمَامَةُ بْنُ أُثَالٍ، فَرَبَطُوهُ بِسَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ، فَخَرَجَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَطْلِقُوا ثُمَامَةَ، فَانْطَلَقَ إِلَى نَخْلٍ قَرِيبٍ مِنَ الْمَسْجِدِ فَاغْتَسَلَ، ثُمَّ دَخَلَ الْمَسْجِدَ فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ."],"takhrij":"متفق عليه: أخرجه البخاري (462) مختصراً هكذا في كتاب الصلاة، باب الاغتسالِ إذا أسلم، وربط الأسير في المسجد، ورواه مطولا في كتاب المغازي (4372) ومسلم في كتاب الجهاد (1764) كلاهما من طريق الليث بن سعد، عن سعيد المقبري، سمع أبا هريرة فذكره. وسيأتي في كتاب الجهاد مطوّلاً.","grade":"متفق عليه","chapter_ar":"باب غسل الكافر إذا أسلم","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (462, 4372) and Muslim (1764).","chapter_en":"Ghusl for a Non-Muslim Upon Accepting Islam","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah , may Allah be pleased with him, reported: The Prophet ﷺ sent horsemen toward Najd, and they returned with a man from Banū Ḥanīfah named Thumāmah ibn Uthāl. They tied him to one of the pillars of the mosque. The Prophet ﷺ came out to him and said: “Release Thumāmah.” He went to a date-palm grove near the mosque and performed ghusl. Then he entered the mosque and said: “I bear witness that there is no deity worthy of worship except Allah, and I bear witness that Muḥammad is the Messenger of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (462، 4372)، ومسلم (1764)."},{"num":1504,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ عَاصِمٍ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُرِيدُ الْإِسْلَامَ، فَأَمَرَنِي أَنْ أَغْتَسِلَ بِمَاءٍ وَسِدْرٍ."],"takhrij":"صحيح: رواه أبو داود (355) والترمذي (605) والنسائي (188) كلهم من طريق سفيان، عن الأغر بن الصبّاح، عن خليفة بن حُصين، عن جده قيس بن عاصم.","grade":"صحيح","chapter_ar":"باب غسل الكافر إذا أسلم","chapter_ur":"","part_ar":"كتاب الغسل","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (355), al-Tirmidhī (605), and al-Nasāʾī (188).","chapter_en":"Ghusl for a Non-Muslim Upon Accepting Islam","part_en":"The Book of Ghusl","group_ar":"","group_en":"","part_no":5,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Qays ibn ʿĀṣim , may Allah be pleased with him, said: I came to the Prophet ﷺ intending to accept Islam, and he instructed me to perform ghusl with water and lote-tree leaves."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (355)، والترمذي (605)، والنسائي (188)."},{"num":1505,"demo":false,"sanad":"","matn":["عَنْ مُعَاذَةَ قَالَتْ: سَأَلْتُ عَائِشَةَ فَقُلْتُ: مَا بَالُ الْحَائِضِ تَقْضِي الصَّوْمَ وَلَا تَقْضِي الصَّلَاةَ ؟ فَقَالَتْ: أَحَرُورِيَّةٌ أَنْتِ ؟ قُلْتُ: لَسْتُ بِحَرُورِيَّةٍ، وَلَكِنِّي أَسْأَلُ، قَالَتْ: كَانَ يُصِيبُنَا ذَلِكَ فَنُؤْمَرُ بِقَضَاءِ الصَّوْمِ، وَلَا نُؤْمَرُ بِقَضَاءِ الصَّلَاةِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الحيض (321) عن همام، عن قتادة قال: حدثتني معاذة أن امرأةً قالت لعائشة: أتجزي إحدانا صلاتَها إذا طهرتْ؟ فقالت: أحرورية أنتِ؟ كنَّا نحيضُ مع النبي صلى الله عليه وسلم فلا يأمرنا به. أو قالت: فلا نفعله. ورواه مسلم في الحيض (335) عن حماد، عن يزيد الرِّشْك عن معاذة: أن امرأة سألت عائشة، فذكرت الحديث،","grade":"متفق عليه","chapter_ar":"باب ما جاء في سقوط الصلاة والصوم عن الحائض والنفساء، وتوقيت أربعين يومًا للنفساء","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (321) and Muslim (335).","chapter_en":"The Exemption of Menstruating and Postpartum Women from Prayer and Fasting, and the Forty-Day Period for Postpartum Bleeding","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Muʿādhah said: I asked ʿĀʾishah: “Why does a menstruating woman make up the fasts but does not make up the prayers?” She replied: “Are you a Ḥarūriyyah?” I said: “I am not a Ḥarūriyyah; I am only asking.” She said: “That used to happen to us, and we were commanded to make up the fasts, but we were not commanded to make up the prayers.”"]},"buhuth":{"en":["Her statement, “Are you a Ḥarūriyyah?” refers to the Ḥarūriyyah, a group of the Khawārij who settled at a village called Ḥarūrāʾ, where their first gathering and mutual pledge took place.","By asking, “Are you a Ḥarūriyyah?” ʿĀʾishah meant: “Are you from the Khawārij who require a menstruating woman to make up the prayers?”","Muʿādhah replied, “No, I am only asking,” meaning that she was asking solely to seek knowledge and not out of obstinate argumentation, and that she was not one of the Khawārij.","When ʿĀʾishah understood that she genuinely wished to learn, she answered her and confined the response to the transmitted evidence rather than giving a detailed legal rationale.","As for fixing the postpartum period at forty days, no hadith that can independently be relied upon has been firmly established concerning it. The strongest report narrated in this chapter concerning the matter is the following hadith of Umm Salamah."]},"intro_kitab":{"ar":["الحيض: هو الدم الذي يسيل من رحم المرأة في أيام معلومة في كل شهر. يقال: حاضت المرأة حيضًا: سال دم حيضها، وهي حائض، والجمع: حوائض وحُيَّض.","والمرأة تلجأ إلى معرفة دم الحيض من دم الاستحاضة بأحد طريقين:","الأول: أن تميِّز دم الحيض من دم الاستحاضة بصفاته.","والثاني: أن تعرف الحيض باعتبار عادتها المعروفة.","وإذا التبس الأمر ولم تستطع أن تميِّز بينهما فهي في حكم الحائض.","فإذا أقبل الحيض تركت الصلاة، وإذا أدبر اغتسلت وصلت.","وأما دم الاستحاضة فهو في حكم الحدث؛ فتتوضأ لكل صلاة، ولا تصلي بذلك الوضوء أكثر من فريضة مع رواتبها."],"en":["Menstruation is blood that flows from a woman’s womb on known, recurring days each month. It is said that a woman menstruates when her menstrual blood flows; she is then described as menstruating, and its plurals include ḥawāʾiḍ and ḥuyyaḍ.","A woman distinguishes menstrual blood from the blood of istiḥāḍah—irregular non-menstrual bleeding—by one of two methods:","First, by distinguishing menstrual blood from istiḥāḍah according to its characteristics.","Second, by identifying menstruation according to her established habitual cycle.","If the matter becomes confused and she is unable to distinguish between them, she is treated according to the ruling of a menstruating woman.","When menstruation begins, she leaves the prayer; when it ends, she performs ghusl and resumes praying.","As for istiḥāḍah, its blood is treated like a state requiring purification. She performs wuḍūʾ for each prayer and, with that wuḍūʾ, does not pray more than one obligatory prayer together with its associated regular Sunnah prayers."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4620],"tks":"متفق عليه: رواه البخاري (321)، ومسلم (335)."},{"num":1506,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: كَانَتِ النُّفَسَاءُ تَجْلِسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعِينَ يَوْمًا، فَكُنَّا نَطْلِي وُجُوهَنَا بِالْوَرْسِ مِنَ الْكَلَفِ."],"takhrij":"حسن: رواه أبو داود (311) والترمذي (139) وابن ماجه (698) كلهم من حديث علي بن عبد الأعلى، عن أبي سهل، عن مُسَّة الأزدية، عن أم سلمة، فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في سقوط الصلاة والصوم عن الحائض والنفساء، وتوقيت أربعين يومًا للنفساء","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (311), al-Tirmidhī (139), and Ibn Mājah (648).","chapter_en":"The Exemption of Menstruating and Postpartum Women from Prayer and Fasting, and the Forty-Day Period for Postpartum Bleeding","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Umm Salamah said: Women experiencing postpartum bleeding used to remain in that state for forty days during the time of the Messenger of Allah ﷺ, and we used to apply wars—a yellow plant dye—to our faces because of facial discoloration."]},"buhuth":{"en":["Al-Tirmidhī said in his Sunan that the scholars from among the Companions of the Prophet ﷺ, the Tābiʿūn, and those who came after them agreed that a woman experiencing postpartum bleeding leaves the prayer for forty days, unless she sees purity before that. If she becomes pure before forty days, she performs ghusl and prays.","Shaykh Ibn Bāz may Allah have mercy on him said:","“When she completes forty days, ghusl becomes obligatory upon her even if she has not seen purity, because forty days is the end of postpartum bleeding according to the sounder of the two scholarly opinions. Thereafter she should perform wuḍūʾ at the time of every prayer until the bleeding stops, just as the Prophet ﷺ instructed the woman experiencing istiḥāḍah. Her husband may also be intimate with her after forty days even if she has not seen purity, because blood continuing under these circumstances is irregular blood that does not prevent prayer or fasting and does not prevent the husband from intimacy with his wife. However, if the blood after forty days coincides with her normal menstrual period, she leaves prayer and fasting and regards it as menstruation.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (311)، والترمذي (139)، وابن ماجه (698)."},{"num":1507,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ الصِّدِّيقِ أَنَّهَا قَالَتْ: سَأَلَتِ امْرَأَةٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِحْدَانَا إِذَا أَصَابَ ثَوْبَهَا الدَّمُ مِنَ الْحَيْضَةِ كَيْفَ تَصْنَعُ ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَصَابَ ثَوْبَ إِحْدَاكُنَّ الدَّمُ مِنَ الْحَيْضَةِ فَلْتَقْرُصْهُ، ثُمَّ لِتَنْضَحْهُ بِمَاءٍ، ثُمَّ لِتُصَلِّي فِيهِ."],"takhrij":"متَّفقٌ عليه: رواه مالك في الطهارة (166 - رواية أبي مصعب الزهريّ) عن هشام بن عروة، عن فاطمة بنت المنذر بن الزبير (زوج هشام)، عن أسماء، فذكرت الحديث. ومن طريقه البخاري في الحيض (307) ومسلم في الطهارة (110).","grade":"متفق عليه","chapter_ar":"باب كيفية غسل دم الحيض من الثوب","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (166, through the narration of Abū Muṣʿab al-Zuhrī), al-Bukhārī (307), and Muslim (291).","chapter_en":"How Menstrual Blood Is Washed from Clothing","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr al-Ṣiddīq said: A woman asked the Messenger of Allah ﷺ: “O Messenger of Allah, if menstrual blood gets onto the garment of one of us, what should she do?” He said: “She should scrape it off, then rub it with water, then rinse or sprinkle it with water, and then pray in it.”"]},"buhuth":{"en":["In another narration of al-Bukhārī (227):","“She should scrape it off, then rub it with water, rinse or sprinkle it, and pray in it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (166، رواية أبي مصعب الزهري)، والبخاري (307)، ومسلم (110)."},{"num":1508,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَتْ إِحْدَانَا تَحِيضُ، ثُمَّ تَقْتَرِصُ الدَّمَ مِنْ ثَوْبِهَا عِنْدَ طُهْرِهَا فَتَغْسِلُهُ وَتَنْضَحُ عَلَى سَائِرِهِ، ثُمَّ تُصَلِّي فِيهِ.","وَفِي رِوَايَةِ: مَا كَانَ لِإِحْدَانَا إِلَّا ثَوْبٌ وَاحِدٌ تَحِيضُ فِيهِ، فَإِذَا أَصَابَهُ شَيْءٌ مِنْ دَمٍ، قَالَتْ: بِرِيقِهَا فَقَصَعَتْهُ بِظُفْرِهَا."],"takhrij":"صحيح: رواه البخاري في الحيض (308) من طريق عبدالرحمن بن القاسم، عن أبيه، عن عائشة.. فذكرتِ الحديثَ. والرواية الثانية في الحيض أيضاً (312) من طريق ابن أبي نجيحٍ، عن مجاهِِدٍ، قال: قالت عائشة.. فذكرتِ الحديثَ.","grade":"صحيح","chapter_ar":"باب كيفية غسل دم الحيض من الثوب","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (308); the second narration is also narrated by him (312).","chapter_en":"How Menstrual Blood Is Washed from Clothing","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿĀʾishah said: When one of us menstruated and then became pure, she would rub the blood from her garment with her fingertips, wash it, sprinkle water over the remainder of the garment, and then pray in it. In another narration: None of us possessed more than one garment in which she menstruated. If some menstrual blood got onto it, she would moisten the spot with her saliva and then scrape it with her fingernail."]},"buhuth":{"en":["In Sunan Abī Dāwūd (358): “She would moisten it with her saliva, then scrape it with her fingernail.”","Al-qaṣʿ means rubbing with the fingernail and pressing one thing against another.","Her statement “she would taqtariṣu the blood” means that she would wash it using the tips of her fingers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (308)، والرواية الثانية عنده أيضا bukhari(312)."},{"num":1509,"demo":false,"sanad":"","matn":["عَنْ أُمِّ قَيْسٍ بِنْتَ مِحْصَنٍ تَقُولُ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ دَمِ الْحَيْضِ يَكُونُ فِي الثَّوْبِ قَالَ: حُكِّيهِ بِضِلْعٍ وَاغْسِلِيهِ بِمَاءٍ وَسِدْرٍ."],"takhrij":"صحيح: رواه أبو داود (363) والنسائي (292) وابن ماجه (628) كلهم من طريق سفيان، عن ثابت بن هرمز أبي المِقْدام، عن عدي بن دينار، عن أم قيس، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب كيفية غسل دم الحيض من الثوب","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (363), al-Nasāʾī (292), and Ibn Mājah (628); authenticated by Ibn Khuzaymah (277).","chapter_en":"How Menstrual Blood Is Washed from Clothing","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Umm Qays bint Miḥṣan said: I asked the Prophet ﷺ about menstrual blood that gets onto a garment. He said: “Scrape it with a stick, and wash it with water and lote-tree leaves.”"]},"buhuth":{"en":["The word ḍilaʿ here refers to a stick or piece of wood.","Scraping here has the same meaning as removing the substance of the blood mentioned in the preceding hadith of Asmāʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (363)، والنسائي (292)، وابن ماجه (628)، وصححه ابن خزيمة (277)."},{"num":1510,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ خَوْلَةَ بِنْتَ يَسَارٍ أَتَتْ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ الله إِنَّهُ لَيْسَ لِي إِلَّا ثَوْبٌ وَاحِدٌ، وَأَنَا أَحِيضُ فِيهِ، فَكَيْفَ أَصْنَعُ؟ فَقَالَ:إِذَا طَهُرْتِ فَاغْسِلِيهِ ثُمَّ صَلِّي فِيهِ، فَقَالَتْ: فَإِنْ لَمْ يَخْرُجْ الدَّمُ قَالَ:يَكْفِيكِ الْمَاءُ، وَلَا يَضُرُّكِ أَثَرُهُ."],"takhrij":"حسن: رواه أبو داود (365)، وأحمد (8939) كلاهما عن قتيبة بن سعيد، حدثنا ابن لهيعة، عن يزيد بن أبي حبيب، عن عيسى بن طلحة، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب كيفية غسل دم الحيض من الثوب","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (365) and Aḥmad (8939).","chapter_en":"How Menstrual Blood Is Washed from Clothing","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah reported that Khawlah bint Yasār came to the Prophet ﷺ and said: “O Messenger of Allah, I have only one garment, and I menstruate in it. What should I do?” He said: “When you become pure, wash it and then pray in it.” She asked: “What if the blood does not come out completely?” He replied: “Water is sufficient for you, and its remaining trace will not harm you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (365)، وأحمد (8939)."},{"num":1511,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا كَانَتْ تَكُونُ حَائِضًا لَا تُصَلِّي وَهِيَ مُفْتَرِشَةٌ بِحِذَاءِ مَسْجِدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي عَلَى خُمْرَتِهِ، إِذَا سَجَدَ أَصَابَنِي بَعْضُ ثَوْبِهِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الحيض (333) ومسلم في الصلاة (513) كلاهما من طريق سليمان الشيباني، عن عبدالله بن شدَّادٍ قال: سمِعتُ خالتي ميمونةَ.. فذكرت الحديث. واللفظ للبخاري، وفي لفظ البخاري (379) ومسلمٍ:كان رسول الله صلى الله عليه وسلم يُصلِّي وأنا حذاءه، وأنا حائض، وربما أصابني ثوبه إذا سجد، قالت: وكان يصلي على الخمرة.","grade":"متفق عليه","chapter_ar":"باب المصلي يصيب ثوبه الحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (333) and Muslim (513).","chapter_en":"The Garment of a Person Praying Touching a Menstruating Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Maymūnah reported that she would be menstruating and therefore not praying while lying beside the place where the Messenger of Allah ﷺ was praying upon his khumrah. When he prostrated, part of his garment would touch her."]},"buhuth":{"ar":["وفي لفظ البخاري (٣٧٩) ومسلم:","«كان رسول الله ﷺ يصلي وأنا حذاءه، وأنا حائض، وربما أصابني ثوبه إذا سجد».","قالت: وكان يصلي على الخمرة."],"en":["In another wording narrated by al-Bukhārī (379) and Muslim:","“The Messenger of Allah ﷺ would pray while I was beside him and I was menstruating, and sometimes his garment would touch me when he prostrated.”","She said that he used to pray upon a khumrah, a small woven mat."]}},"tuhfa":{},"full":1,"rep":[2581],"tks":"متفق عليه: رواه البخاري (333)، ومسلم (513)."},{"num":1512,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ وَأَنَا إِلَى جَنْبِهِ، وَأَنَا حَائِضٌ، وَعَلَيَّ مِرْطٌ، وَعَلَيْهِ بَعْضُهُ إِلَى جَنْبِهِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (514) من حديث وكيع، ثنا طلحة بن يحيى، عن عبيد الله بن عبدالله، عن عائشة، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب المصلي يصيب ثوبه الحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (514).","chapter_en":"The Garment of a Person Praying Touching a Menstruating Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿĀʾishah, the wife of the Prophet ﷺ, said: The Prophet ﷺ would pray during the night while I was beside him and menstruating. I was wearing a mirṭ, and part of it was upon him beside me."]},"buhuth":{"en":["A mirṭ is a cloak or covering garment.","This report demonstrates the permissibility of praying while part of a garment is upon the person praying and another part is upon a menstruating woman or another person."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (514)."},{"num":1513,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ، أَنَّهُ سَأَلَ أُخْتَهُ أُمَّ حَبِيبَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي الثَّوْبِ الَّذِي يُجَامِعُهَا فِيهِ ؟ فَقَالَتْ: نَعَمْ، إِذَا لَمْ يَرَ فِيهِ أَذًى."],"takhrij":"صحيح: رواه أبو داود (366) والنسائي (294) وابن ماجه (540) كلهم من طريق الليث بن سعد، عن يزيد بن أبي حبيب، عن سُوَيد بن قيس، عن معاوية بن خُديج، عن معاوية بن أبي سفيان، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الصلاة في الثوب الذي يجامع أهله فيه","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (366), al-Nasāʾī (294), and Ibn Mājah (540); authenticated by Ibn Khuzaymah (276).","chapter_en":"Praying in the Garment Worn During Marital Relations","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Muʿāwiyah ibn Abī Sufyān asked his sister Umm Ḥabībah, the wife of the Prophet ﷺ: “Did the Prophet ﷺ pray in the garment in which he had marital relations with her?” She replied: “Yes, provided that he saw no impurity upon it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (366)، والنسائي (294)، وابن ماجه (540)، وصححه ابن خزيمة (276)."},{"num":1514,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُصَلِّي فِي شُعُرِنَا أَوْ فِي لُحُفِنَا."],"takhrij":"صحيح: رواه أبو داود (367) والترمذي (600) والنسائي (5366) كلهم من طريق أشعث بن عبد الملك، عن محمد بن سيرين، عن عبدالله بن شقيق، عن عائشة، واللفظ لأبي داود، ولفظ الترمذي:لا يصلي في لُحف نسائه، ولفظ النسائي:لا يصلي في لُحفنا، قال سفيان بن حبيب:ملاحفنا.","grade":"صحيح","chapter_ar":"باب كراهة الصلاة في شُعُر النساء","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (367), al-Tirmidhī (600), and al-Nasāʾī (5366). This wording is that of Abū Dāwūd.","chapter_en":"The Dislike of Praying in Women’s Garments or Coverings","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿĀʾishah said: The Messenger of Allah ﷺ would not pray in our garments, or in our blankets."]},"buhuth":{"en":["Al-Tirmidhī’s wording is:","“He would not pray in the blankets of his wives.”","Al-Nasāʾī’s wording is:","“He would not pray in our blankets.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (367)، والترمذي (600)، والنسائي (5366)، واللفظ لأبي داود."},{"num":1515,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كُنْتُ أَشْرَبُ وَأَنَا حَائِضٌ، ثُمَّ أُنَاوِلُهُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَضَعُ فَاهُ عَلَى مَوْضِعِ فِيَّ، فَيَشْرَبُ، وَأَتَعَرَّقُ الْعَرْقَ وَأَنَا حَائِضٌ، ثُمَّ أُنَاوِلُهُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَضَعُ فَاهُ عَلَى مَوْضِعِ فِيَّ."],"takhrij":"صحيح: رواه مسلم في الحيض (300) من طريق المِقدامِ بنِ شريحٍ، عن أبيه، عن عائشةَ .. فذكرته.","grade":"صحيح","chapter_ar":"باب طهارة سؤر الحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (300).","chapter_en":"The Purity of the Leftovers of a Menstruating Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿĀʾishah said: I would drink while menstruating and then hand the vessel to the Prophet ﷺ. He would place his mouth upon the same spot where my mouth had been and drink. I would also eat meat from a bone while menstruating and then hand it to the Prophet ﷺ, and he would place his mouth upon the same spot where my mouth had been."]},"buhuth":{"en":["In Sunan Abī Dāwūd (259):","“I used to eat meat from a bone while menstruating and then give it to the Prophet ﷺ, and he would place his mouth upon the same place where I had placed mine.”","Al-ʿarq is a bone upon which some meat remains.","Her expression “ataʿarraqu” means that she would remove the meat remaining upon the bone with her teeth.","Al-Khaṭṭābī said: “Her expression ataʿarraqu—with a fatḥah on the ʿayn and a sukūn on the rāʾ—means that she takes the meat from the bone with her teeth. It is a bone from which most of the meat has been removed while some remains upon it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6301],"tks":"صحيح: رواه مسلم (300)."},{"num":1516,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ سَعْدٍ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ مُؤَاكَلَةِ الْحَائِضِ ؟ فَقَالَ: وَاكِلْهَا."],"takhrij":"حسن: رواه أبو داود (212) والترمذي (133) وابن ماجه (651) كلهم من حديث العلاء بن الحارث، عن حرام بن حكيم، عن عمه عبدالله بن سعد، فذكر الحديث. وهذا لفظ الترمذي وابن ماجه. وقال الترمذي: حسن غريب.","grade":"حسن","chapter_ar":"باب ما جاء في مؤاكلة الحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (212), al-Tirmidhī (133), and Ibn Mājah (651).","chapter_en":"Eating with a Menstruating Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Saʿd said: I asked the Prophet ﷺ about eating together with a menstruating woman. He said: “Eat with her.”"]},"buhuth":{"en":["This is the wording of al-Tirmidhī and Ibn Mājah. Al-Tirmidhī said: “Ḥasan gharīb.”","In Abū Dāwūd’s narration, it is reported from his uncle that he asked the Messenger of Allah ﷺ:","“What is lawful for me with my wife while she is menstruating?”","He replied:","“You may have what is above the waist-wrapper.”","The narration also mentions eating with a menstruating woman."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (212)، والترمذي (133)، وابن ماجه (651)."},{"num":1517,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ بِنْتَ أُمِّ سَلَمَةَ حَدَّثَتْهُ، أَنَّ أُمَّ سَلَمَةَ حَدَّثَتْهَا قَالَتْ: بَيْنَا أَنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُضْطَجِعَةٌ فِي خَمِيصَةٍ، إِذْ حِضْتُ فَانْسَلَلْتُ فَأَخَذْتُ ثِيَابَ حِيضَتِي قَالَ: أَنُفِسْتِ ؟ قُلْتُ: نَعَمْ، فَدَعَانِي فَاضْطَجَعْتُ مَعَهُ فِي الْخَمِيلَةِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الحيض (298) واللفظ له، ومسلم في الحيض (296) كلاهما من حديث هشام الدستوائي، عن يحيى بن أبي كثير، عن أبي سلمة ابن عبدالرحمن أن زينب بنت أم سلمة، فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب الاضطجاع مع الحائض في لحاف واحد","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (298), whose wording this is, and Muslim (296).","chapter_en":"Lying with a Menstruating Woman under One Covering","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Zaynab bint Umm Salamah reported that Umm Salamah told her: While I was lying with the Messenger of Allah ﷺ under a khamīṣah, I began menstruating. I slipped away and put on the clothes I used during menstruation. He asked: “Have you begun menstruating?” I replied: “Yes.” He then called me, and I lay down with him under the same covering."]},"buhuth":{"en":["In a narration of Ibn Mājah (637), the Messenger of Allah ﷺ said to her:","“Come and enter beneath the covering with me.”","A khamīṣah is a black garment with markings or stripes, made from wool or another material.","A khamīlah is a cloth possessing a raised nap or fringe."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (298)، واللفظ له، ومسلم (296)."},{"num":1518,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَضْطَجِعُ مَعِي وَأَنَا حَائِضٌ، وَبَيْنِي وَبَيْنَهُ ثَوْبٌ."],"takhrij":"صحيح: رواه مسلم في الحيض (295) من طريق ابن وهبٍ، أخبرني مخرمة، عن أبيه، عن كريب مولى ابن عبَّاسٍ، قال: سمعت ميمونة.. فذكرتِ الحديثَ.","grade":"صحيح","chapter_ar":"باب الاضطجاع مع الحائض في لحاف واحد","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (295).","chapter_en":"Lying with a Menstruating Woman under One Covering","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Maymūnah, the Mother of the Believers, said: The Messenger of Allah ﷺ would lie with me while I was menstruating, with a cloth between me and him."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (295)."},{"num":1519,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كُنْتُ أَنَا وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيتُ فِي الشِّعَارِ الْوَاحِدِ وَأَنَا حَائِضٌ طَامِثٌ، فَإِنْ أَصَابَهُ مِنِّي شَيْءٌ غَسَلَ مَكَانَهُ وَلَمْ يَعْدُهُ، ثُمَّ صَلَّى فِيهِ، وَإِنْ أَصَابَ تَعْنِي ثَوْبَهُ مِنْهُ شَيْءٌ، غَسَلَ مَكَانَهُ وَلَمْ يَعْدُهُ، ثُمَّ صَلَّى فِيهِ."],"takhrij":"حسن: رواه أبو داود (269) واللفظ له، والنسائي (284، 372) كلاهما من طريق يحيى (وهو ابن سعيد)، عن جابر بن صُبْح قال: سمعت حِلاساً الهجري قال: سمعتُ عائشة، فذكرت الحديث.","grade":"حسن","chapter_ar":"باب الاضطجاع مع الحائض في لحاف واحد","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (269), whose wording this is, and al-Nasāʾī (284, 372).","chapter_en":"Lying with a Menstruating Woman under One Covering","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿĀʾishah said: The Messenger of Allah ﷺ and I would spend the night beneath the same close covering while I was menstruating. If anything from me got onto him, he would wash that spot only and would not wash beyond it, then he would pray. If anything got onto his garment, he would likewise wash that particular spot and not go beyond it, then pray in the garment."]},"buhuth":{"en":["In al-Nasāʾī’s wording:","“Then he would return; if anything from me touched him, he would do the same, not go beyond that spot, and pray in it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (269)، واللفظ له، والنسائي (284، 372)."},{"num":1520,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَيْسَرَةَ قَالَ: قَالَتْ أُمُّ الْمُؤْمِنِينَ: كُنْتُ أَتَّزِرُ وَأَنَا حَائِضٌ، ثُمَّ أَدْخُلُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي لِحَافِهِ."],"takhrij":"صحيح: رواه الدارمي (1088)، والبيهقي (1508) كلاهما من طريق شعبة، عن أبي إسحاق، عن أبي ميسرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب الاضطجاع مع الحائض في لحاف واحد","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Dārimī (1088) and al-Bayhaqī (1/314).","chapter_en":"Lying with a Menstruating Woman under One Covering","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abū Maysarah reported that the Mother of the Believers said: I would put on a waist-wrapper while menstruating and then enter beneath the covering with the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الدارمي (1088)، والبيهقي (1508)."},{"num":1521,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَتْ إِحْدَانَا إِذَا كَانَتْ حَائِضًا فَأَرَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُبَاشِرَهَا أَمَرَهَا أَنْ تَتَّزِرَ فِي فَوْرِ حَيْضَتِهَا، ثُمَّ يُبَاشِرُهَا قَالَتْ: وَأَيُّكُمْ يَمْلِكُ إِرْبَهُ كَمَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْلِكُ إِرْبَهُ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الحيض (302) ومسلم في الحيض (293) كلاهما من طريق علي بن مسهر، قال: أخبرنا أبو إسحاق، وهو الشيباني، عن عبدالرحمن بن الأسود، عن أبيه، عن عائشة فذكرت.","grade":"متفق عليه","chapter_ar":"باب مباشرة الحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (302) and Muslim (293).","chapter_en":"Intimacy with a Menstruating Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["The Mother of the Believers ʿĀʾishah said: When one of us was menstruating and the Messenger of Allah ﷺ wished to have intimate physical contact with her, he would instruct her to wear a waist-wrapper during the height of her menstruation and would then be intimate with her. She said: “Which of you can control his desire as the Messenger of Allah ﷺ was able to control his desire?”"]}},"tuhfa":{},"full":1,"rep":[6367],"tks":"متفق عليه: رواه البخاري (302)، ومسلم (293)."},{"num":1522,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يُبَاشِرَ امْرَأَةً مِنْ نِسَائِهِ أَمَرَهَا فَاتَّزَرَتْ وَهِيَ حَائِضٌ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الحيض (303) ومسلم في الحيض (294) كلاهما من حديث الشيباني، عن عبدالله بن شدَّاد، قال: سمعت ميمونة قالت. وفي رواية مسلم: كان يُباشِر نساءَه فوقَ الإزار وهن حُيّض.","grade":"متفق عليه","chapter_ar":"باب مباشرة الحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (303) and Muslim (294).","chapter_en":"Intimacy with a Menstruating Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Maymūnah said: When the Messenger of Allah ﷺ wished to have intimate physical contact with one of his wives while she was menstruating, he would instruct her to wear a waist-wrapper."]},"buhuth":{"ar":["وفي رواية مسلم: «كان يباشر نساءه فوق الإزار وهن حُيَّض»."],"en":["In Muslim’s narration:","“He would have intimate physical contact with his wives above the waist-wrapper while they were menstruating.”"]}},"tuhfa":{},"full":1,"rep":[6368],"tks":"متفق عليه: رواه البخاري (303)، ومسلم (294)."},{"num":1523,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ الْيَهُودَ كَانُوا إِذَا حَاضَتِ الْمَرْأَةُ فِيهِمْ لَمْ يُؤَاكِلُوهَا وَلَمْ يُجَامِعُوهُنَّ فِي الْبُيُوتِ، فَسَأَلَ أَصْحَابُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَنْزَلَ اللَّهُ تَعَالَى: ﴿وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ﴾ [البقرة: 222] إِلَى آخِرِ الآيَةِ ،فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اصْنَعُوا كُلَّ شَيْءٍ إِلَّا النِّكَاحَ، فَبَلَغَ ذَلِكَ الْيَهُودَ فَقَالُوا: مَا يُرِيدُ هَذَا الرَّجُلُ أَنْ يَدَعَ مِنْ أَمْرِنَا شَيْئًا إِلَّا خَالَفَنَا فِيهِ، فَجَاءَ أُسَيْدُ بْنُ حُضَيْرٍ وَعَبَّادُ بْنُ بِشْرٍ فَقَالَا: يَا رَسُولَ اللَّهِ! إِنَّ الْيَهُودَ تَقُولُ: كَذَا وَكَذَا، فَلَا نُجَامِعُهُنَّ؟ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى ظَنَنَّا أَنْ قَدْ وَجَدَ عَلَيْهِمَا، فَخَرَجَا فَاسْتَقْبَلَهُمَا هَدِيَّةٌ مِنْ لَبَنٍ إِلَى النَّبِيّِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَرْسَلَ فِي آثَارِهِمَا فَسَقَاهُمَا فَعَرَفَا أَنْ لَمْ يَجِدْ عَلَيْهِمَا."],"takhrij":"صحيح: رواه مسلم في الحيض (302) من طريق ابن مهدي، حدَّثنا حمَّاد بن سلمة، ثنا ثابت، عن أنسٍ.. فذكره.","grade":"صحيح","chapter_ar":"باب مباشرة الحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (302).","chapter_en":"Intimacy with a Menstruating Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas reported: When a woman among the Jews menstruated, they would not eat with her and would not associate with menstruating women in their homes. The Companions of the Prophet ﷺ asked the Prophet ﷺ about this, so Allah Most High revealed: “They ask you concerning menstruation. Say: It is harm, so keep away from women during menstruation and do not approach them until they become pure. When they have purified themselves, then approach them from where Allah has commanded you. Indeed, Allah loves those who constantly repent and loves those who purify themselves.” [Sūrat al-Baqarah 2:222] The Messenger of Allah ﷺ said: “Do everything except intercourse.” When this reached the Jews, they said: “This man does not wish to leave anything from our practices without opposing us concerning it.” Then Usayd ibn Ḥuḍayr and ʿAbbād ibn Bishr came and said: “O Messenger of Allah, the Jews say such-and-such. Should we then have intercourse with them?” The face of the Messenger of Allah ﷺ changed until we thought that he had become angry with them. They left, and a gift of milk intended for the Prophet ﷺ met them on their way. He sent someone after them and gave them the milk to drink, so they understood that he had not been angry with them."]},"buhuth":{"en":["The statement “they would not associate with them in the houses” means that they would avoid normal household association with menstruating women.","The first occurrence of “al-maḥīḍ” refers to menstrual blood, while the second refers to the period of menstruation.","“Except intercourse” means sexual intercourse.","The expression “he had found something against them” means that he had become angry with them, while “he had not found anything against them” means that he was not angry with them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (302)."},{"num":1524,"demo":false,"sanad":"","matn":["عَنْ عِكْرِمَةَ، عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ مِنَ الْحَائِضِ شَيْئًا، أَلْقَى عَلَى فَرْجِهَا ثَوْبًا."],"takhrij":"صحيح: رواه أبو داود (272) قال: حدَّثنا موسى بن إسماعيل، ثنا حماد، عن أيوب، عن عكرمة، فذكر مثله. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب مباشرة الحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (272).","chapter_en":"Intimacy with a Menstruating Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["One of the wives of the Prophet ﷺ reported that when the Prophet ﷺ wished for intimate contact with a menstruating woman, he would place a cloth over her private area."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (272)."},{"num":1525,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ: كُنْتُ أُرَجِّلُ رَأْسَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا حَائِضٌ.","وَفِي رِوَايَةِ: عَنْ عُرْوَةَ، أَنَّهُ سُئِلَ أَتَخْدُمُنِي الْحَائِضُ أَوْ تَدْنُو مِنِّي الْمَرْأَةُ وَهِيَ جُنُبٌ ؟ فَقَالَ عُرْوَةُ: كُلُّ ذَلِكَ عَلَيَّ هَيِّنٌ، وَكُلُّ ذَلِكَ تَخْدُمُنِي وَلَيْسَ عَلَى أَحَدٍ فِي ذَلِكَ بَأْسٌ، أَخْبَرَتْنِي عَائِشَة \" أَنَّهَا كَانَتْ تُرَجِّلُ تَعْنِي رَأْسَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ حَائِضٌ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَئِذٍ مُجَاوِرٌ فِي الْمَسْجِدِ يُدْنِي لَهَا رَأْسَهُ وَهِيَ فِي حُجْرَتِهَا، فَتُرَجِّلُهُ وَهِيَ حَائِضٌ."],"takhrij":"متَّفقٌ عليه: أخرج الرواية الأُولى مالك في الطهارة (102) عن هشام بن عروة، عن أبيه، عن عائشة، ومن طريقه البخاري في الحيض (295). ورواه مسلم في الحيض (297) من حديث أبي خيثمة، عن هشام به، وفيه: يُدني إليَّ رأسَه وأنا في حُجْرتي، فأُرَجِّلُ رأسه وأنا حائض. والرواية الثانية أخرجها البخاري (296). وفي رواية: أنها كانت ترجّل النبي صلى الله عليه وسلم وهي حائض، وهو مُعتكِفٌ في المسجد، وهي في حجرتها، يناولها رأسه. وسيأتي في كتاب الصوم، باب الاعتكاف.","grade":"متفق عليه","chapter_ar":"باب جواز ترجيل الحائض رأس زوجها","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (102), al-Bukhārī (295), and Muslim (297).","chapter_en":"The Permissibility of a Menstruating Woman Combing Her Husband’s Hair","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, said: I used to comb the hair of the Messenger of Allah ﷺ while I was menstruating. In another narration, ʿUrwah was asked: “May a menstruating woman serve me, or may a woman in a state of janābah come near me?”","ʿUrwah replied: “That is easy for me. Any of them may serve me, and there is no harm in any of that. ʿĀʾishah informed me that the Messenger of Allah ﷺ would be in the mosque while she was in her chamber. He would bring his head close to her, and she would comb his hair while she was menstruating.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: أخرجه مالك (102)، والبخاري (295)، ورواه مسلم (297)."},{"num":1526,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَّكِئُ فِي حَجْرِي وَأَنَا حَائِضٌ، ثُمَّ يَقْرَأُ الْقُرْآنَ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الحيض (297) ومسلم في الحيض (301) كلاهما من حديث منصور بن صفية، عن أمه صفية، عن عائشة، فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب قراءة الرجل في حجر امرأته وهي حائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (297) and Muslim (301).","chapter_en":"A Man Reciting While Resting in His Wife’s Lap When She Is Menstruating","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿĀʾishah reported that the Prophet ﷺ would recline in my lap while I was menstruating and then recite the Qurʾān."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (297)، ومسلم (301)."},{"num":1527,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَاوِلِينِي الْخُمْرَةَ مِنَ الْمَسْجِدِ، قَالَتْ فَقُلْتُ: إِنِّي حَائِضٌ، فَقَالَ: إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ."],"takhrij":"صحيح: رواه مسلم في الحيض (298) من حديث الأعمش، عن ثابت بن عبيد، عنِ القاسم بن محمد، عن عائشة.. فذكرته .","grade":"صحيح","chapter_ar":"باب تناول الحائض شيئًا من المسجد","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (298).","chapter_en":"A Menstruating Woman Handing Something from the Mosque","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿĀʾishah said: The Messenger of Allah ﷺ said to me: “Hand me the small prayer mat from the mosque.” I said: “I am menstruating.” He said: “Your menstruation is not in your hand.”"]},"buhuth":{"en":["Regarding her words “from the mosque,” Abū al-ʿAbbās al-Qurṭubī said in al-Mufhim (1/558) that the scholars differed concerning what this phrase is grammatically connected to.","Some connected it to the command “hand it to me,” and used the report as evidence that a menstruating woman may enter the mosque when a need arises.","Others understood the phrase as connected to the location of the Prophet ﷺ, meaning: “He said to me while he was inside the mosque: ‘Hand me the small prayer mat.’” On this interpretation, the words occur in an altered order. This supports the well-known position among the jurists that a menstruating woman does not enter the mosque, whether to remain there or merely to pass through.","The second interpretation is supported by the following report of Abū Hurayrah. That is, the Prophet ﷺ said this to her while he was in the mosque so that she could hand the item to him from outside the mosque; he did not order her to enter the mosque and remove it. He was in iʿtikāf, while ʿĀʾishah was in her chamber and menstruating.","The statement of the Prophet ﷺ, “Your menstruation is not in your hand,” indicates that she feared only putting her hand into the mosque. Had she been instructed to enter the mosque herself, there would have been no particular reason to specify her hand. This was stated by al-Qāḍī ʿIyāḍ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (298)."},{"num":1528,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: بَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، فَقَالَ: يَا عَائِشَةُ، نَاوِلِينِي الثَّوْبَ، فَقَالَتْ: إِنِّي حَائِضٌ، فَقَالَ: إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ، فَنَاوَلَتْهُ."],"takhrij":"صحيح: رواه مسلم في الحيض (299) من طريق يحيى بن سعيد، عن يزيد بن كيسان، عن أبي حازمٍ، عن أبي هريرة.. فذكر الحديث.","grade":"صحيح","chapter_ar":"باب تناول الحائض شيئًا من المسجد","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (299).","chapter_en":"A Menstruating Woman Handing Something from the Mosque","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah reported: While the Messenger of Allah ﷺ was in the mosque, he said: “O ʿĀʾishah, hand me the garment.” She said: “I am menstruating.” He replied: “Your menstruation is not in your hand.” So she handed it to him."]},"buhuth":{"en":["Regarding the pronunciation of the expression “your menstruation,” the hadith scholars read it with the vowel indicating the menstrual blood. Al-Khaṭṭābī held that the correct reading is the form referring to the state of menstruation. Al-Qāḍī ʿIyāḍ regarded the reading of the hadith scholars as stronger. This differs from the narration of Umm Salamah, “I took the clothes of my menstruation,” where the reading referring to the state of menstruation is the correct one."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (299)."},{"num":1529,"demo":false,"sanad":"","matn":["عَنْ مُعَاذَةَ، أَنَّ امْرَأَةً سَأَلَتْ عَائِشَةَ قَالَتْ: تَخْتَضِبُ الْحَائِضُ؟ فَقَالَتْ: قَدْ كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَخْتَضِبُ فَلَمْ يَكُنْ يَنْهَانَا عَنْهُ."],"takhrij":"صحيح: رواه ابن ماجه (656) قال: حدَّثنا محمد بن يحيى، ثنا حجاج، ثنا يزيد بن إبراهيم، ثنا أيوب، عن معاذة.","grade":"صحيح","chapter_ar":"باب جواز الاختضاب للحائض","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (656).","chapter_en":"The Permissibility of a Menstruating Woman Applying Dye","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Muʿādhah reported that a woman asked ʿĀʾishah: “May a menstruating woman apply dye?” She replied: “We used to be with the Prophet ﷺ while applying dye, and he did not forbid us from doing so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (656)."},{"num":1530,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَتَى حَائِضًا أَوِ امْرَأَةً فِي دُبُرِهَا أَوْ كَاهِنًا، فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ."],"takhrij":"حسن: رواه أبو داود (3904) والترمذي (135) واللفظ له، وابن ماجه (639) كلهم من طريق حماد بن سلمة، عن حكيم الأثرم، عن أبي تميمة، عن أبي هريرة. وزاد أبو داود وابن ماجه بعد قوله:كاهنا:فصدّقه بما يقول.","grade":"حسن","chapter_ar":"باب النهي عن إتيان الحائض وعن إتيان المرأة في دبرها","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (3904), al-Tirmidhī (135), whose wording this is, and Ibn Mājah (639).","chapter_en":"The Prohibition of Intercourse with a Menstruating Woman and of Anal Intercourse with a Woman","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever has intercourse with a menstruating woman, or has intercourse with a woman in her anus, or goes to a soothsayer, has disbelieved in what was revealed to Muḥammad ﷺ.”"]},"buhuth":{"en":["Abū Dāwūd and Ibn Mājah add after the words “or a soothsayer”:","“and believes what he says.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3904)، والترمذي (135)، واللفظ له، وابن ماجه (639)."},{"num":1531,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ قَالَتْ: كُنَّا لَا نَعُدُّ الْكُدْرَةَ وَالصُّفْرَةَ شَيْئًا."],"takhrij":"صحيح: رواه البخاري في الحيض (326) عن قتيبة، ثنا إسماعيل، عن أيوب، عن محمد، عن أمِّ عطيَّة.. فذكرته.","grade":"صحيح","chapter_ar":"باب المرأة ترى الكدرة والصفرة بعد الطهر","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (326).","chapter_en":"A Woman Seeing Brownish or Yellowish Discharge after Becoming Pure","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Umm ʿAṭiyyah said: “We did not regard brownish or yellowish discharge as anything.”"]},"buhuth":{"en":["In Sunan Abī Dāwūd (307): “We did not regard brownish or yellowish discharge after purity as anything,” and Umm ʿAṭiyyah was among those who had pledged allegiance to the Prophet ﷺ.","Al-Bukhārī titled the chapter: “Yellowish and brownish discharge outside the days of menstruation.” His intent is that such discharge during the days of menstruation is treated as menstruation. This reconciles the report with the statement of ʿĀʾishah may Allah be pleased with her: “Do not be hasty until you see the white discharge.” Women used to send ʿĀʾishah a small container containing cotton marked with yellow traces from menstrual blood, asking her about prayer. She would tell them: “Do not be hasty until you see the white discharge,” meaning the sign that menstruation had ended. Mālik narrated this in al-Ṭahārah (97).","The “white discharge” (al-qaṣṣah al-bayḍāʾ) is the recognized sign of purity: the cotton comes out white and clean, with no yellow trace mixed with it. This indicates that yellowish or brownish discharge during the days of menstruation is treated as menstruation, whereas after established purity it is treated as purity.","Her statement, “We did not regard,” means during the lifetime of the Prophet ﷺ, so it carries the ruling of a report attributed to him; this is the approach followed by al-Bukhārī.","The expressions “brownish discharge” and “yellowish discharge” refer to fluid resembling pus with a yellowish coloration.","There is no fixed maximum duration for menstruation; rather, the matter is referred back to a woman’s established pattern. A common duration is six or seven days, based on the forthcoming hadith of Ḥamnah bint Jaḥsh, in which the Prophet ﷺ says: “Consider yourself menstruating for six or seven days.” This applies to a woman who cannot distinguish the blood and has no established habitual cycle.","Otherwise, menstrual blood is generally dark and has an unpleasant odor, whereas the blood of istiḥāḍah is generally red and without such an odor. It flows from the womb and may occur during days that would otherwise be menstrual days or during days of purity.","A woman experiencing istiḥāḍah is treated, in general, according to the rulings of purity.","It is also stated in an authentic report that istiḥāḍah is “a blow from Satan,” referring to the disturbance connected with this bleeding."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (326)."},{"num":1532,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ: قَالَتْ فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ: يَا رَسُولَ اللَّهِ! إِنِّي لَا أَطْهُرُ أَفَأَدَعُ الصَّلَاةَ ؟ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا ذَلِكَ عِرْقٌ، وَلَيْسَتْ بِالْحَيْضَةِ، فَإِذَا أَقْبَلَتِ الْحَيْضَةُ فَاتْرُكِي الصَّلَاةَ، فَإِذَا ذَهَبَ قَدْرُهَا فَاغْسِلِي الدَّمَ عَنْكِ وَصَلِّي."],"takhrij":"متَّفقٌ عليه: رواه مالك في الطهارة (104) عن هشام بن عروة، عن أبيه، عن عائشة، ومن طريقه البخاري في الحيض (306) ومسلم في الحيض (333). ورواه البخاري أيضاً مختصراً في الحيض (331) ولفظه:إذا أقبلت الحيضة فدعي الصلاة، وإذا أدبرت فاغسلي عنك الدم وصلّي، وهو مختصر من قصة فاطمة المذكورة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غسل المستحاضة وصلاتها وغشيان زوجها","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (104), al-Bukhārī (306), and Muslim (333).","chapter_en":"What Has Been Reported Concerning the Ghusl of a Woman with Istiḥāḍah, Her Prayer, and Her Husband Having Marital Relations with Her","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿĀʾishah, the wife of the Prophet ﷺ, reported that Fāṭimah bint Abī Ḥubaysh said: “O Messenger of Allah, I do not become pure. Should I stop praying?” The Messenger of Allah ﷺ said to her: “That is only a vein; it is not menstruation. When menstruation begins, leave the prayer. When its usual duration has passed, wash the blood from yourself and pray.”"]},"buhuth":{"ar":["ورواه البخاري أيضًا مختصرًا (٣٣)، ولفظه:","«إِذَا أَقْبَلَتِ الْحَيْضَةُ فَدَعِي الصَّلَاةَ، وَإِذَا أَدْبَرَتْ فَاغْسِلِي عَنْكِ الدَّمَ وَصَلِّي»."],"en":["Al-Bukhārī also narrated a shorter wording (33):","“When menstruation begins, leave the prayer; and when it ends, wash the blood from yourself and pray.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (104)، والبخاري (306)، ومسلم (333)."},{"num":1533,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ امْرَأَةً كَانَتْ تُهَرَاقُ الدِّمَاءَ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَفْتَتْ لَهَا أُمُّ سَلَمَةَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لِتَنْظُرْ إِلَى عَدَدِ اللَّيَالِي وَالْأَيَّامِ الَّتِي كَانَتْ تَحِيضُهُنَّ مِنَ الشَّهْرِ قَبْلَ أَنْ يُصِيبَهَا الَّذِي أَصَابَهَا، فَلْتَتْرُكِ الصَّلَاةَ قَدْرَ ذَلِكَ مِنَ الشَّهْرِ، فَإِذَا خَلَّفَتْ ذَلِكَ فَلْتَغْتَسِلْ ثُمَّ لِتَسْتَثْفِرْ بِثَوْبٍ، ثُمَّ لِتُصَلِّي."],"takhrij":"صحيح: رواه مالك في الطهارة (105) عن نافع، عن سليمان بن يسار، عن أم سلمة. ومن طريق مالك رواه أبو داود (274) والنسائي (355).","grade":"صحيح","chapter_ar":"باب ما جاء في غسل المستحاضة وصلاتها وغشيان زوجها","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (105), Abū Dāwūd (274), al-Nasāʾī (354, 355), and Ibn Mājah (623).","chapter_en":"What Has Been Reported Concerning the Ghusl of a Woman with Istiḥāḍah, Her Prayer, and Her Husband Having Marital Relations with Her","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, reported that a woman experienced continuous heavy bleeding during the time of the Messenger of Allah ﷺ. Umm Salamah sent a question to the Messenger of Allah ﷺ on her behalf, and he said: “Let her consider the number of nights and days during which she used to menstruate each month before this condition afflicted her. Let her refrain from prayer for that same amount of time each month. When that period has passed, let her perform ghusl, fasten a cloth securely to contain the bleeding, and then pray.”"]},"buhuth":{"en":["Al-istithfār means fastening a cloth securely around oneself so that it holds the place of the bleeding and prevents the blood from flowing out."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (105)، وأبو داود (274)، والنسائي (354، 355)، وابن ماجه (623)."},{"num":1534,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: اسْتَفْتَتْ أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنِّي أُسْتَحَاضُ، فَقَالَ: إِنَّمَا ذَلِكِ عِرْقٌ، فَاغْتَسِلِي، ثُمَّ صَلِّي.","فَكَانَتْ تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ.","قَالَ اللَّيْثُ بْنُ سَعْدٍ: لَمْ يَذْكُرْ ابْنُ شِهَابٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَمَرَ أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ، أَنْ تَغْتَسِلَ عِنْدَ كُلِّ صَلَاةٍ، وَلَكِنَّهُ شَيْءٌ فَعَلَتْهُ هِيَ.","وَفِي رِوَايَةِ: اسْتُحِيضَتْ سَبْعَ سِنِينَ، فَاسْتَفْتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ هَذِهِ لَيْسَتْ بِالْحَيْضَةِ وَلَكِنَّ هَذَا عِرْقٌ، فَاغْتَسِلِي وَصَلِّي.","قَالَتْ عَائِشَةُ: فَكَانَتْ تَغْتَسِلُ فِي مِرْكَنٍ فِي حُجْرَةِ أُخْتِهَا زَيْنَبَ بِنْتِ جَحْشٍ، حَتَّى تَعْلُوَ حُمْرَةُ الدَّمِ الْمَاءَ.","قَالَ ابْنُ شِهَابٍ: فَحَدَّثْتُ بِذَلِكَ أَبَا بَكْرِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ، فَقَالَ: يَرْحَمُ اللَّهُ هِنْدًا، لَوْ سَمِعَتْ بِهَذِهِ الْفُتْيَا، وَاللَّهِ إِنْ كَانَتْ لَتَبْكِي، لِأَنَّهَا كَانَتْ لَا تُصَلِّي.","وَفِي رِوَايَةِ: فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: امْكُثِي قَدْرَ مَا كَانَتْ تَحْبِسُكِ حَيْضَتُكِ، ثُمَّ اغْتَسِلِي وَصَلِّي."],"takhrij":"متَّفقٌ عليه: هذه الروايات كلها أخرجها مسلم في الحيض (334)، ورواه البخاري في الحيض (327) مختصراً: أن أم حبيبة اُستحيضت سبع سنين، فسألت رسول الله صلى الله عليه وسلم عن ذلك، فأمرها أن تغتسل وقال:هذا عرق، فكانت تغتسل لكل صلاة.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن المستحاضة تغتسل لكل صلاة","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: These narrations are recorded by Muslim (334), while al-Bukhārī narrated a shorter version (327).","chapter_en":"What Has Been Reported That a Woman with Istiḥāḍah Performs Ghusl for Every Prayer","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿĀʾishah said: Umm Ḥabībah bint Jaḥsh, who was married to ʿAbd al-Raḥmān ibn ʿAwf, sought a ruling from the Messenger of Allah ﷺ and said: “I experience istiḥāḍah.” He said: “That is only a vein. Perform ghusl and then pray.”","She thereafter used to perform ghusl for every prayer.","Al-Layth ibn Saʿd said: Ibn Shihāb al-Zuhrī did not mention that the Messenger of Allah ﷺ commanded Umm Ḥabībah bint Jaḥsh to perform ghusl for every prayer. Rather, that was something she herself chose to do.","In another narration, she experienced istiḥāḍah for seven years and sought a ruling from the Messenger of Allah ﷺ. He said:","“This is not menstruation; rather, it is a vein. So perform ghusl and pray.” ʿĀʾishah said: She would perform ghusl in a large basin in the chamber of her sister Zaynab bint Jaḥsh, until the redness of the blood would rise and color the water.","In another narration, the Messenger of Allah ﷺ said to her: “Remain without prayer for the length of time that your menstruation used to prevent you from praying; then perform ghusl and pray.”"]},"buhuth":{"en":["In Abū Dāwūd (281): “He commanded her to leave the prayer during the days of her menstrual periods.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: هذه الروايات في مسلم (334)، وروى البخاري مختصرا (327)."},{"num":1535,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ قَالَ، حَدَّثَتْنِي فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ، أَنَّهَا أَمَرَتْ أَسْمَاءَ، أَوْ أَسْمَاءُ حَدَّثَتْنِي أَنَّهَا أَمَرَتْهَا فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ، أَنْ تَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَهَا أَنْ تَقْعُدَ الْأَيَّامَ الَّتِي كَانَتْ تَقْعُدُ ثُمَّ تَغْتَسِلُ."],"takhrij":"حسن: رواه أبو داود (281) قال: حدَّثنا يوسف بن موسى، ثنا جرير، عن سهيل، يعني ابن أبي صالح، عن الزهري، عن عروة بن الزبير، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء أن المستحاضة تغتسل لكل صلاة","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (281).","chapter_en":"What Has Been Reported That a Woman with Istiḥāḍah Performs Ghusl for Every Prayer","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr said: Fāṭimah bint Abī Ḥubaysh told me that she instructed Asmāʾ—or Asmāʾ told me that Fāṭimah bint Abī Ḥubaysh instructed her—to ask the Messenger of Allah ﷺ. He instructed her to count the days during which she normally refrained from prayer and then to perform ghusl."]},"buhuth":{"en":["Benefit: Among the women reported to have experienced istiḥāḍah during the time of the Prophet ﷺ were:","• Zaynab bint Jaḥsh al-Asadiyyah, Mother of the Believers.","• Ḥamnah bint Jaḥsh al-Asadiyyah.","• Ḥabībah bint Jaḥsh al-Asadiyyah, also reported as Umm Ḥabībah bint Jaḥsh, who was married to ʿAbd al-Raḥmān ibn ʿAwf. Some held that Umm Ḥabībah was a title of Ḥamnah bint Jaḥsh, but the first view is regarded here as correct. These three were sisters who were afflicted with istiḥāḍah during the lifetime of the Prophet ﷺ.","• Sawdah bint Zamʿah, Mother of the Believers.","• Umm Salamah bint Abī Umayyah, Mother of the Believers.","• Fāṭimah bint Abī Ḥubaysh al-Qurashiyyah al-Asadiyyah.","• Sahlah bint Suhayl ibn ʿAmr al-Qurashiyyah.","• Asmāʾ bint Marthad of Banū Ḥārithah.","• Bādiyah bint Ghaylān, the woman about whom the effeminate man said that she “approaches with four and departs with eight,” as narrated by al-Bukhārī (4324) and Muslim (2180)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (281)."},{"num":1536,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ، أَنَّ امْرَأَةً كَانَتْ تُهَرَاقُ الدَّمَ وَكَانَتْ تَحْتَ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهَا أَنْ تَغْتَسِلَ عِنْدَ كُلِّ صَلَاةٍ وَتُصَلِّي."],"takhrij":"صحيح: رواه أبو داود (293) قال: حدَّثنا عبدالله بن عمرو بن أبي الحجاج أبو معمر، ثنا عبد الوارث، عن الحسين، عن يحيى بن أبي كثير، عن أبي سلمة قال: أخبرتني زينب بنت أبي سلمة، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء أن المستحاضة تغتسل لكل صلاة","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (293), Ibn Mājah (646), and al-Dārimī (935).","chapter_en":"What Has Been Reported That a Woman with Istiḥāḍah Performs Ghusl for Every Prayer","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Zaynab bint Abī Salamah reported that a woman experienced continuous bleeding, and she was married to ʿAbd al-Raḥmān ibn ʿAwf. The Messenger of Allah ﷺ instructed her to perform ghusl for every prayer and then pray."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (293)، وابن ماجه (646)، والدارمي (935)."},{"num":1537,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ قَالَتْ: قُلْتُ يَا رَسُولَ اللَّهِ! إِنَّ فَاطِمَةَ بِنْتَ أَبِي حُبَيْشٍ اسْتُحِيضَتْ مُنْذُ كَذَا وَكَذَا فَلَمْ تُصَلِّ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سُبْحَانَ اللَّهِ! إِنَّ هَذَا مِنَ الشَّيْطَانِ، لِتَجْلِسْ فِي مِرْكَنٍ فَإِذَا رَأَتْ صُفْرَةً فَوْقَ الْمَاءِ فَلْتَغْتَسِلْ لِلظُّهْرِ وَالْعَصْرِ غُسْلًا وَاحِدًا وَتَغْتَسِلْ لِلْمَغْرِبِ وَالْعِشَاءِ غُسْلًا وَاحِدًا وَتَغْتَسِلْ لِلْفَجْرِ غُسْلًا وَاحِدًا وَتَتَوَضَّأْ فِيمَا بَيْنَ ذَلِكَ."],"takhrij":"حسن: رواه أبو داود (296) قال: ثنا وهب بن بقية، ثنا خالد (بن عبدالله) عن سهيل، يعني ابن أبي صالح، عن الزهري، عن عروة بن الزبير، عن أسماء بنت عميس، فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في المستحاضة تجمع بين الصلاتين بغسل واحد","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (296).","chapter_en":"What Has Been Reported Concerning a Woman with Istiḥāḍah Combining Two Prayers with One Ghusl","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Asmāʾ bint ʿUmays said: I said: “O Messenger of Allah, Fāṭimah bint Abī Ḥubaysh has been experiencing istiḥāḍah for such-and-such a period and has not been praying.” The Messenger of Allah ﷺ said: “Glory be to Allah! This is from Satan. Let her sit in a basin, and when she sees a yellowish color above the water, let her perform one ghusl for Ẓuhr and ʿAṣr, one ghusl for Maghrib and ʿIshāʾ, and one ghusl for Fajr, and let her perform wuḍūʾ in between.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (296)."},{"num":1538,"demo":false,"sanad":"","matn":["عَنْ حَمْنَةَ بِنْتِ جَحْشٍ قَالَتْ: كُنْتُ أُسْتَحَاضُ حَيْضَةً كَثِيرَةً شَدِيدَةً، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْتَفْتِيهِ وَأُخْبِرُهُ، فَوَجَدْتُهُ فِي بَيْتِ أُخْتِي زَيْنَبَ بِنْتِ جَحْشٍ فَقُلْتُ: يَا رَسُولَ اللَّهِ! إِنِّي امْرَأَةٌ أُسْتَحَاضُ حَيْضَةً كَثِيرَةً شَدِيدَةً، فَمَا تَرَى فِيهَا قَدْ مَنَعَتْنِي الصَّلَاةَ وَالصَّوْمَ ؟ فَقَالَ: أَنْعَتُ لَكِ الْكُرْسُفَ، فَإِنَّهُ يُذْهِبُ الدَّمَ، قَالَتْ: هُوَ أَكْثَرُ مِنْ ذَلِكَ، قَالَ: فَاتَّخِذِي ثَوْبًا، فَقَالَتْ: هُوَ أَكْثَرُ مِنْ ذَلِكَ، إِنَّمَا أَثُجُّ ثَجًّا، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَآمُرُكِ بِأَمْرَيْنِ، أَيَّهُمَا فَعَلْتِ أَجْزَأَ عَنْكِ مِنَ الْآخَرِ، وَإِنْ قَوِيتِ عَلَيْهِمَا فَأَنْتِ أَعْلَمُ، قَالَ لَهَا: إِنَّمَا هَذِهِ رَكْضَةٌ مِنْ رَكَضَاتِ الشَّيْطَانِ، فَتَحَيَّضِي سِتَّةَ أَيَّامٍ أَوْ سَبْعَةَ أَيَّامٍ فِي عِلْمِ اللَّهِ، ثُمَّ اغْتَسِلِي حَتَّى إِذَا رَأَيْتِ أَنَّكِ قَدْ طَهُرْتِ وَاسْتَنْقَأْتِ فَصَلِّي ثَلَاثًا وَعِشْرِينَ لَيْلَةً أَوْ أَرْبَعًا وَعِشْرِينَ لَيْلَةً وَأَيَّامَهَا وَصُومِي، فَإِنَّ ذَلِكَ يَجْزِيكِ، وَكَذَلِكَ فَافْعَلِي فِي كُلِّ شَهْرٍ كَمَا تَحِيضُ النِّسَاءُ وَكَمَا يَطْهُرْنَ مِيقَاتُ حَيْضِهِنَّ وَطُهْرِهِنَّ، وَإِنْ قَوِيتِ عَلَى أَنْ تُؤَخِّرِي الظُّهْرَ وَتُعَجِّلِي الْعَصْرَ فَتَغْتَسِلِينَ وَتَجْمَعِينَ بَيْنَ الصَّلَاتَيْنِ الظُّهْرِ وَالْعَصْرِ، وَتُؤَخِّرِينَ الْمَغْرِبَ وَتُعَجِّلِينَ الْعِشَاءَ ثُمَّ تَغْتَسِلِينَ وَتَجْمَعِينَ بَيْنَ الصَّلَاتَيْنِ، فَافْعَلِي، وَتَغْتَسِلِينَ مَعَ الْفَجْرِ، فَافْعَلِي وَصُومِي إِنْ قَدِرْتِ عَلَى ذَلِكَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَهَذَا أَعْجَبُ الْأَمْرَيْنِ إِلَيَّ."],"takhrij":"حسن: رواه أبو داود (287) والترمذي (128) وابن ماجه (622، 627) كلهم من حديث عبدالله بن محمد بن عقيل، عن إبراهيم بن محمد بن طلحة، عن عَمِّه عمران بن طلحة، عن أمه حَمْنة بنت جَحْش فذكرته، واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ما جاء في المستحاضة تجمع بين الصلاتين بغسل واحد","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (287), al-Tirmidhī (128), and Ibn Mājah (622, 627).","chapter_en":"What Has Been Reported Concerning a Woman with Istiḥāḍah Combining Two Prayers with One Ghusl","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Ḥamnah bint Jaḥsh said: I used to experience very heavy and severe istiḥāḍah. I came to the Messenger of Allah ﷺ to seek his ruling and inform him about it, and I found him in the house of my sister Zaynab bint Jaḥsh. I said: “O Messenger of Allah, I am a woman who experiences very heavy and severe istiḥāḍah. What do you advise concerning it? It has prevented me from prayer and fasting.” He said: “I recommend cotton for you, for it will absorb the blood.” She said: “It is more than that.” He said: “Then use a cloth.” She said: “It is more than that; it gushes forth profusely.” The Messenger of Allah ﷺ said: “I will instruct you concerning two courses of action. Whichever of them you follow will suffice you in place of the other, and if you are able to do both, then you know best.” He then said to her: “This is only a blow from among the blows of Satan. So consider yourself menstruating for six or seven days, according to Allah’s knowledge, then perform ghusl. When you consider that you have become pure and thoroughly clean, pray for twenty-three nights—or twenty-four nights—and their days, and fast. That will suffice you. Do this every month just as women menstruate and become pure according to the customary times of their menstruation and purity. If you are able to delay Ẓuhr and bring ʿAṣr forward, then perform ghusl and combine Ẓuhr and ʿAṣr; and delay Maghrib and bring ʿIshāʾ forward, then perform ghusl and combine the two prayers. Do so. And perform ghusl for Fajr. Do so, and fast if you are able.” The Messenger of Allah ﷺ said: “This is the more pleasing of the two courses to me.”"]},"buhuth":{"en":["Kursuf means cotton.","Concerning his statement, “a blow from among the blows of Satan,” al-Khaṭṭābī said that the basic meaning of rakḍ is striking with the foot and causing injury with it. What is intended is harm and corruption, just as an animal kicks and injures with its leg. The meaning—Allah knows best—is that Satan found through this condition a means of confusing her concerning her religion, the time of her purity, and her prayer, until she became confused. Thus, figuratively, it was as though one of Satan’s blows had afflicted her.","The attribution of forgetfulness to Satan is like the statement of Allah Most High:","“So Satan made him forget to mention him to his master.” [Sūrat Yūsuf 12:42]","Likewise, when Satan causes confusion or forgetfulness in prayer, the worshipper is alerted according to the prescribed manner.","Other narrators transmitted the report in abbreviated form, and Ibn Mājah related it from Umm Ḥabībah bint Jaḥsh with wording close to the report of Ḥamnah. Ibn Mājah then referred to the report of Sharīk; its chain contains Sharīk and Abū al-Yaqẓān, and the chain is weak because of weakness in both narrators. It will be mentioned again near the end of the Book of Menstruation.","Regarding the expression “hantāh,” al-Jawharī said that this form is specifically used in direct address. Kursuf means cotton.","Al-Tirmidhī graded the report of Ḥamnah ḥasan ṣaḥīḥ. The author said: The more accurate judgment is that it is ḥasan only. The scholars differed concerning ʿAbd Allāh ibn Muḥammad ibn ʿAqīl: Yaḥyā ibn Maʿīn weakened him, al-ʿIjlī declared him trustworthy, and Ibn Ḥajar placed him among those described as truthful but having some weakness in their narration, and it is also said that he changed toward the end of his life.","Ibn Mandah stated that the report of Ḥamnah was not authentic through any route because it came through Ibn ʿAqīl and claimed that his reports had been abandoned. Ibn al-Turkumānī replied that Aḥmad, Isḥāq, and al-Ḥumaydī relied upon his reports, al-Bukhārī regarded his hadith as ḥasan, and Ibn Ḥanbal and al-Tirmidhī authenticated reports through him. Ibn al-Turkumānī also answered al-Bukhārī’s doubt regarding Ibn ʿAqīl hearing from Ibrāhīm by noting that Ibn ʿAqīl heard from Ibn ʿUmar, Jābir, and Anas, who were contemporaries of Ibrāhīm’s teachers, so his hearing from Ibrāhīm is not implausible. See al-Jawhar al-Naqī (1/339) and al-Minnah al-Kubrā (1/227–229)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (287)، والترمذي (128)، وابن ماجه (622، 627)."},{"num":1539,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: جَاءَتْ فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّه!ِ إِنِّي امْرَأَةٌ أُسْتَحَاضُ فَلَا أَطْهُرُ، أَفَأَدَعُ الصَّلَاةَ ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا، إِنَّمَا ذَلِكِ عِرْقٌ وَلَيْسَ بِحَيْضٍ، فَإِذَا أَقْبَلَتْ حَيْضَتُكِ فَدَعِي الصَّلَاةَ، وَإِذَا أَدْبَرَتْ فَاغْسِلِي عَنْكِ الدَّمَ ثُمَّ صَلِّي.","قَالَ: وَقَالَ أَبِي: ثُمَّ تَوَضَّئِي لِكُلِّ صَلَاةٍ حَتَّى يَجِيءَ ذَلِكَ الْوَقْتُ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (228) عن محمد، قال: ثنا أبو معاوية.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن المستحاضة تتوضأ لكل صلاة","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (228) and Muslim (333). This wording is that of al-Bukhārī.","chapter_en":"What Has Been Reported That a Woman with Istiḥāḍah Performs Wuḍūʾ for Every Prayer","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["ʿĀʾishah said: Fāṭimah bint Abī Ḥubaysh came to the Prophet ﷺ and said: “O Messenger of Allah, I am a woman who experiences istiḥāḍah and never becomes pure. Should I stop praying?” He said: “No. That is only a vein; it is not menstruation. When your menstrual period comes, leave the prayer, and when it ends, wash the blood from yourself and then pray.” The narrator said: My father added: “Then perform wuḍūʾ for every prayer until that time comes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (228)، ومسلم (333)، واللفظ للبخاري."},{"num":1540,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: اسْتُحِيضَتْ فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ، فَسَأَلَت النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: يَا رَسُولَ الله! إِنِّي أُسْتَحَاضُ فَلَا أَطْهُرُ، أَفَأَدَعُ الصَّلَاةَ؟ قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :إِنَّمَا ذَلِكَ عِرْقٌ، وَلَيْسَتْ بِالحَيْضَةِ، فَإِذَا أَقْبَلَتْ الحَيْضَةُ، فَدَعِي الصَّلَاةَ، وَإِذَا أَدْبَرَتْ، فَاغْسِلِي عَنْكِ أَثَرَ الدَّمِ، وَتَوَضَّئِي، فَإِنَّمَا ذَلِكَ عِرْقٌ، وَلَيْسَتْ بِالحَيْضَةِ. قِيلَ لَهُ: فَالْغُسْلُ؟ قَالَ:ذَلِكَ لَا يَشُكُّ فِيهِ أَحَدٌ."],"takhrij":"صحيح: رواه النسائي (217) عن يحيى بن حبيب بن عربي، قال: حدثنا حماد وهو ابن زيد، عن هشام بن عروة، عن أبيه، عن عائشة فذكرتْه.","grade":"صحيح","chapter_ar":"باب ما جاء أن المستحاضة تتوضأ لكل صلاة","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (217).","chapter_en":"What Has Been Reported That a Woman with Istiḥāḍah Performs Wuḍūʾ for Every Prayer","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["ʿĀʾishah said: Fāṭimah bint Abī Ḥubaysh experienced istiḥāḍah, so she asked the Prophet ﷺ: “O Messenger of Allah, I experience istiḥāḍah and do not become pure. Should I stop praying?” The Messenger of Allah ﷺ said: “That is only a vein and is not menstruation. When menstruation begins, leave the prayer; and when it ends, wash away the trace of blood and perform wuḍūʾ, for that is only a vein and is not menstruation.” He was asked concerning ghusl. He replied: “That is something no one doubts.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (217)."},{"num":1541,"demo":false,"sanad":"","matn":["عَنْ فَاطِمَةَ بِنْتِ أَبِي حُبَيْشٍ، أَنَّهَا كَانَتْ تُسْتَحَاضُ، فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا كَانَ دَمُ الْحَيْضَةِ، فَإِنَّهُ أَسْوَدُ يُعْرَفُ، فَإِذَا كَانَ ذَلِكَ فَأَمْسِكِي عَنِ الصَّلَاةِ، فَإِذَا كَانَ الْآخَرُ فَتَوَضَّئِي وَصَلِّي، فَإِنَّمَا هُوَ عِرْقٌ."],"takhrij":"حسن: رواه أبو داود (286) قال: حدَّثنا محمد بن المثنى، حدَّثنا محمد بن أبي عدي، عن محمد، يعني ابن عمرو، قال: حدثني ابن شهاب، عن عروة بن الزبير، عن فاطمة بنت أبي حُبَيش، فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ما جاء أن المستحاضة تتوضأ لكل صلاة","chapter_ur":"","part_ar":"كتاب الحيض","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (286).","chapter_en":"What Has Been Reported That a Woman with Istiḥāḍah Performs Wuḍūʾ for Every Prayer","part_en":"The Book of Menstruation","group_ar":"","group_en":"","part_no":6,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Fāṭimah bint Abī Ḥubaysh reported that she experienced istiḥāḍah. The Prophet ﷺ said to her: “When it is menstrual blood—and menstrual blood is dark and recognizable—then when that blood is present, refrain from prayer. When it is the other kind, perform wuḍūʾ and pray, for it is only a vein.”"]},"buhuth":{"en":["In summary concerning a woman experiencing istiḥāḍah:","She is not required to perform ghusl for any of the prayers except for a single ghusl when her menstrual period ends. This is the view of the majority of scholars: Abū Ḥanīfah, Mālik, al-Shāfiʿī, and Aḥmad, and it is also the position of many of the Companions and Tābiʿūn.","As for the reports narrated in Sunan Abī Dāwūd, al-Bayhaqī, and elsewhere, although some are authentic and others weak—as al-Bayhaqī explained—they do not establish an obligation contrary to what is more authentically reported.","The report concerning Umm Ḥabībah bint Jaḥsh found in the two Ṣaḥīḥ collections and elsewhere, stating, “She would perform ghusl for every prayer,” describes what she, may Allah be pleased with her, herself understood and practiced.","Al-Shāfiʿī therefore said:","“The Messenger of Allah ﷺ merely instructed her to perform ghusl and pray; it does not state that he instructed her to perform ghusl for every prayer.”","He also said:","“I have no doubt—if Allah Most High wills—that her ghusl was voluntary beyond what she had been commanded to do, and that was permissible for her.” Al-Umm (1/62).","Sufyān ibn ʿUyaynah, al-Layth ibn Saʿd, and others likewise held this understanding.","Although some Companions, including Ibn ʿAbbās and Ibn al-Zubayr and others, held that ghusl was obligatory for a woman experiencing istiḥāḍah, consensus was subsequently established that wuḍūʾ for each prayer is sufficient. Performing ghusl for every prayer remains recommended for a woman who wishes to do so and is able to do so without hardship, for Islam is a religion of ease."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (286)."},{"num":1542,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا الْأَعْمَالُ بِالنِّيَّةِ، وَإِنَّمَا لِامْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَتَزَوَّجُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري (1) ومسلم (1907)، كلاهما من طريق يحيى بن سعيد، عن محمد بن إبراهيم، عن علقمة بن وقاص الليثي قال: سمعت عمر بن الخطاب، فذكره.","grade":"متفق عليه","chapter_ar":"باب إيجاب النية للوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1) and Muslim (1907).","chapter_en":"The Obligation of Intention for Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb said: I heard the Messenger of Allah ﷺ say: “Actions are only by intentions, and every person will have only what he intended. Whoever’s migration was to Allah and His Messenger, then his migration was to Allah and His Messenger. And whoever’s migration was for some worldly gain he wished to obtain, or for a woman he wished to marry, then his migration was for that to which he migrated.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ﴾ [البينة: ٥]."],"en":["“And they were not commanded except to worship Allah, being sincere to Him in religion.” [Sūrat al-Bayyinah 98:5]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1],"tks":"متفق عليه: رواه البخاري (1)، ومسلم (1907)."},{"num":1543,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قال: طَلَبَ بَعْضُ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَضُوءًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ مَعَ أَحَدٍ مِنْكُمْ مَاءٌ ؟ فَوَضَعَ يَدَهُ فِي الْمَاءِ، وَيَقُولُ: تَوَضَّئُوا بِسْمِ اللَّهِ، فَرَأَيْتُ الْمَاءَ يَخْرُجُ مِنْ بَيْنِ أَصَابِعِهِ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ. قَالَ ثَابِتٌ: قُلْتُ لِأَنَسٍ: كَمْ تُرَاهُمْ ؟ قَالَ: نَحْوًا مِنْ سَبْعِينَ."],"takhrij":"صحيح: رواه النسائي (78) وأحمد (12694) كلاهما من حديث عبد الرزاق، وهو في مصنفه (20535)، قال: حدَّثنا معمر، عن ثابت وقتادة، عن أنس فذكر مثله. وصحّحه ابن خزيمة (144) فأخرجه من طريق عبد الرزاق به.","grade":"صحيح","chapter_ar":"باب التسمية في الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (78) and Aḥmad (12694); authenticated by Ibn Khuzaymah (144).","chapter_en":"Saying the Name of Allah During Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Anas said: Some of the Companions of the Prophet ﷺ sought water for wuḍūʾ. The Messenger of Allah ﷺ asked: “Does any one of you have water?” He placed his hand into the water and said: “Perform wuḍūʾ in the name of Allah.” I saw water flowing from between his fingers until every one of them, down to the last person, had performed wuḍūʾ. Thābit said: I asked Anas: “Approximately how many were they?” He replied: “About seventy.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10979],"tks":"صحيح: رواه النسائي (78)، وأحمد (12694)، وصححه ابن خزيمة (144)."},{"num":1544,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَقْبَلُ اللَّهُ صَلَاةَ أَحَدِكُمْ إِذَا أَحْدَثَ حَتَّى يَتَوَضَّأَ."],"takhrij":"متَّفقٌ عليه: أخرجه البخاري في الوضوء (135) وفي كتاب الحِيَل (6954) ومسلم في الطهارة (225) وفي رواية عند البخاري: فقال رجلٌ من حضرموت: ما الحَدَثُ يا أبا هريرة؟ قال: فُساءٌ أو ضُراط.","grade":"متفق عليه","chapter_ar":"باب وجوب الطهارة للصلاة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (135) and Muslim (225).","chapter_en":"The Obligation of Purification for Prayer","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “The prayer of one of you is not accepted after he breaks his state of purification until he performs wuḍūʾ.”"]},"buhuth":{"ar":["وفي رواية عند البخاري: فقال رجل من حضرموت: ما الحدث يا أبا هريرة؟","قال: فُساء أو ضُراط."],"en":["In another narration of al-Bukhārī, a man from Ḥaḍramawt asked:","“What is ḥadath, O Abū Hurayrah?”","He replied:","“Passing wind, whether silently or audibly.”"]},"intro":{"ar":["قال الله تعالى:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ﴾ [المائدة: ٦]."],"en":["“O you who believe, when you rise to perform prayer, wash your faces and your hands up to the elbows, wipe over your heads, and wash your feet up to the ankles.” [Sūrat al-Māʾidah 5:6]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (135)، ومسلم (225)."},{"num":1545,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا تُقْبَلُ صَلَاةٌ بِغَيْرِ طُهُورٍ، وَلَا صَدَقَةٌ مِنْ غُلُولٍ."],"takhrij":"صحيح: رواه مسلم في الطهارة (224) وفيه: عن مصعب بن سعد قال: دخل عبدالله بن عمر على ابن عامر يعوده وهو مريض، فقال: ألا تدعو الله لي يا ابن عمر! قال: سمعتُ رسول الله صلى الله عليه وسلم يقول، فذكر الحديث، ثم قال له: كنتَ على البصرة.","grade":"صحيح","chapter_ar":"باب وجوب الطهارة للصلاة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (224).","chapter_en":"The Obligation of Purification for Prayer","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: I heard the Messenger of Allah ﷺ say: “Allah does not accept prayer without purification, nor charity from ghulūl.”"]},"buhuth":{"en":["Ghulūl means unlawfully taking from the spoils of war before their proper distribution."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (224)."},{"num":1546,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ مِنَ الْغَائِطِ وَأُتِيَ بِطَعَامٍ، فَقِيلَ لَهُ: أَلَا تَوَضَّأُ؟ فَقَالَ: لِمَ ؟ أَأُصَلِّي فَأَتَوَضَّأَ؟."],"takhrij":"صحيح: رواه مسلم في الحيض (374) عن أبي بكر بن أبي شيبة، عن ابن عينية، عن عمرو بن دينار، سمع سعيد بن الحُوَيْرِث يقول: عن ابن عباس فذكر مثله.","grade":"صحيح","chapter_ar":"باب وجوب الطهارة للصلاة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (374).","chapter_en":"The Obligation of Purification for Prayer","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās said: We were with the Messenger of Allah ﷺ when he went to relieve himself. He then returned and food was brought to him. We said: “O Messenger of Allah, should we not bring you water for wuḍūʾ?” He replied: “Do I intend to pray, so that I should perform wuḍūʾ?”"]},"buhuth":{"en":["Abū Dāwūd (3760), al-Tirmidhī (1847), and al-Nasāʾī (132) narrate the wording:","“I was only commanded to perform wuḍūʾ when I rise for prayer.”","Ibn Khuzaymah authenticated it (35), and al-Tirmidhī graded it Ḥasan."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (374)."},{"num":1547,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لا تُقْبَلُ صَلاةٌ بِغَيْرِ طُهُورٍ، وَلا صَدَقَةٌ مِنْ غُلُولٍ."],"takhrij":"حسن: رواه البزار -كشف الأستار (252) عن محمد بن مسكين، ثنا يحيى بن حسَّان، ثنا سليمان، عن كثير، عن الوليد، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب وجوب الطهارة للصلاة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Bazzār in Kashf al-Astār (1/133, no. 252).","chapter_en":"The Obligation of Purification for Prayer","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “No prayer is accepted without purification, nor charity from ghulūl.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (252)."},{"num":1548,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَقْبَلُ اللهُ صَلَاةً بِغَيْرِ طَهُورٍ، وَلَا صَدَقَةً مِنْ غُلُولٍ."],"takhrij":"صحيح: رواه الطبراني في الكبير (18/ح 509) قال: حدَّثنا عبد العلي بن أحمد ابن عبدالله بن الفضل الحميدي، ورجاء البزار، قالا: ثنا بن الحباب، ثنا شعبة، عن قتادة، عن أبي السوار العدوي، عن عمران بن حصين، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وجوب الطهارة للصلاة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (18/206).","chapter_en":"The Obligation of Purification for Prayer","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn said: The Messenger of Allah ﷺ said: “Allah does not accept prayer without purification, nor charity from ghulūl.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في المعجم الكبير (18/ح 509)."},{"num":1549,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ عُمَيْرٍ الْهُذَلِيُّ، عَنِ النَّبِيّِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَقْبَلُ اللَّهُ عَزَّ وَجَلَّ صَدَقَةً مِنْ غُلُولٍ، وَلَا صَلَاةً بِغَيْرِ طُهُورٍ."],"takhrij":"صحيح: رواه أبو داود (59) والنسائي (139) وابن ماجه (271) كلهم من طريق قتادة، عن أبي المَليح بن أسامة، عن أسامة بن عُمير الهُذَلي، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وجوب الطهارة للصلاة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (59), al-Nasāʾī (139), and Ibn Mājah (271).","chapter_en":"The Obligation of Purification for Prayer","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Usāmah ibn ʿUmayr al-Hudhalī reported that the Prophet ﷺ said: “Allah, Mighty and Majestic, does not accept charity from ghulūl, nor prayer without purification.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (59)، والنسائي (139)، وابن ماجه (271)."},{"num":1550,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِفْتَاحُ الصَّلَاةِ الطُّهُورُ، وَتَحْرِيمُهَا التَّكْبِيرُ، وَتَحْلِيلُهَا التَّسْلِيمُ."],"takhrij":"حسن: رواه أبو داود (61) والترمذي (3) وابن ماجه (275) كلهم من طريق سفيان، عن عبدالله بن محمد بن عقيل، عن محمد بن الحنفية، عن علي بن أبي طالب، فذكره.","grade":"حسن","chapter_ar":"باب وجوب الطهارة للصلاة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (61), al-Tirmidhī (3), and Ibn Mājah (275).","chapter_en":"The Obligation of Purification for Prayer","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: The Messenger of Allah ﷺ said: “The key to prayer is purification; its commencement that makes ordinary actions prohibited is the takbīr, and its conclusion that makes them permissible again is the taslīm.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (61)، والترمذي (3)، وابن ماجه (275)."},{"num":1551,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا تَوَضَّأَ الْعَبْدُ الْمُسْلِمُ أَوِ الْمُؤْمِنُ فَغَسَلَ وَجْهَهُ، خَرَجَ مِنْ وَجْهِهِ كُلُّ خَطِيئَةٍ نَظَرَ إِلَيْهَا بِعَيْنَيْهِ مَعَ الْمَاءِ، أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ، فَإِذَا غَسَلَ يَدَيْهِ خَرَجَ مِنْ يَدَيْهِ كُلُّ خَطِيئَةٍ، كَانَ بَطَشَتْهَا يَدَاهُ مَعَ الْمَاءِ، أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ، فَإِذَا غَسَلَ رِجْلَيْهِ، خَرَجَتْ كُلُّ خَطِيئَةٍ مَشَتْهَا رِجْلَاهُ مَعَ الْمَاءِ، أَوْ مَعَ آخِرِ قَطْرِ الْمَاء، حَتَّى يَخْرُجَ نَقِيًّا مِنَ الذُّنُوبِ."],"takhrij":"صحيح: رواه مالك في الطهارة (31) عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكر الحديث. ومن طريقه رواه مسلم في الطهارة (244).","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (31) and Muslim (244).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “When the Muslim servant performs wuḍūʾ and washes his face, every sin at which his eyes looked leaves his face with the water—or with the last drop of the water. When he washes his hands, every sin committed by his hands leaves his hands with the water—or with the last drop of the water. When he washes his feet, every sin toward which his feet walked leaves with the water—or with the last drop of the water—until he emerges purified from sins.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مالك (31)، ومسلم (244)."},{"num":1552,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ، خَرَجَتْ خَطَايَاهُ مِنْ جَسَدِهِ، حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِهِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (245) عن محمد بن معمر بن ربعي، حدَّثنا أبو هشام المخزومي، عن عبد الوحد، ( وهو ابن زياد) حدَّثنا عثمان بن حكيم، حدَّثنا محمد بن المنكدر، عن حُمْران، عن عثمان بن عفان.. فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (245).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿUthmān ibn ʿAffān said: The Messenger of Allah ﷺ said: “Whoever performs wuḍūʾ and perfects his wuḍūʾ, his sins leave his body until they even emerge from beneath his fingernails.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (245)."},{"num":1553,"demo":false,"sanad":"","matn":["عَنْ حُمْرَانَ مَوْلَى عُثْمَانَ قَالَ: أَتَيْتُ عُثْمَانَ بْنَ عَفَّانَ، بِوَضُوءٍ فَتَوَضَّأَ ثُمَّ قَالَ: إِنَّ نَاسًا يَتَحَدَّثُونَ عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَادِيثَ لَا أَدْرِي مَا هِيَ ؟ إِلَّا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا، ثُمَّ قَالَ: مَنْ تَوَضَّأَ هَكَذَا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ، وَكَانَتْ صَلَاتُهُ وَمَشْيُهُ إِلَى الْمَسْجِدِ نَافِلَةً."],"takhrij":"صحيح: رواه مسلم في الطهارة (229) عن قتيبة بن سعيد، وأحمد بن عبدة الضبِّي، ثنا عبد العزيز – وهو الدراوردي، عن زيد بن أسلم، عن حُمْران مولى عثمان.. فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (229).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ḥumrān, the freed servant of ʿUthmān, said: I brought ʿUthmān ibn ʿAffān water for wuḍūʾ, and he performed wuḍūʾ. He then said: Some people narrate reports from the Messenger of Allah ﷺ that I do not know, but I saw the Messenger of Allah ﷺ perform wuḍūʾ in the same manner as this wuḍūʾ of mine, and then he said: “Whoever performs wuḍūʾ in this manner will have his previous sins forgiven, while his prayer and his walking to the mosque will be additional voluntary deeds for him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (229)."},{"num":1554,"demo":false,"sanad":"","matn":["عَنْ إِسْحَاق بْنِ سَعِيدِ بْنِ عَمْرِو بْنِ سَعِيدِ بْنِ الْعَاصِ قَالَ: حَدَّثَنِي أَبِي، عَنْ أَبِيهِ قَالَ: كُنْتُ عِنْدَ عُثْمَانَ بْنِ عَفَّانَ فَدَعَا بِطَهُورٍ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنِ امْرِئٍ مُسْلِمٍ تَحْضُرُهُ صَلَاةٌ مَكْتُوبَةٌ، فَيُحْسِنُ وُضُوءَهَا وَخُشُوعَهَا وَرُكُوعَهَا، إِلَّا كَانَتْ كَفَّارَةً لِمَا قَبْلَهَا مِنَ الذُّنُوبِ، مَا لَمْ يُؤْتِ كَبِيرَةً، وَذَلِكَ الدَّهْرَ كُلَّهُ."],"takhrij":"صحيح: رواه مسلم في الطهارة (228) عن عبد بن حميد، وحجاج الشاعر، كلاهما عن أبي الوليد: حدَّثنا إسحاق بن سعيد بن عمرو بن سعيد بن العاص به.","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (228).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Isḥāq ibn Saʿīd ibn ʿAmr ibn Saʿīd ibn al-ʿĀṣ said: My father narrated to me from his father, who said: I was with ʿUthmān ibn ʿAffān when he called for water for purification and said: I heard the Messenger of Allah ﷺ say: “No Muslim man is present when an obligatory prayer becomes due and then performs its wuḍūʾ properly, perfects its humility and its bowing, except that it becomes an expiation for the sins that preceded it, so long as he does not commit a major sin; and this applies for all time.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (228)."},{"num":1555,"demo":false,"sanad":"","matn":["عَنْ حُمْرَانَ بْنِ أَبَانَ قَالَ: كُنْتُ أَضَعُ لِعُثْمَانَ طَهُورَهُ فَمَا أَتَى عَلَيْهِ يَوْمٌ إِلَّا وَهُوَ يُفِيضُ عَلَيْهِ نُطْفَةً، وَقَالَ عُثْمَان:ُ حَدَّثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ انْصِرَافِنَا مِنْ صَلَاتِنَا هَذِهِ، قَالَ مِسْعَرٌ: أُرَاهَا الْعَصْرَ، فَقَالَ: مَا أَدْرِي أُحَدِّثُكُمْ بِشَيْءٍ أَوْ أَسْكُتُ، فَقُلْنَا: يَا رَسُولَ اللَّهِ! إِنْ كَانَ خَيْرًا فَحَدِّثْنَا، وَإِنْ كَانَ غَيْرَ ذَلِكَ فَاللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: مَا مِنْ مُسْلِمٍ يَتَطَهَّرُ، فَيُتِمُّ الطُّهُورَ الَّذِي كَتَبَ اللَّهُ عَلَيْهِ، فَيُصَلِّي هَذِهِ الصَّلَوَاتِ الْخَمْسَ، إِلَّا كَانَتْ كَفَّارَاتٍ لِمَا بَيْنَهَ."],"takhrij":"صحيح: رواه مسلم في الطهارة (231) عن أبي كُرَيب محمد بن العلاء، وإسحاق بن إبراهيم جميعاً، عن وكيعٍ. قال أبو كريب: حدَّثنا وكيع، عن مسعر، عن جامع بن شدَّاد، قال: سمعت حُمْران .. فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (231).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ḥumrān ibn Abān said: I used to prepare ʿUthmān’s water for purification, and hardly a day passed without him pouring some water over himself. ʿUthmān said: The Messenger of Allah ﷺ spoke to us as we were leaving this prayer—Misʿar said: I think it was the ʿAṣr prayer—and said: “I do not know whether I should tell you something or remain silent.” We said: “O Messenger of Allah, if it is something good, then tell us; and if it is otherwise, then Allah and His Messenger know best.” He said: “No Muslim purifies himself and completes the purification that Allah has prescribed for him, and then performs these five prayers, except that they become expiations for what occurs between them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (231)."},{"num":1556,"demo":false,"sanad":"","matn":["عَنْ حُمْرَانَ مَوْلَى عُثْمَانَ قَالَ: تَوَضَّأَ عُثْمَانُ بْنُ عَفَّانَ يَوْمًا وُضُوءًا حَسَنًا، ثُمَّ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ، ثُمَّ قَالَ: مَنْ تَوَضَّأَ هَكَذَا، ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ لَا يَنْهَزُهُ إِلَّا الصَّلَاةُ، غُفِرَ لَهُ مَا خَلَا مِنْ ذَنْبِهِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (232) عن هارون بن سعيد الأيلي، حدَّثنا ابن وهبٍ، وأخبرني مخرمة بن بكير، عن أبيه، عن حُمْران .. فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (232).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ḥumrān, the freed servant of ʿUthmān, said: One day ʿUthmān performed wuḍūʾ and performed it well. He then said: I saw the Messenger of Allah ﷺ perform wuḍūʾ and perfect it, and then he said: “Whoever performs wuḍūʾ like this and then goes out to the mosque, with nothing driving him except the prayer, will have what has passed of his sins forgiven.”"]},"buhuth":{"en":["The expression “what has passed of his sins” means his preceding sins."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (232)."},{"num":1557,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الأَشْعَرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الطُّهُورُ شَطْرُ الإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلَآَنِ أَوْ تَمْلَأُ مَا بَيْنَ السَّمَوَاتِ وَالأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ، كُلُّ النَّاسِ يَغْدُو، فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا."],"takhrij":"صحيح: رواه مسلم في الطهارة (223). عن إسحاق بن منصور، حدَّثنا حَبَّان بن هلال، حدَّثنا أبان، حدَّثنا يحيى، أن زيداً حدثه، أن أبا سلام حدثه، عن أبي مالك الأشعري قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (223).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Mālik al-Ashʿarī said: The Messenger of Allah ﷺ said: “Purification is half of faith. ‘All praise belongs to Allah’ fills the Scale. ‘Glory be to Allah’ and ‘all praise belongs to Allah’ fill—or fills—what is between the heavens and the earth. Prayer is light, charity is proof, patience is illumination, and the Qurʾān is evidence either for you or against you. Every person goes out in the morning and sells his soul, either setting it free or destroying it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[133],"tks":"صحيح: رواه مسلم (223)."},{"num":1558,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: قَالَ عَمْرُو بْنُ عَبَسَةَ السُّلَمِيُّ: كُنْتُ وَأَنَا فِي الْجَاهِلِيَّةِ أَظُنُّ أَنَّ النَّاسَ عَلَى ضَلَالَةٍ، وَأَنَّهُمْ لَيْسُوا عَلَى شَيْءٍ وَهُمْ يَعْبُدُونَ الْأَوْثَانَ، فَسَمِعْتُ بِرَجُلٍ بِمَكَّةَ يُخْبِرُ أَخْبَارًا، فَقَعَدْتُ عَلَى رَاحِلَتِي فَقَدِمْتُ عَلَيْهِ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُسْتَخْفِيًا جُرَآءُ عَلَيْهِ قَوْمُهُ، فَتَلَطَّفْتُ حَتَّى دَخَلْتُ عَلَيْهِ بِمَكَّةَ، فَقُلْتُ لَهُ: مَا أَنْتَ، قَالَ: أَنَا نَبِيٌّ، فَقُلْتُ: وَمَا نَبِيٌّ ؟ قَالَ: أَرْسَلَنِي اللَّهُ، فَقُلْتُ: وَبِأَيِّ شَيْءٍ أَرْسَلَكَ ؟ قَالَ: أَرْسَلَنِي بِصِلَةِ الْأَرْحَامِ، وَكَسْرِ الْأَوْثَانِ، وَأَنْ يُوَحَّدَ اللَّهُ لَا يُشْرَكُ بِهِ شَيْءٌ، قُلْتُ لَهُ: فَمَنْ مَعَكَ عَلَى هَذَا ؟ قَالَ: حُرٌّ وَعَبْدٌ، قَالَ: وَمَعَهُ يَوْمَئِذٍ أَبُو بَكْرٍ، وَبِلَالٌ مِمَّنْ آمَنَ بِهِ، فَقُلْتُ: إِنِّي مُتَّبِعُكَ، قَالَ: إِنَّكَ لَا تَسْتَطِيعُ ذَلِكَ يَوْمَكَ هَذَا، أَلَا تَرَى حَالِي وَحَالَ النَّاسِ، وَلَكِنْ ارْجِعْ إِلَى أَهْلِكَ، فَإِذَا سَمِعْتَ بِي قَدْ ظَهَرْتُ، فَأْتِنِي، قَالَ: فَذَهَبْتُ إِلَى أَهْلِي، وَقَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ وَكُنْتُ فِي أَهْلِي، فَجَعَلْتُ أَتَخَبَّرُ الْأَخْبَارَ، وَأَسْأَلُ النَّاسَ حِينَ قَدِمَ الْمَدِينَةَ حَتَّى قَدِمَ عَلَيَّ نَفَرٌ مِنْ أَهْلِ يَثْرِبَ مِنْ أَهْلِ الْمَدِينَةَ، فَقُلْتُ: مَا فَعَلَ هَذَا الرَّجُلُ الَّذِي قَدِمَ الْمَدِينَةَ ؟ فَقَالُوا: النَّاسُ إِلَيْهِ سِرَاعٌ، وَقَدْ أَرَادَ قَوْمُهُ قَتْلَهُ فَلَمْ يَسْتَطِيعُوا ذَلِكَ، فَقَدِمْتُ الْمَدِينَةَ فَدَخَلْتُ عَلَيْهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ أَتَعْرِفُنِي ؟ قَالَ: نَعَمْ أَنْتَ الَّذِي لَقِيتَنِي بِمَكَّةَ، قَالَ: فَقُلْتُ: بَلَى، فَقُلْتُ: يَا نَبِيَّ اللَّهِ أَخْبِرْنِي عَمَّا عَلَّمَكَ اللَّهُ وَأَجْهَلُهُ، أَخْبِرْنِي، عَنِ الصَّلَاةِ، قَالَ: صَلِّ صَلَاةَ الصُّبْحِ ثُمَّ أَقْصِرْ، عَنِ الصَّلَاةِ حَتَّى تَطْلُعَ الشَّمْسُ، حَتَّى تَرْتَفِعَ فَإِنَّهَا تَطْلُعُ حِينَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ، ثُمَّ صَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ، حَتَّى يَسْتَقِلَّ الظِّلُّ بِالرُّمْحِ، ثُمَّ أَقْصِرْ، عَنِ الصَّلَاةِ فَإِنَّ حِينَئِذٍ تُسْجَرُ جَهَنَّمُ، فَإِذَا أَقْبَلَ الْفَيْءُ فَصَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ، حَتَّى تُصَلِّيَ الْعَصْرَ، ثُمَّ أَقْصِرْ، عَنِ الصَّلَاةِ حَتَّى تَغْرُبَ الشَّمْسُ، فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ، قَالَ: فَقُلْتُ: يَا نَبِيَّ اللَّهِ فَالْوُضُوءَ حَدِّثْنِي عَنْهُ، قَالَ: مَا مِنْكُمْ رَجُلٌ يُقَرِّبُ وَضُوءَهُ، فَيَتَمَضْمَضُ وَيَسْتَنْشِقُ فَيَنْتَثِرُ إِلَّا خَرَّتْ خَطَايَا وَجْهِهِ وَفِيهِ وَخَيَاشِيمِهِ، ثُمَّ إِذَا غَسَلَ وَجْهَهُ كَمَا أَمَرَهُ اللَّهُ إِلَّا خَرَّتْ خَطَايَا وَجْهِهِ مِنْ أَطْرَافِ لِحْيَتِهِ مَعَ الْمَاءِ، ثُمَّ يَغْسِلُ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ إِلَّا خَرَّتْ خَطَايَا يَدَيْهِ مِنْ أَنَامِلِهِ مَعَ الْمَاءِ، ثُمَّ يَمْسَحُ رَأْسَهُ إِلَّا خَرَّتْ خَطَايَا رَأْسِهِ مِنْ أَطْرَافِ شَعْرِهِ مَعَ الْمَاءِ، ثُمَّ يَغْسِلُ قَدَمَيْهِ إِلَى الْكَعْبَيْنِ إِلَّا خَرَّتْ خَطَايَا رِجْلَيْهِ مِنْ أَنَامِلِهِ مَعَ الْمَاءِ، فَإِنْ هُوَ قَامَ فَصَلَّى فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَمَجَّدَهُ بِالَّذِي هُوَ لَهُ أَهْلٌ، وَفَرَّغَ قَلْبَهُ لِلَّهِ إِلَّا انْصَرَفَ مِنْ خَطِيئَتِهِ كَهَيْئَتِهِ يَوْمَ وَلَدَتْهُ أُمُّهُ.","فَحَدَّثَ عَمْرُو بْنُ عَبَسَةَ بِهَذَا الْحَدِيثِ، أَبَا أُمَامَةَ صَاحِبَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ أَبُو أُمَامَةَ: يَا عَمْرَو بْنَ عَبَسَةَ انْظُرْ مَا تَقُولُ فِي مَقَامٍ وَاحِدٍ يُعْطَى هَذَا الرَّجُلُ، فَقَالَ عَمْرٌو: يَا أَبَا أُمَامَةَ لَقَدْ كَبِرَتْ سِنِّي وَرَقَّ عَظْمِي وَاقْتَرَبَ أَجَلِي، وَمَا بِي حَاجَةٌ أَنْ أَكْذِبَ عَلَى اللَّهِ وَلَا عَلَى رَسُولِ اللَّهِ، لَوْ لَمْ أَسْمَعْهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا مَرَّةً أَوْ مَرَّتَيْنِ أَوْ ثَلَاثًا حَتَّى عَدَّ سَبْعَ مَرَّاتٍ مَا حَدَّثْتُ بِهِ أَبَدًا، وَلَكِنِّي سَمِعْتُهُ أَكْثَرَ مِنْ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (832)، عن أحمد بن جعفر المَعقري، حدَّثنا النضرُ بن محمد، حدَّثنا عكرمة بن عمَّار، حدَّثنا شدَّاد بن عبدالله أبو عمَّار، ويحيى بن أبي كثيرٍ، عن أبي أُمامة.. فذكر الحديثَ.","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (832).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Umāmah reported that ʿAmr ibn ʿAbasah al-Sulamī said: During the pre-Islamic period, I believed that the people were upon misguidance and had nothing of truth while they worshipped idols. Then I heard of a man in Makkah who was reporting extraordinary news, so I mounted my riding animal and went to him. The Messenger of Allah ﷺ was keeping himself concealed, while his people were acting boldly against him. I proceeded cautiously until I was able to meet him privately in Makkah. I asked him: “What are you?” He said: “I am a Prophet.” I asked: “What is a prophet?” He said: “Allah has sent me.” I asked: “With what has He sent you?” He replied: “He has sent me with maintaining ties of kinship, breaking the idols, and declaring Allah alone to be One, associating nothing with Him.” I asked: “Who is with you upon this?” He replied: “A free man and a slave.” At that time Abū Bakr and Bilāl were among those who had believed in him. I said: “I will follow you.” He replied: “You are not able to do that on this day of yours. Do you not see my situation and the situation of the people? Rather, return to your family, and when you hear that I have become established, then come to me.” So I returned to my family. The Messenger of Allah ﷺ later came to Madinah while I remained among my people. I continued seeking news and questioning people after he came to Madinah, until a group from Yathrib—the people of Madinah—came to me. I asked: “What has happened to the man who came to Madinah?” They replied: “People are rushing to him. His people tried to kill him but were unable to do so.” So I went to Madinah and entered upon him. I said: “O Messenger of Allah, do you recognize me?” He replied: “Yes. You are the one who met me in Makkah.” I said: “Yes.” Then I said: “O Prophet of Allah, tell me about what Allah has taught you and what I do not know. Tell me about the prayer.” He said: “Pray the dawn prayer, then refrain from prayer until the sun rises and becomes elevated, for when it rises it rises between the two horns of Satan, and at that time the disbelievers prostrate to it. Then pray, for the prayer is witnessed and attended, until the shadow becomes directly beneath the spear. Then refrain from prayer, for at that time Hell is kindled. When the shadow begins to return, then pray, for the prayer is witnessed and attended, until you have prayed ʿAṣr. Then refrain from prayer until the sun sets, for it sets between the two horns of Satan, and at that time the disbelievers prostrate to it.” I then asked: “O Prophet of Allah, tell me about wuḍūʾ.” He said: “There is no man among you who brings his water for wuḍūʾ, then rinses his mouth, draws water into his nose, and expels it, except that the sins of his face, his mouth, and his nostrils fall away. Then, when he washes his face as Allah has commanded him, the sins of his face fall from the ends of his beard with the water. Then he washes his hands up to the elbows, and the sins of his hands fall from his fingertips with the water. Then he wipes his head, and the sins of his head fall from the ends of his hair with the water. Then he washes his feet up to the ankles, and the sins of his feet fall from his toes with the water. Then, if he stands and prays, praises Allah, extols Him, glorifies Him as He deserves, and empties his heart entirely for Allah, he departs from his sins in the same state as on the day his mother gave birth to him.”","ʿAmr ibn ʿAbasah then narrated this hadith to Abū Umāmah, the Companion of the Messenger of Allah ﷺ. Abū Umāmah said: “O ʿAmr ibn ʿAbasah, consider carefully what you are saying! Is a man granted all of this in a single occasion?” ʿAmr replied: “O Abū Umāmah, I have grown old, my bones have become frail, and my death has drawn near. I have no need to lie about Allah or about the Messenger of Allah ﷺ. Had I heard it from the Messenger of Allah ﷺ only once, twice, or three times”—until he counted seven times—“I would never have narrated it. Rather, I heard it more times than that.”"]},"buhuth":{"en":["His statement, “he brings his wuḍūʾ,” with the wāw carrying a fatḥah, means the water with which he performs wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (832)."},{"num":1559,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ خَرَجَ مِنْ بَيْتِهِ مُتَطَهِّرًا إِلَى صَلَاةٍ مَكْتُوبَةٍ فَأَجْرُهُ كَأَجْرِ الْحَاجِّ الْمُحْرِمِ، وَمَنْ خَرَجَ إِلَى تَسْبِيحِ الضُّحَى لَا يَنْصِبُهُ إِلَّا إِيَّاهُ فَأَجْرُهُ كَأَجْرِ الْمُعْتَمِرِ، وَصَلَاةٌ عَلَى أَثَرِ صَلَاةٍ لَا لَغْوَ بَيْنَهُمَا كِتَابٌ فِي عِلِّيِّينَ."],"takhrij":"حسن: رواه أبو داود (558) عن أبي توبة، حدَّثنا الهيثم بن حُميد، عن يحيى بن الحارث، عن القاسم أبي عبدالرحمن، عن أبي أُمامة فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (558).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Umāmah reported that the Messenger of Allah ﷺ said: “Whoever leaves his house in a state of purification for an obligatory prayer will have a reward like that of a pilgrim in iḥrām. Whoever goes out for the prayer of Ḍuḥā, with nothing causing him to go out except it, will have a reward like that of one performing ʿumrah. And one prayer following another, with no idle speech between them, is recorded in ʿIlliyyīn.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2934],"tks":"حسن: رواه أبو داود (558)."},{"num":1560,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ صَاحِبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ عَبْدُ الْوَهَّابِ: أَبُو أُمَامَةَ الْحِمْصِيُّ صَاحِبُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْوُضُوءُ يُكَفِّرُ مَا قَبْلَهُ , ثُمَّ تَصِيرُ الصَّلَاةُ نَافِلَةً.","فَقِيلَ لَهُ: أَسَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ قَالَ: نَعَمْ، غَيْرَ مَرَّةٍ، وَلَا مَرَّتَيْنِ وَلَا ثَلَاثٍ، وَلَا أَرْبَعٍ وَلَا خَمْسٍ."],"takhrij":"حسن: رواه أحمد (22162) قال: حدَّثنا محمد بن بشر، حدَّثنا سعيد بن أبي عروبة، عن قتادة، عن شهر بن حوشب وعبد الوهاب، عن هشام وأزهر بن القاسم، حدَّثنا هشام، عن قتادة، عن شهر بن حوشب، عن أبي أُمامة.","grade":"حسن","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (22162), Abū Dāwūd al-Ṭayālisī (1225), and al-Ṭabarānī in al-Muʿjam al-Kabīr (7570).","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Umāmah, the Companion of the Messenger of Allah ﷺ—and ʿAbd al-Wahhāb said: Abū Umāmah al-Ḥimṣī, the Companion of the Messenger of Allah ﷺ—reported that the Messenger of Allah ﷺ said: “Wuḍūʾ expiates what came before it, and then the prayer becomes an additional voluntary deed.”","I asked him: “Did you hear this from the Messenger of Allah ﷺ?” He replied: “Yes—not once, nor twice, nor three times, nor four, nor five.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22162)، وأبو داود الطيالسي (1225)، والطبراني في المعجم الكبير (7570)."},{"num":1561,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: رَجُلَانِ مِنْ أُمَّتِي يَقُومُ أَحَدُهُمَا مِن اللَّيْلَ يُعَالِجُ نَفْسَهُ إِلَى الطَّهُورِ وَعَلَيْهِ عُقَدٌ فَيَتَوَضَّأُ، فَإِذَا وَضَّأَ يَدَيْهِ انْحَلَّتْ عُقْدَةٌ، وَإِذَا وَضَّأَ وَجْهَهُ انْحَلَّتْ عُقْدَةٌ، وَإِذَا مَسَحَ بِرَأْسِهِ انْحَلَّتْ عُقْدَةٌ، وَإِذَا وَضَّأَ رِجْلَيْهِ انْحَلَّتْ عُقْدَةٌ، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لِلَّذِينَ وَرَاءَ الْحِجَابِ: انْظُرُوا إِلَى عَبْدِي هَذَا يُعَالِجُ نَفْسَهُ يَسْأَلُنِي، مَا سَأَلَنِي عَبْدِي فَهُوَ لَهُ."],"takhrij":"صحيح: رواه أحمد (17791) والطبراني في الكبير (17/ح 843) كلاهما من طريق عبدالله بن وهب، عن عمرو بن الحارث، أن أبا عُشَّانة حدثه، أنه سمع عقبة بن عامر، فذكر الحديث. واللفظ لأحمد.","grade":"صحيح","chapter_ar":"باب ما جاء في ثواب الطهور","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17791) and al-Ṭabarānī in al-Muʿjam al-Kabīr (17/301). This wording is that of Aḥmad.","chapter_en":"What Has Been Reported Concerning the Reward of Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir said: I heard the Prophet ﷺ say: “Two men from my Ummah: one of them rises during the night, struggling against himself to reach the water of purification while knots are upon him. He performs wuḍūʾ. When he washes his hands, one knot is undone; when he washes his face, one knot is undone; when he wipes his head, one knot is undone; and when he washes his feet, one knot is undone. Then Allah says to those behind the veil: ‘Look at this servant of Mine. He struggles against himself and asks Me. Whatever My servant asks of Me is his.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17791)، والطبراني في المعجم الكبير (17/301)، واللفظ لأحمد."},{"num":1562,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قال لِبِلَالٍ عِنْدَ صَلَاةِ الْفَجْرِ: يَا بِلَالُ! حَدِّثْنِي بِأَرْجَى عَمَلٍ عَمِلْتَهُ فِي الْإِسْلَامِ، فَإِنِّي سَمِعْتُ دَفَّ نَعْلَيْكَ بَيْنَ يَدَيَّ فِي الْجَنَّةِ، قَالَ: مَا عَمِلْتُ عَمَلًا أَرْجَى عِنْدِي أَنِّي لَمْ أَتَطَهَّرْ طَهُورًا فِي سَاعَةِ لَيْلٍ أَوْ نَهَارٍ إِلَّا صَلَّيْتُ بِذَلِكَ الطُّهُورِ مَا كُتِبَ لِي أَنْ أُصَلِّيَ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في التهجد (1149) ومسلم في فضائل الصحابة (2458) كلاهمامن حديث أبي أسامة، عن أبي حيَّان، عن أبي زرعة، عن أبي هريرة فذكر مثله واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل الوضوء والصلاة عقبه","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1149) and Muslim (2458). This wording is that of al-Bukhārī.","chapter_en":"What Has Been Reported Concerning the Virtue of Wuḍūʾ and Prayer after It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said to Bilāl at the time of the dawn prayer: “O Bilāl, tell me about the deed you have done in Islam for which you have the greatest hope, for I heard the sound of your sandals before me in Paradise.” Bilāl replied: “I have done no deed for which I have greater hope than this: whenever I purified myself at any hour of the night or day, I prayed with that purification whatever was decreed for me to pray.”"]},"buhuth":{"en":["In Muslim’s wording:","“O Bilāl, tell me about the deed you have done in Islam that you consider most beneficial, for tonight I heard the soft sound of your sandals before me in Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1149)، ومسلم (2458)، واللفظ للبخاري."},{"num":1563,"demo":false,"sanad":"","matn":["عَنْ حُمْرَانَ مَوْلَى عُثْمَانَ بْنِ عَفَّانَ، أَنَّ عُثْمَانَ بْنَ عَفَّانَ جَلَسَ عَلَى الْمَقَاعِدِ فَجَاءَ الْمُؤَذِّنُ فَآذَنَهُ بِصَلَاةِ الْعَصْرِ، فَدَعَا بِمَاءٍ فَتَوَضَّأَ، ثُمّ قَالَ: وَاللَّهِ لَأُحَدِّثَنَّكُمْ حَدِيثًا لَوْلَا أَنَّهُ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمُوهُ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنَ امْرِئٍ يَتَوَضَّأُ فَيُحْسِنُ وُضُوءَهُ، ثُمَّ يُصَلِّي الصَّلَاةَ، إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلَاةِ الْأُخْرَى حَتَّى يُصَلِّيَهَا.","قَالَ يَحْيَى: قَالَ مَالِك: أُرَاهُ يُرِيدُ هَذِهِ الْآيَةَ: ﴿وَأَقِمِ الصَّلَاةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ذَلِكَ ذِكْرَى لِلذَّاكِرِينَ﴾ [سورة هود:114]."],"takhrij":"متَّفقٌ عليه: رواه مالك في الطهارة (29) واللفظ له، عن هشام بن عروة، عن أبيه، عن حُمْران به. ورواه البخـاري في الوضـوء (160) من وجـه آخـر عـن ابـن شهاب، ومسلم في الطهارة (227) من وجه آخر عن هشام، كلاهما عن عــروة، عن حُمْران به، وفيهما: قال عروة: الاية: ﴿إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ﴾ [البقرة 159]، ولم تقع في رواية مالك تعيين الآية، فقال من قبل نفسه. وسيأتي تفصيل الوضوء في صفة وضوء النبي صلى الله عليه وسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل الوضوء والصلاة عقبه","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (29), al-Bukhārī (160), and Muslim (227).","chapter_en":"What Has Been Reported Concerning the Virtue of Wuḍūʾ and Prayer after It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ḥumrān, the freed servant of ʿUthmān ibn ʿAffān, reported that ʿUthmān ibn ʿAffān was sitting at al-Maqāʿid when the caller to prayer came and informed him that it was time for ʿAṣr. He called for water and performed wuḍūʾ. He then said: “By Allah, I will certainly narrate a hadith to you. Were it not for something in the Book of Allah, I would not have narrated it to you.” He then said: I heard the Messenger of Allah ﷺ say: “No person performs wuḍūʾ and perfects his wuḍūʾ, then performs the prayer, except that he is forgiven for what occurs between that prayer and the next prayer, until he performs it.”","Yaḥyā said: Mālik said: I think he intended this verse: “And establish prayer at the two ends of the day and in the early hours of the night. Indeed, good deeds remove evil deeds. That is a reminder for those who remember.” [Sūrat Hūd 11:114]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (29)، والبخاري (160)، ومسلم (227)."},{"num":1564,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسًا مَا تَقُولُ ذَلِكَ يُبْقِي مِنْ دَرَنِهِ، قَالُوا: لَا يُبْقِي مِنْ دَرَنِهِ شَيْئًا، قَالَ: فَذَلِكَ مِثْلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللَّهُ بِهَا الْخَطَايَا."],"takhrij":"متَّفقٌ عليه: رواه البخاري في مواقيت الصلاة واللفظ له (528) ومسلم في المساجد (667) كلاهما من طريق يزيد بن الهاد، عن محمد بن إبراهيم، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل الوضوء والصلاة عقبه","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (528) and Muslim (667).","chapter_en":"What Has Been Reported Concerning the Virtue of Wuḍūʾ and Prayer after It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah reported that he heard the Messenger of Allah ﷺ say: “Tell me: if there were a river at the door of one of you in which he bathed five times every day, would any of his dirt remain?” They replied: “None of his dirt would remain.” He said: “That is the likeness of the five daily prayers: Allah wipes away sins through them.”"]},"buhuth":{"en":["In another wording:","“The likeness of the five prayers is that of a flowing river at the door of one of you in which he bathes five times every day. What would they leave of his dirt?”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14678],"tks":"متفق عليه: رواه البخاري (528)، ومسلم (667)."},{"num":1565,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَثَلُ الصَّلَوَاتِ الْخَمْسِ، كَمَثَلِ نَهْرٍ جَارٍ غَمْرٍ عَلَى بَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ."],"takhrij":"صحيح: رواه مسلم في المساجد (668)، عن أبي بكر بن أبي شيبة، وأبو كريب، قالا: حدَّثنا أبو معاوية، عن الأعمش، عن أبي سفيان، عن جابر .. فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الوضوء والصلاة عقبه","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (668).","chapter_en":"What Has Been Reported Concerning the Virtue of Wuḍūʾ and Prayer after It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Messenger of Allah ﷺ said: “The likeness of the five daily prayers is that of a deep, abundant flowing river at the door of one of you in which he bathes five times every day.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (668)."},{"num":1566,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ قَالَ: سَمِعْتُ رَسُولَ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَرَأَيْتَ لَوْ كَانَ بِفِنَاءِ أَحَدِكُمْ نَهْرٌ يَجْرِي يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ، مَا كَانَ يَبْقَى مِنْ دَرَنِهِ ؟ قَالَ: لَا شَيْءَ، قَالَ: فَإِنَّ الصَّلَاةَ تُذْهِبُ الذُّنُوبَ كَمَا يُذْهِبُ الْمَاءُ الدَّرَنَ."],"takhrij":"حسن: رواه ابن ماجه (1397) قال: حدَّثنا عبدالله بن أبي زياد، ثنا يعقوب بن إبراهيم بن سعد، حدثني ابنُ أخي ابن شهاب، عن عمه، حدثني صالح بن عبدالله بن أبي فروة، أن عامر بن سعد أخبره قال: سمعتُ أبان ابن عثمان يقول: قال عثمان، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في فضل الوضوء والصلاة عقبه","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Mājah (1397).","chapter_en":"What Has Been Reported Concerning the Virtue of Wuḍūʾ and Prayer after It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿUthmān reported: I heard the Messenger of Allah ﷺ say: “Tell me: if there were a river in the courtyard of one of you in which he bathed five times every day, what would remain of his dirt?” He replied: “Nothing.” He said: “Prayer removes sins just as water removes dirt.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1397)."},{"num":1567,"demo":false,"sanad":"","matn":["عَنْ سَعْدٍ وَنَاس مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُونَ: كَانَ رَجُلَانِ أَخَوَانِ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ أَحَدُهُمَا أَفْضَلَ مِنَ الْآخَرِ، فَتُوُفِّيَ الَّذِي هُوَ أَفْضَلُهُمَا، ثُمَّ عُمِّرَ الْآخَرُ بَعْدَهُ أَرْبَعِينَ لَيْلَةً، ثُمَّ تُوُفِّيَ، فَذُكِرَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَضْلُ الْأَوَّلِ عَلَى الْآخَرِ، فَقَالَ: أَلَمْ يَكُنْ يُصَلِّي ؟ فَقَالُوا: بَلَى يَا رَسُولَ اللَّهِ، فَكَانَ لَا بَأْسَ بِهِ، فَقَالَ: مَا يُدْرِيكُمْ مَاذَا بَلَغَتْ بِهِ صَلَاتُهُ ؟ ثُمَّ قَالَ عِنْدَ ذَلِكَ: إِنَّمَا مَثَلُ الصَّلَوَاتِ كَمَثَلِ نَهَرٍ جَارٍ بِبَابِ رَجُلٍ، غَمْرٍ عَذْبٍ، يَقْتَحِمُ فِيهِ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ، فَمَا تُرَوْنَ يُبْقِي ذَلِكَ مِنْ دَرَنِهِ."],"takhrij":"حسن: رواه أحمد (1534) قال: حدَّثنا هارون بن معروف، قال عبدالله: وسمعته أنا من هارون، حدَّثنا عبدالله بن وهب، حدثني مخرمة، عن أبيه، عن عامر بن سعد بن أبي وقاص قال: سمعت سعداً، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في فضل الوضوء والصلاة عقبه","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (1534); authenticated by Ibn Khuzaymah (310) and al-Ḥākim (718).","chapter_en":"What Has Been Reported Concerning the Virtue of Wuḍūʾ and Prayer after It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Saʿd and a group of the Companions of the Messenger of Allah ﷺ reported: There were two brothers during the time of the Messenger of Allah ﷺ. One of them was more virtuous than the other. The more virtuous of the two died, and the other lived for forty nights after him and then died. The superiority of the first over the second was mentioned to the Messenger of Allah ﷺ. He said: “Was he not praying?” They replied: “Yes, O Messenger of Allah, and there was nothing wrong with him.” He said: “How do you know how far his prayer raised him?” Then he said: “The likeness of prayer is that of a deep, sweet, flowing river at the door of a man into which he plunges five times every day. What do you think that would leave of his dirt?”"]},"buhuth":{"en":["A ghamr river means a river abundant in water."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (1534)، وصححه ابن خزيمة (310)، والحاكم (718)."},{"num":1568,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: كُنْتُ إِذَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا، نَفَعَنِي اللَّهُ بِمَا شَاءَ مِنْهُ، وَإِذَا حَدَّثَنِي عَنْهُ غَيْرِي، اسْتَحْلَفْتُهُ، فَإِذَا حَلَفَ لِي صَدَّقْتُهُ، وَإِنَّ أَبَا بَكْرٍ حَدَّثَنِي، وَصَدَقَ أَبُو بَكْرٍ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: مَا مِنْ رَجُلٍ يُذْنِبُ ذَنْبًا، فَيَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ.","وَفِي رِوَايَةِ: ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ اللَّهَ إِلَّا غَفَرَ اللَّهُ لَهُ، ثُمَّ قَرَأَ هَذِهِ الْآيَةَ: ﴿وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللَّهَ﴾ [آل عمران: ١٣٥] إِلَى آخِرِ الْآيَةِ."],"takhrij":"حسن: رواه أحمد (2) وأبو داود (1521) والترمذي في تفسير سورة آل عمران، وحسّنه (3006)، وابن ماجه (1395) كلهم من طرق عن عثمان بن المغيرة الثقفي، عن علي بن ربيعة الوالبيّ، عن أسماء بن الحكم الفزاري، عن علي بن أبي طالب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل الوضوء والصلاة عقبه","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (1521), al-Tirmidhī in his Tafsīr of Sūrat Āl ʿImrān (3006), who graded it Ḥasan, and Ibn Mājah (1395).","chapter_en":"What Has Been Reported Concerning the Virtue of Wuḍūʾ and Prayer after It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAlī said: Whenever I heard a hadith directly from the Messenger of Allah ﷺ, Allah benefited me through it as He willed. When someone else narrated to me from him, I would ask him to swear an oath; if he swore to me, I believed him. Abū Bakr narrated to me—and Abū Bakr spoke the truth—that he heard the Prophet ﷺ say: “No man commits a sin, then performs wuḍūʾ and perfects his wuḍūʾ, then prays two rakʿahs and asks Allah for forgiveness, except that Allah forgives him.”","He then recited this verse: “And those who, when they commit an indecency or wrong themselves, remember Allah and seek forgiveness for their sins—and who can forgive sins except Allah?—and they do not knowingly persist in what they have done.” [Sūrat Āl ʿImrān 3:135]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1521)، والترمذي في تفسير سورة آل عمران (3006) وحسنه، وابن ماجه (1395)."},{"num":1569,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ تَوَضَّأَ فَأَحْسَنَ وُضُوءَهُ، ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يَسْهُو فِيهِمَا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ."],"takhrij":"صحيح: رواه أبو داود (905) حدَّثنا أحمد بن محمد بن حنبل، حدَّثنا عبدالملك بن عمرو، حدَّثنا هشام، يعني ابن سعد، عن زيد بن أسلم، عن عطاء بن يسار، عن زيد بن خالد الجُهَني، فذكر الحديث. والحديث في مسند الإمام أحمد (17054).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الوضوء والصلاة عقبه","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (905) and Aḥmad (17054); authenticated by al-Ḥākim (451).","chapter_en":"What Has Been Reported Concerning the Virtue of Wuḍūʾ and Prayer after It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Zayd ibn Khālid al-Juhanī reported that the Prophet ﷺ said: “Whoever performs wuḍūʾ and perfects his wuḍūʾ, then prays two rakʿahs without becoming heedless in them, will have his previous sins forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (905)، وأحمد (17054)، وصححه الحاكم (451)."},{"num":1570,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَدِّدُوا وَقَارِبُوا وَاعْمَلُوا وَخَيِّرُوا، وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمْ الصَّلَاةُ، وَلَا يُحَافِظُ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ."],"takhrij":"حسن: رواه أحمد (22433) والطبراني في الكبير (1444) وأبو يعلى كما في إتحاف الخيرة (972) كلهم من طريق الوليد بن مسلم، حدَّثنا ابن ثوبان، حدثني حسَّان بن عطية، أن أبا كبشة السلوليَّ حدّثه، أنه سمع ثوبان مولى رسول الله صلى الله عليه وسلم يقول، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في المحافظة على الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (22433) and al-Ṭabarānī in al-Muʿjam al-Kabīr (1444).","chapter_en":"What Has Been Reported Concerning Maintaining Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Thawbān reported that the Messenger of Allah ﷺ said: “Be upright, strive to come close to what is right, and perform good deeds. The best of your deeds is prayer, and no one consistently maintains wuḍūʾ except a believer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22433)، والطبراني في المعجم الكبير (1444)."},{"num":1571,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ ( فَذَكَرَ الْحَدِيثَ): سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أُمَّتِي يُدْعَوْنَ يَوْمَ الْقِيَامَةِ غُرًّا مُحَجَّلِينَ مِنْ آثَارِ الْوُضُوءِ، فَمَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ غُرَّتَهُ فَلْيَفْعَلْ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (136) واللفظ له، ومسلم في الطهارة (246) كلاهما من طريق سعيد بن أبي هلال، عن نُعيم بن عبدالله المُجْمِر قال: رقيتُ مع أبي هريرة على ظهر المسجد، فتوضأ فقال: أنِّي سمعت رسول الله صلى الله عليه وسلم يقول، فذكر الحديث. وفي رواية مسلم من طريق عُمارة بن غَزِيَّة الأنصاري، عن نُعيم بن عبدالله المُجْمِر قال: رأيت أبا هريرة يتوضأ، فغسل وجهه فأسبغ الوضوء، ثم غسل يده اليمنى حتَّى أشرع في العَضُد، ثم يده اليُسرى حتَّى أشرع في العَضُد، ثم مسح رأسه، ثم غسل رِجله اليُمنى حتَّى أشرع في الساق، ثم غسل رجله اليُسرى حتَّى أشرع في الساق، ثم قـــال: هكذا رأيتُ رسول الله صلى الله عليه وسلم يتوضأ، ثم قال، فذكره.","grade":"متفق عليه","chapter_ar":"باب الغُرِّ المُحَجَّلين من آثار الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (136), whose wording this is, and Muslim (246).","chapter_en":"The Bright-Faced and Bright-Limbed from the Traces of Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah said: I heard the Messenger of Allah ﷺ say: “My Ummah will be summoned on the Day of Resurrection with bright faces and bright limbs from the traces of wuḍūʾ. So whoever among you is able to extend his brightness, let him do so.”"]},"buhuth":{"en":["The expression “bright-faced and bright-limbed” comes from the ghurrah and taḥjīl of a horse: whiteness upon its face and legs that beautifies and adorns it. The expression is used metaphorically for a person, so that the traces of wuḍūʾ upon the face, hands, and feet are likened to the white markings of a horse.","For this reason, thorough completion of wuḍūʾ is encouraged, as it increases and extends this brightness.","Extending the ghurrah and taḥjīl refers to washing beyond the minimum area that is obligatory to wash."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (136)، واللفظ له، ومسلم (246)."},{"num":1572,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمٍ قَالَ: كُنْتُ خَلْفَ أَبِي هُرَيْرَةَ وَهُوَ يَتَوَضَّأُ لِلصَّلَاةِ، فَكَانَ يَمُدُّ يَدَهُ حَتَّى تَبْلُغَ إِبْطَهُ، فَقُلْتُ لَهُ: يَا أَبَا هُرَيْرَةَ مَا هَذَا الْوُضُوءُ؟ فَقَالَ: يَا بَنِي فَرُّوخَ! أَنْتُمْ هَاهُنَا ؟ لَوْ عَلِمْتُ أَنَّكُمْ هَاهُنَا مَا تَوَضَّأْتُ هَذَا الْوُضُوءَ، سَمِعْتُ خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: تَبْلُغُ الْحِلْيَةُ مِنَ الْمُؤْمِنِ حَيْثُ يَبْلُغُ الْوَضُوءُ."],"takhrij":"صحيح: رواه مسلم الطهارة (250) عن قُتيبة بن سعيد، حدَّثنا خَلف، عن أبي مالكٍ الأشجعي، عن أبي حازمٍ ..فذكره.","grade":"صحيح","chapter_ar":"باب الغُرِّ المُحَجَّلين من آثار الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (250).","chapter_en":"The Bright-Faced and Bright-Limbed from the Traces of Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Ḥāzim said: I was behind Abū Hurayrah while he was performing wuḍūʾ for prayer. He continued washing his arm until he reached his armpit. I asked him: “What is this, O Abū Hurayrah?” He replied: “O sons of Farrūkh! Are you here? Had I known that you were here, I would not have performed wuḍūʾ in this manner. I heard the Prophet ﷺ, my beloved, say: ‘The adornment of the believer will reach as far as his wuḍūʾ reaches.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (250)."},{"num":1573,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى الْمَقْبُرَةِ فَقَالَ: السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ، وَدِدْتُ أَنِّي قَدْ رَأَيْتُ إِخْوَانَنَا، فَقَالُوا: يَا رَسُولَ اللَّهِ! أَلَسْنَا بِإِخْوَانِكَ ؟ قَالَ: بَلْ أَنْتُمْ أَصْحَابِي، وَإِخْوَانُنَا الَّذِينَ لَمْ يَأْتُوا بَعْدُ وَأَنَا فَرَطُهُمْ عَلَى الْحَوْضِ، فَقَالُوا: يَا رَسُولَ اللَّهِ! كَيْفَ تَعْرِفُ مَنْ يَأْتِي بَعْدَكَ مِنْ أُمَّتِكَ ؟ قَالَ: أَرَأَيْتَ لَوْ كَانَ لِرَجُلٍ خَيْلٌ غُرٌّ مُحَجَّلَةٌ فِي خَيْلٍ دُهْمٍ بُهْمٍ أَلَا يَعْرِفُ خَيْلَهُ ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ! قَالَ: فَإِنَّهُمْ يَأْتُونَ يَوْمَ الْقِيَامَةِ غُرًّا مُحَجَّلِينَ مِنَ الْوُضُوءِ، وَأَنَا فَرَطُهُمْ عَلَى الْحَوْضِ فَلَا يُذَادَنَّ رِجَالٌ عَنْ حَوْضِي كَمَا يُذَادُ الْبَعِيرُ الضَّالُّ أُنَادِيهِمْ؟ أَلَا هَلُمّ!َ أَلَا هَلُمَّ! أَلَا هَلُمَّ! فَيُقَالُ: إِنَّهُمْ قَدْ بَدَّلُوا بَعْدَكَ، فَأَقُولُ: فَسُحْقًا فَسُحْقًا فَسُحْقًا."],"takhrij":"صحيح: رواه مالك في الطهارة (28) عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة، فذكر الحديث، واللفظ له، ومسلم في الطهارة (249) من طريق مالك وغيره، عن العلاء بن عبدالرحمن به مثله.","grade":"صحيح","chapter_ar":"باب الغُرِّ المُحَجَّلين من آثار الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (28).","chapter_en":"The Bright-Faced and Bright-Limbed from the Traces of Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ went out to the graveyard and said: “Peace be upon you, abode of believing people. Indeed, if Allah wills, we will join you. I wish that I had seen our brothers.” They said: “O Messenger of Allah, are we not your brothers?” He said: “Rather, you are my Companions. Our brothers are those who have not yet come, and I will precede them at the Basin.” They asked: “O Messenger of Allah, how will you recognize those of your Ummah who come after you?” He said: “Tell me: if a man owned horses with white blazes and white markings on their legs among completely black horses, would he not recognize his own horses?” They replied: “Yes, O Messenger of Allah.” He said: “They will come on the Day of Resurrection with bright faces and bright limbs from wuḍūʾ, and I will precede them at the Basin. Men will certainly be driven away from my Basin just as a stray camel is driven away. I will call to them: ‘Come! Come! Come!’ Then it will be said: ‘They changed after you.’ So I will say: ‘Away with them! Away with them! Away with them!’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مالك (28)."},{"num":1574,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ حَوْضِي لَأَبْعَدُ مِنْ أَيْلَةَ مِنْ عَدَنٍ وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لَأَذُودُ عَنْهُ الرِّجَالَ، كَمَا يَذُودُ الرَّجُلُ الإِبِلَ الْغَرِيبَةَ عَنْ حَوْضِهِ، قَالُوا: يَا رَسُولَ اللَّهِ! وَتَعْرِفُنَا ؟ قَالَ: نَعَمْ، تَرِدُونَ عَلَيَّ غُرًّا مُحَجَّلِينَ مِنْ آثَارِ الْوُضُوءِ، لَيْسَتْ لِأَحَدٍ غَيْرِكُمْ."],"takhrij":"صحيح: رواه مسلم في الطهارة (248) عن عثمان بن أبي شيبة ثنا علي بن مُسهر، عن سعد بن طارق، عن رِبعي بن خِراش، عن حذيفة فذكره.","grade":"صحيح","chapter_ar":"باب الغُرِّ المُحَجَّلين من آثار الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (248).","chapter_en":"The Bright-Faced and Bright-Limbed from the Traces of Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ḥudhayfah said: The Messenger of Allah ﷺ said: “My Basin is farther in extent than the distance between Aylah and ʿAdan. By the One in whose Hand is my soul, I will drive men away from it just as a man drives unfamiliar camels away from his watering place.” They asked: “O Messenger of Allah, will you recognize us?” He replied: “Yes. You will come to me with bright faces and bright limbs from the traces of wuḍūʾ, a distinction belonging to no one other than you.”"]}},"tuhfa":{},"full":1,"rep":[835],"tks":"صحيح: رواه مسلم (248)."},{"num":1575,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أُمَّتِي يَوْمَ الْقِيَامَةِ غُرٌّ مِنَ السُّجُودِ مُحَجَّلُونَ مِنَ الْوُضُوءِ."],"takhrij":"صحيح: رواه الترمذي (607) عن أبي الوليد أحمد بن بكار الدمشقي ثنا الوليد بن مسلم قال: قال صفوان بن عمرو، أخبرني يزيد بن خُمير، عن عبدالله بن بُسر فذكر مثله.","grade":"صحيح","chapter_ar":"باب الغُرِّ المُحَجَّلين من آثار الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (607), who said: “This is a ḥasan ṣaḥīḥ gharīb hadith.”","chapter_en":"The Bright-Faced and Bright-Limbed from the Traces of Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Busr reported that the Prophet ﷺ said: “My Ummah on the Day of Resurrection will have brightness from prostration and bright-marked limbs from wuḍūʾ.”"]},"buhuth":{"en":["Aḥmad (17693) and al-Ṭabarānī in Musnad al-Shāmiyyīn (995) narrated:","“There is no one from my Ummah except that I will recognize him on the Day of Resurrection.”","They asked:","“How will you recognize them, O Messenger of Allah, among the multitude of creation?”","He said:","“Tell me: if you entered an enclosure containing completely black horses, and among them was a horse with a white blaze on its face and white markings on its legs, would you not recognize it?”","They replied:","“Yes.”","He said:","“My Ummah on that Day will have brightness from prostration and bright-marked limbs from wuḍūʾ.”","The word “buhm”—with a ḍammah on the bāʾ and sukūn on the hāʾ—means completely and uniformly black."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (607)، وقال: «هذا حديث حسن صحيح غريب»."},{"num":1576,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: قِيلَ يَا رَسُولَ اللَّهِ كَيْفَ تَعْرِفُ مَنْ لَمْ تَرَ مِنْ أُمَّتِكَ ؟ قَالَ: غُرٌّ مُحَجَّلُونَ بُلْقٌ مِنْ آثَارِ الطُّهُورِ."],"takhrij":"حسن: رواه ابن ماجه (284) حدَّثنا محمد بن يحيى النيسابوري، قال: حدَّثنا أبو الوليد هشام بن عبد الملك، قال: حدَّثنا حماد، عن عاصم، عن زِرِّ بن حُبَيش، أن عبدالله بن مسعود قال: فذكره.","grade":"حسن","chapter_ar":"باب الغُرِّ المُحَجَّلين من آثار الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Mājah (284) and Ibn Ḥibbān in his Ṣaḥīḥ (1047).","chapter_en":"The Bright-Faced and Bright-Limbed from the Traces of Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn Masʿūd said: It was asked: “O Messenger of Allah, how will you recognize those of your Ummah whom you have never seen?” He replied: “They will be bright-faced and bright-limbed, marked with brightness from the traces of wuḍūʾ.”"]},"buhuth":{"en":["The word “bulq” derives from describing a horse as ablaq when its coloring contains both black and white."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (284)، وابن حبان في صحيحه (1047)."},{"num":1577,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْجِبُهُ التَّيَمُّنُ فِي تَنَعُّلِهِ وَتَرَجُّلِهِ وَطُهُورِهِ وَفِي شَأْنِهِ كُلِّهِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (168) ومسلم في الطهارة (268) كلاهما من طريق شعبة، عن أشعث بن سليم، عن أبيه، عن مسروق، عن عائشة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب التيمُّن في الطهور وغيره","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (168) and Muslim (268).","chapter_en":"Beginning with the Right Side in Purification and Other Matters","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿĀʾishah said: The Prophet ﷺ liked beginning with the right side when putting on his sandals, combing his hair, performing purification, and in all of his affairs."]},"buhuth":{"en":["Muslim also narrated:","“The Messenger of Allah ﷺ loved beginning with the right side in his purification when he purified himself, in combing his hair when he combed it, and in putting on his sandals when he put them on.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14475],"tks":"متفق عليه: رواه البخاري (168)، ومسلم (268)."},{"num":1578,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا لَبِسْتُمْ وَإِذَا تَوَضَّأْتُمْ فَابْدَءُوا بِأَيَامِنِكُمْ."],"takhrij":"صحيح: رواه أبو داود (4141) وابن ماجه (402) من طريق أبي جعفر النُّفَيْلي، ثنا زهير بن معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب التيمُّن في الطهور وغيره","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4141) and Ibn Mājah (402).","chapter_en":"Beginning with the Right Side in Purification and Other Matters","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “When you dress and when you perform wuḍūʾ, begin with your right sides.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14473],"tks":"صحيح: رواه أبو داود (4141)، وابن ماجه (402)."},{"num":1579,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ، عَنْ أَبِيهِ، أَنَّهُ قَالَ لِعَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ وَهُوَ جَدُّ عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ، وَكَانَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ تَسْتَطِيعُ أَنْ تُرِيَنِي كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ ؟ فَقَالَ عَبْدُ اللَّهِ بْنُ زَيْدِ بْنِ عَاصِمٍ: نَعَمْ، فَدَعَا بِوَضُوءٍ فَأَفْرَغَ عَلَى يَدِهِ فَغَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ، ثُمَّ تَمَضْمَضَ وَاسْتَنْثَرَ ثَلَاثًا، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا، ثُمَّ غَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ إِلَى الْمِرْفَقَيْنِ، ثُمَّ مَسَحَ رَأْسَهُ بِيَدَيْهِ، فَأَقْبَلَ بِهِمَا وَأَدْبَرَ بَدَأَ بِمُقَدَّمِ رَأْسِهِ، ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ، ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ، ثُمَّ غَسَلَ رِجْلَيْهِ."],"takhrij":"متَّفقٌ عليه: رواه مالك في الطهارة (1) وعنه البخاري في الوضوء (185) ومسلم في الطهارة (235).","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (32), al-Bukhārī (185), and Muslim (235).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAmr ibn Yaḥyā al-Māzinī narrated from his father that he said to ʿAbdullāh ibn Zayd ibn ʿĀṣim—who was the grandfather of ʿAmr ibn Yaḥyā al-Māzinī and one of the Companions of the Messenger of Allah ﷺ: “Can you show me how the Messenger of Allah ﷺ used to perform wuḍūʾ?” ʿAbdullāh ibn Zayd ibn ʿĀṣim replied: “Yes.” He called for water for wuḍūʾ, poured it over his hands and washed them twice. He then rinsed his mouth and expelled water from his nose three times, washed his face three times, and washed his arms to the elbows twice each. He then wiped his head with both hands, moving them forward and backward. He began at the front of his head, moved both hands to the back of his head, and then returned them to the place from which he had begun. He then washed his feet."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1)، والبخاري (185)، ومسلم (235)."},{"num":1580,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ تَوَضَّأَ فَغَسَلَ وَجْهَهُ، أَخَذَ غَرْفَةً مِنْ مَاءٍ فَمَضْمَضَ بِهَا وَاسْتَنْشَقَ، ثُمَّ أَخَذَ غَرْفَةً مِنْ مَاءٍ فَجَعَلَ بِهَا هَكَذَا أَضَافَهَا إِلَى يَدِهِ الْأُخْرَى فَغَسَلَ بِهِمَا وَجْهَهُ، ثُمَّ أَخَذَ غَرْفَةً مِنْ مَاءٍ فَغَسَلَ بِهَا يَدَهُ الْيُمْنَى، ثُمَّ أَخَذَ غَرْفَةً مِنْ مَاءٍ فَغَسَلَ بِهَا يَدَهُ الْيُسْرَى، ثُمَّ مَسَحَ بِرَأْسِهِ، ثُمَّ أَخَذَ غَرْفَةً مِنْ مَاءٍ فَرَشَّ عَلَى رِجْلِهِ الْيُمْنَى حَتَّى غَسَلَهَا، ثُمَّ أَخَذَ غَرْفَةً أُخْرَى فَغَسَلَ بِهَا رِجْلَهُ يَعْنِي الْيُسْرَى، ثُمَّ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ."],"takhrij":"صحيح: رواه البخاري في الوضوء (140) من حديث ابن بلال، يعني سليمان، عن زيد بن أسلم، عن عطاء بن يسار، عن ابن عباس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (140).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās performed wuḍūʾ. He took a handful of water, rinsed his mouth and drew water into his nose. He then took another handful, joined it with his other hand, and washed his face with both hands. He took a handful of water and washed his right arm, then another handful and washed his left arm. He then wiped his head. After that, he took a handful of water and poured it over his right foot until he washed it, then took another handful and washed his left foot. He then said: “This is how I saw the Messenger of Allah ﷺ perform wuḍūʾ.”"]},"buhuth":{"en":["In another report:","“The Prophet ﷺ performed wuḍūʾ once for each limb.”","Also narrated by al-Bukhārī (157).","A number of narrators reported from Ibn ʿAbbās that the Prophet ﷺ performed wuḍūʾ once for each limb. The scholars agreed that wuḍūʾ is valid when each limb is washed once, twice, or three times. All of these forms are authentically established from the Prophet ﷺ. It is also established that on some occasions he washed some limbs once and others three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (140)."},{"num":1581,"demo":false,"sanad":"","matn":["عَنْ حُمْرَانَ مَوْلَى عُثْمَانَ أَنَّهُ أَخْبَرَ، أَنَّهُ رَأَى عُثْمَانَ بْنَ عَفَّانَ دَعَا بِإِنَاءٍ، فَأَفْرَغَ عَلَى كَفَّيْهِ ثَلَاثَ مِرَارٍ فَغَسَلَهُمَا، ثُمَّ أَدْخَلَ يَمِينَهُ فِي الْإِنَاءِ فَمَضْمَضَ وَاسْتَنْشَقَ، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثَ مِرَارٍ، ثُمَّ مَسَحَ بِرَأْسِهِ، ثُمَّ غَسَلَ رِجْلَيْهِ ثَلَاثَ مِرَارٍ إِلَى الْكَعْبَيْنِ، ثُمَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا، ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (159) واللفظ له، ومسلم في الطهارة (226) كلاهما من طريق الزهري، عن عطاء بن يزيد، أخبره أن حُمران مولى عثمان أخبره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (159), whose wording this is, and Muslim (226).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ḥumrān, the freed servant of ʿUthmān, reported that he saw ʿUthmān ibn ʿAffān call for a vessel of water. He poured water over his hands three times and washed them. He then placed his right hand into the vessel, rinsed his mouth, and drew water into his nose. He washed his face three times, his arms to the elbows three times, wiped his head, and then washed his feet to the ankles three times. He then said that the Messenger of Allah ﷺ said: “Whoever performs wuḍūʾ in a manner similar to this wuḍūʾ of mine, then prays two rakʿahs without allowing himself to become distracted by thoughts during them, will have his previous sins forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (159)، واللفظ له، ومسلم (226)."},{"num":1582,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ خَيْرٍ قَالَ: أَتَانَا عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ وَقَدْ صَلَّى، فَدَعَا بِطَهُورٍ، فَقُلْنَا: مَا يَصْنَعُ بِالطَّهُورِ وَقَدْ صَلَّى ؟ مَا يُرِيدُ إِلَّا لِيُعَلِّمَنَا، فَأُتِيَ بِإِنَاءٍ فِيهِ مَاءٌ وَطَسْتٍ فَأَفْرَغَ مِنَ الْإِنَاءِ عَلَى يَمِينِهِ فَغَسَلَ يَدَيْهِ ثَلَاثًا، ثُمَّ تَمَضْمَضَ وَاسْتَنْثَرَ ثَلَاثًا، فَمَضْمَضَ وَنَثَرَ مِنَ الْكَفِّ الَّذِي يَأْخُذُ فِيهِ، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا، ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى ثَلَاثًا وَغَسَلَ يَدَهُ الشِّمَالَ ثَلَاثًا، ثُمَّ جَعَلَ يَدَهُ فِي الْإِنَاءِ فَمَسَحَ بِرَأْسِهِ مَرَّةً وَاحِدَةً، ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى ثَلَاثًا وَرِجْلَهُ الشِّمَالَ ثَلَاثًا، ثُمَّ قَالَ: مَنْ سَرَّهُ أَنْ يَعْلَمَ وُضُوءَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَهُوَ هَذَا."],"takhrij":"حسن: رواه أبو داود (111) واللفظ له، والنسائي (92) كلاهما من حديث خالد بن علقمة، عن عبد خير.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (111), whose wording this is, and al-Nasāʾī (92).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbd Khayr said: ʿAlī, may Allah be pleased with him, came to us after he had already prayed and called for water for wuḍūʾ. We said: “What does he intend to do with water for wuḍūʾ when he has already prayed? He only intends to teach us.” A vessel containing water and a basin were brought. He poured water from the vessel and washed his hands three times. He rinsed his mouth and expelled water from his nose three times, using the same handful for rinsing the mouth and nose. He then washed his face three times, his right arm three times, and his left arm three times. He placed his hand into the vessel and wiped his head once. Then he washed his right foot three times and his left foot three times. He said: “Whoever would like to know the wuḍūʾ of the Messenger of Allah ﷺ, this is it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (111)، واللفظ له، والنسائي (92)."},{"num":1583,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! كَيْفَ الطُّهُورُ ؟ فَدَعَا بِمَاءٍ فِي إِنَاءٍ فَغَسَلَ كَفَّيْهِ ثَلَاثًا، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا، ثُمَّ غَسَلَ ذِرَاعَيْهِ ثَلَاثًا، ثُمَّ مَسَحَ بِرَأْسِهِ فَأَدْخَلَ إِصْبَعَيْهِ السَّبَّاحَتَيْنِ فِي أُذُنَيْهِ وَمَسَحَ بِإِبْهَامَيْهِ عَلَى ظَاهِرِ أُذُنَيْهِ بَاطِنَ أُذُنَيْهِ، ثُمَّ غَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ: هَكَذَا الْوُضُوءُ، فَمَنْ زَادَ عَلَى هَذَا أَوْ نَقَصَ، فَقَدْ أَسَاءَ وَظَلَمَ، أَوْ ظَلَمَ وَأَسَاءَ."],"takhrij":"حسن: رواه أبو داود (135)، واللفظ له،، والنسائي الصغرى (140) وابن ماجه (422) كلهم من طريق موسى بن أبي عائشة، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (135), whose wording this is, al-Nasāʾī (140), and Ibn Mājah (422).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that a man came to the Prophet ﷺ and asked: “O Messenger of Allah, how is purification performed?” He called for water in a vessel and washed his hands three times, washed his face three times, and washed his forearms three times. He then wiped his head, inserted his two index fingers into his ears, wiped the outer portions of his ears with his thumbs and their inner portions with his index fingers, and then washed his feet three times each. He then said: “This is wuḍūʾ. Whoever adds to this or falls short has acted badly and wronged.” Or: “Has wronged and acted badly.”"]},"buhuth":{"en":["Al-Nasāʾī and Ibn Mājah narrate a shorter wording:","“He showed him wuḍūʾ three times for each limb, then said: ‘This is wuḍūʾ. Whoever adds to this has acted badly, exceeded the limit, and wronged.’”","The statement “whoever adds to this” refers to increasing the number of washings.","Ibn Khuzaymah titled a chapter (174): “The stern warning concerning washing the limbs of wuḍūʾ more than three times, and the evidence that whoever does so is a wrongdoer who has acted badly, or an overstepping wrongdoer.” He then cited this hadith.","This does not contradict the established narration from Abū Hurayrah concerning washing the arms toward the shoulders and the legs toward the shins in connection with the bright-faced and bright-limbed.","As for the wording in Abū Dāwūd, “or falls short,” which occurs as an isolated addition in this wording, it is rejected, because wuḍūʾ is valid when the limbs are washed once each or twice each."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (135)، واللفظ له، والنسائي (140)، وابن ماجه (422)."},{"num":1584,"demo":false,"sanad":"","matn":["عَنْ رُبَيِّعَ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ قَالَتْ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ قَالَتْ: فَمَسَحَ رَأْسَهُ وَمَسَحَ مَا أَقْبَلَ مِنْهُ وَمَا أَدْبَرَ وَصُدْغَيْهِ وَأُذُنَيْهِ مَرَّةً وَاحِدَةً."],"takhrij":"حسن: رواه أبو داود (129)، والترمذي (34) كلاهما عن قتيبة بن سعيد، حدّثنا بكر، يعني ابن مضر، ، عن ابن عجلان، عن عبدالله بن محمد بن عقيل، أنّ ربيع بنت معوذ بن عفراء، أخبرته، فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (129) and al-Tirmidhī (34).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh ibn ʿAfrāʾ said: “I saw the Messenger of Allah ﷺ perform wuḍūʾ.” She said: “He wiped his head, wiping its front and back, his temples, and his ears, all in one wiping.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (129)، والترمذي (34)."},{"num":1585,"demo":false,"sanad":"","matn":["عَنْ رُبَيِّعَ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ عِنْدَهَا، فَمَسَحَ الرَّأْسَ كُلَّهُ مِنْ قَرْنِ الشَّعْرِ كُلِّ نَاحِيَةٍ لِمُنْصَبِّ الشَّعْرِ لَا يُحَرِّكُ الشَّعْرَ عَنْ هَيْئَتِهِ."],"takhrij":"حسن: رواه أبو داود (128) عن قتيبة بن سعيد ويزيد بن خالد الهمداني، قالا: حدَّثنا الليث، عن ابن عجلان، عن عبدالله بن محمد بن عقيل، عنها.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (128).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh reported that the Messenger of Allah ﷺ performed wuḍūʾ in her presence and wiped his entire head, beginning from the hairline and wiping each side in the direction in which the hair naturally lay, without disturbing the hair from its normal position."]},"buhuth":{"en":["Her statement, “he wiped the entire head,” is evidence for wiping the whole head."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (128)."},{"num":1586,"demo":false,"sanad":"","matn":["عَنْ الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَسَحَ بِرَأْسِهِ مِنْ فَضْلِ مَاءٍ كَانَ فِي يَدِهِ."],"takhrij":"حسن: رواه أبو داود (130) عن مسدد، ثنا عبدالله بن داود، عن سفيان بن سعيد، عن ابن عقيل، عنها. وإسناده حسن أيضاً.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (130).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh reported that the Prophet ﷺ wiped his head with water remaining upon his hand."]},"buhuth":{"en":["Abū Dāwūd also narrated (131), as did Ibn Mājah (441):","The Prophet ﷺ performed wuḍūʾ and inserted his two fingers into the openings of his ears."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (130)."},{"num":1587,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ الْكِنْدِيِّ قَالَ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَضُوءٍ فَتَوَضَّأَ، فَغَسَلَ كَفَّيْهِ ثَلَاثًا، ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا، وَغَسَلَ وَجْهَهُ ثَلَاثًا، ثُمَّ غَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا، ثُمَّ مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ظَاهِرِهِمَا وَبَاطِنِهِمَا."],"takhrij":"حسن: رواه أبو داود (121) عن الإمام أحمد بن حنبل، وهو في المسند (17188) قال: حدَّثنا أبو المغيرة، قال: حدَّثنا حَرِيز، قال: حدَّثنا عبدالرحمن بن ميسرة الحضرمي، قال: سمعتُ المقدام بن معديكرب فذكر الحديث. وزاد الإمام في المسند وغسل رجليه ثلاثاً ثلاثاً","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (121).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Miqdām ibn Maʿdīkarib al-Kindī said: Water for wuḍūʾ was brought to the Messenger of Allah ﷺ. He performed wuḍūʾ, washing his hands three times and his face three times, then washing his forearms three times each. He then rinsed his mouth and drew water into his nose three times, and then wiped his head and his ears, both their outer and inner portions."]},"buhuth":{"en":["In Aḥmad’s narration, he washed his hands three times and his face three times, then washed his forearms three times each, after which he rinsed his mouth and drew water into his nose three times. He wiped his head and his ears, both their outer and inner portions, and washed his feet three times each.","Narrated by Aḥmad (17188).","The unusual feature in Aḥmad’s wording is that rinsing the mouth and nose occurs after washing the forearms, whereas the well-established order in the authentic narrations places them after washing the hands."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (121)."},{"num":1588,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْأَزْهَرِ الْمُغِيرَةِ بْنِ فَرْوَةَ، وَيَزِيدُ بْنُ أَبِي مَالِكٍ، أَنَّ مُعَاوِيَةَ تَوَضَّأَ لِلنَّاسِ كَمَا رَأَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ، فَلَمَّا بَلَغَ رَأْسَهُ، غَرَفَ غَرْفَةً مِنْ مَاءٍ فَتَلَقَّاهَا بِشِمَالِهِ حَتَّى وَضَعَهَا عَلَى وَسَطِ رَأْسِهِ حَتَّى قَطَرَ الْمَاءُ أَوْ كَادَ يَقْطُرُ، ثُمَّ مَسَحَ مِنْ مُقَدَّمِهِ إِلَى مُؤَخَّرِهِ وَمِنْ مُؤَخَّرِهِ إِلَى مُقَدَّمِهِ."],"takhrij":"حسن: رواه أبو داود (124) عن مُؤَمَّل بن الفضل الحرَّاني، ثنا الوليد بن مسلم، ثنا عبدالله بن العلاء، ثنا أبو الازهر المغيرة بن فروة ويزيد بن أبي مالك فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (124).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū al-Azhar al-Mughīrah ibn Furwah and Yazīd ibn Abī Mālik reported that Muʿāwiyah performed wuḍūʾ before the people in the manner in which he had seen the Messenger of Allah ﷺ perform wuḍūʾ. When he reached his head, he scooped a handful of water and received it with his left hand until he placed it upon the middle of his head, so that the water dripped—or was dripping. He then wiped from the front of his head toward the back and from the back toward the front."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (124)."},{"num":1589,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ مَرَّتَيْنِ مَرَّتَيْنِ."],"takhrij":"حسن: رواه أبو داود (136) والترمذي (43)، كلاهما من حديث زيد بن حُباب، عن عبدالرحمن بن ثابت بن ثوبان قال: حدثني عبدالله بن الفضل، عن عبدالرحمن بن هرمز وهو الاعرج، عن أبي هريرة.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (136) and al-Tirmidhī (43), who said: “This is a ḥasan gharīb hadith.”","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ performed wuḍūʾ, washing each limb twice."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (136)، والترمذي (43)، وقال: «هذا حديث حسن غريب»."},{"num":1590,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، أَنَّهُ قَالَ لِبَنِيهِ: اجْتَمِعُوا فَلَأُرِيَكُمْ كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ، وَكَيْفَ كَانَ يُصَلِّي، فَإِنِّي لَا أَدْرِي مَا قَدْرُ صُحْبَتِي إِيَّاكُمْ . قَالَ: فَجَمَعَ بَنِيهِ وَأَهْلَهُ، وَدَعَا بِوَضُوءٍ، فَمَضْمَضَ وَاسْتَنْشَقَ، وَغَسَلَ وَجْهَهُ ثَلَاثًا، وَغَسَلَ الْيَدَ الْيُمْنَى ثَلَاثًا، وَغَسَلَ يَدَهُ هَذِهِ ثَلَاثًا يَعْنِي الْيُسْرَى، ثُمَّ مَسَحَ رَأْسَهُ وَأُذُنَيْهِ: ظَاهِرَهُمَا وَبَاطِنَهُمَا، وَغَسَلَ هَذِهِ الرِّجْلَ يَعْنِي الْيُمْنَى ثَلَاثًا، وَغَسَلَ هَذِهِ الرِّجْلَ ثَلَاثًا يَعْنِي الْيُسْرَى، قَالَ: هَكَذَا مَا أَلَوْتُ أَنْ أُرِيَكُمْ كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ، ثُمَّ دَخَلَ بَيْتَهُ، فَصَلَّى صَلَاةً لَا نَدْرِي مَا هِيَ، ثُمَّ خَرَجَ، فَأَمَرَ بِالصَّلَاةِ، فَأُقِيمَتْ، فَصَلَّى بِنَا الظُّهْرَ، فَأَحْسِبُ أَنِّي سَمِعْتُ مِنْهُ آيَاتٍ مِنْ يس، ثُمَّ صَلَّى الْعَصْرَ، ثُمَّ صَلَّى بِنَا الْمَغْرِبَ، ثُمَّ صَلَّى بِنَا الْعِشَاءَ، وَقَالَ: مَا أَلَوْتُ أَنْ أُرِيَكُمْ كَيْفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ، وَكَيْفَ كَانَ يُصَلِّي."],"takhrij":"حسن: أخرجه الإمام أحمد (18537) قال: حدَّثنا إسماعيل، حدَّثنا سعيد الجُرَيري، عن أبي عائذ سيفٍ السعدي – وأثنى عليه خيراً – عن يزيد بن البراء بن عازب – وكان أميراً بعُمان، وكان كخير الأُمراء، ، قال: قال أبي: فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Imām Aḥmad (18537).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib said to his sons: “Gather together so that I may show you how the Messenger of Allah ﷺ used to perform wuḍūʾ and how he used to pray, for I do not know how much longer I will remain in your company.” He gathered his sons and family and called for water for wuḍūʾ. He rinsed his mouth and expelled water from his nose, washed his face three times, washed his right arm three times and his left arm three times, then wiped his head and his ears, both their outer and inner parts. He washed his right foot three times and his left foot three times. He said: “This is the utmost I can do to show you how the Messenger of Allah ﷺ used to perform wuḍūʾ.” He then entered his house and prayed a prayer whose identity they did not know. Afterward he came out and ordered that the prayer be established. He led them in Ẓuhr, and al-Barāʾ said: “I think I heard him reciting verses from Sūrah Yā-Sīn.” He then prayed ʿAṣr, then led them in Maghrib, and then led them in ʿIshāʾ. He said: “This is the utmost I can do to show you how the Messenger of Allah ﷺ used to perform wuḍūʾ and how he used to pray.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (18537)."},{"num":1591,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ أَنَّهُ سُئِلَ: هَلْ أَمَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ غَيْرَ أَبِي بَكْرٍ رَضِيَ اللَّهُ تَعَالَى عَنْهُ ؟ فَقَالَ: نَعَمْ كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَلَمَّا كَانَ مِنَ السَّحَرِ، ضَرَبَ عُنُقَ رَاحِلَتِي، فَظَنَنْتُ أَنَّ لَهُ حَاجَةً، فَعَدَلْتُ مَعَهُ، فَانْطَلَقْنَا حَتَّى بَرَزْنَا عَنِ النَّاسِ، فَنَزَلَ عَنْ رَاحِلَته، ثُمَّ انْطَلَقَ فَتَغَيَّبَ عَنِّي حَتَّى مَا أَرَاهُ، فَمَكَثَ طَوِيلًا، ثُمَّ جَاءَ فَقَالَ: حَاجَتَكَ يَا مُغِيرَةُ ؟ قُلْتُ: مَا لِي حَاجَةٌ . فَقَال: هَلْ مَعَكَ مَاءٌ ؟ فَقُلْتُ: نَعَمْ، فَقُمْتُ إِلَى قِرْبَةٍ أَوْ إِلَى سَطِيحَةٍ مُعَلَّقَةٍ فِي آخِرَةِ الرَّحْلِ، فَأَتَيْتُهُ بِمَاءٍ، فَصَبَبْتُ عَلَيْهِ، فَغَسَلَ يَدَيْهِ، فَأَحْسَنَ غَسْلَهُمَا، قَالَ: وَأَشُكُّ أَقَالَ: دَلَّكَهُمَا بِتُرَابٍ، أَمْ لَا، ثُمَّ غَسَلَ وَجْهَهُ، ثُمَّ ذَهَبَ يَحْسِرُ عَنْ يَدَيْهِ وَعَلَيْهِ جُبَّةٌ شَامِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ، فَضَاقَتْ، فَأَخْرَجَ يَدَيْهِ مِنْ تَحْتِهَا إِخْرَاجًا، فَغَسَلَ وَجْهَهُ وَيَدَيْهِ، قَالَ: فَيَجِيءُ فِي الْحَدِيثِ غَسْلُ الْوَجْهِ مَرَّتَيْن ؟ قَالَ: لَا أَدْرِي أَهَكَذَا كَانَ أَمْ لَا، ثُمَّ مَسَحَ بِنَاصِيَتِهِ، وَمَسَحَ عَلَى الْعِمَامَةِ، وَمَسَحَ عَلَى الْخُفَّيْنِ، وَرَكِبْنَا فَأَدْرَكْنَا النَّاسَ وَقَدْ أُقِيمَتْ الصَّلَاةُ، فَتَقَدَّمَهُمْ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ، وَقَدْ صَلَّى بِهِمْ رَكْعَةً وَهُمْ فِي الثَّانِيَةِ، فَذَهَبْتُ أُوذِنُهُ فَنَهَانِي، فَصَلَّيْنَا الرَّكْعَةَ الَّتِي أَدْرَكْنَا، وَقَضَيْنَا الرَّكْعَةَ الَّتِي سُبِقْنَا."],"takhrij":"صحيح: رواه الإمام أحمد (18134) قال: حدَّثنا إسماعيل، أخبرنا أيوب، عن محمد، عن عمرو بن وهب الثقفي قال: كنَّا مع المغيرة بن شعبة فسئل فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Imām Aḥmad (18134).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah was asked: “Did anyone from this Ummah ever lead the Prophet ﷺ in prayer besides Abū Bakr, may Allah be pleased with him?” He replied: “Yes.” We were with the Prophet ﷺ on a journey. In the latter part of the night, he struck the neck of my riding animal, and I thought that he had some need, so I turned aside with him. We continued until we were away from the people. He dismounted and went off until he was hidden from my sight. He remained away for a long time, then returned and said: “Do you have any need, O Mughīrah?” I replied: “I have no need.” He asked: “Do you have water?” I said: “Yes.” I went to a waterskin—or another water container—hanging at the rear of the saddle and brought him water. I poured it for him, and he washed his hands thoroughly. The narrator said: “I am uncertain whether he said that he rubbed them with earth or not.” He then washed his face. He tried to uncover his arms while wearing a Syrian cloak with tight sleeves, but the sleeves were too narrow, so he brought his arms out from beneath the cloak and washed his arms. The narrator expressed uncertainty concerning a wording that might imply repetition of washing the face. He then wiped his forelock, wiped over his turban, and wiped over his leather socks. We mounted and returned to the people after the prayer had already been established. ʿAbd al-Raḥmān ibn ʿAwf had been put forward to lead them and had already completed one rakʿah and was in the second. We joined the row behind him, prayed the rakʿah we caught, and then completed the rakʿah we had missed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (18134)."},{"num":1592,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ، أَنَّهُ جَمَعَ أَصْحَابَهُ فَقَالَ: هَلُمَّ أُصَلِّي صَلَاةَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَكَانَ رَجُلًا مِنَ الْأَشْعَرِيِّينَ، قَالَ: فَدَعَا بِجَفْنَةٍ مِنْ مَاءٍ، فَغَسَلَ يَدَيْهِ ثَلَاثًا، وَمَضْمَضَ وَاسْتَنْشَقَ وَغَسَلَ وَجْهَهُ ثَلَاثًا، وَذِرَاعَيْهِ ثَلَاثًا، وَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ، وَغَسَلَ قَدَمَيْهِ، قَالَ: فَصَلَّى الظُّهْرَ , فَقَرَأَ فِيهَا بِفَاتِحَةِ الْكِتَابِ، وَكَبَّرَ ثِنْتَيْنِ وَعِشْرِينَ تَكْبِيرَةً."],"takhrij":"حسن: رواه أحمد (22893) والطبراني في الكبير (3412، 3414) كلاهما من طريق قتادة، عن شهر بن حوشب، عن عبدالرحمن بن غَنْم، عن أبي مالك الأشعري فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (22893), al-Ṭabarānī (3412, 3414), and Ibn Mājah (417).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Mālik al-Ashʿarī gathered his companions and said: “Come, and I will pray for you the prayer of your Prophet ﷺ.” He was a man from the Ashʿarīs. He called for a large bowl of water, washed his hands three times, rinsed his mouth and drew water into his nose, washed his face three times, washed his forearms three times, wiped his head and ears, and washed his feet. He then prayed Ẓuhr, recited Sūrat al-Fātiḥah in it, and pronounced twenty-two takbīrs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22893)، والطبراني (3412، 3414)، وابن ماجه (417)."},{"num":1593,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَمَضْمَضَ ثَلَاثًا، وَاسْتَنْشَقَ ثَلَاثًا، وَغَسَلَ وَجْهَهُ ثَلَاثًا، وَغَسَلَ يَدَيْهِ ثَلَاثًا، وَمَسَحَ بِرَأْسِهِ، وَوَضَّأَ قَدَمَيْه."],"takhrij":"حسن: رواه الإمام أحمد (8577) والطبراني في الأوسط (5912) –مجمع البحرين ،كلاهما عن همام، عن عامر – يعني الأحول، عن عطاء، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Imām Aḥmad (8577) and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (5912), as cited in Majmaʿ al-Baḥrayn.","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ performed wuḍūʾ. He rinsed his mouth three times, drew water into his nose three times, washed his face three times, washed his arms three times, wiped his head, and washed his feet."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (8577)، والطبراني في الأوسط (5912) — مجمع البحرين."},{"num":1594,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ ثَلَاثًا ثَلَاثًا."],"takhrij":"حسن: رواه ابن ماجه (415) مقروناً بأبي هريرة كما سبق عن أبي كريب، حدَّثنا خالد بن حيَّان، عن سالم أبي المهاجر، عن ميمون بن مهران، عن عائشة وأبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Mājah (415).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿĀʾishah reported that the Prophet ﷺ performed wuḍūʾ, washing each limb three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (415)."},{"num":1595,"demo":false,"sanad":"","matn":["عَنْ أَبِي رَافِعٍ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَغَسَلَ وَجْهَهُ ثَلَاثًا، وَغَسَلَ يَدَيْهِ ثَلَاثًا، وَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ، وَغَسَلَ رِجْلَيْهِ ثَلَاثًا، وَرَأَيْتُهُ مَرَّةً أُخْرَى تَوَضَّأَ مَرَّةً مَرَّةً."],"takhrij":"حسن: رواه الطبراني في الأوسط (907) – مجمع البحرين (404)، والطحاوي في شرح المعاني (1/30) كلاهما من طريق سعيد بن سليمان الواسطي، عن عبد العزيز بن محمد الدراوردي، حدثنا عمرو بن عمرو، عن عبد الله بن عبيد الله بن أبي رافع، عن أبيه، عن أبي رافع قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (404), and al-Ṭaḥāwī in Sharḥ Maʿānī al-Āthār (1/30).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Rāfiʿ said: I saw the Messenger of Allah ﷺ performing wuḍūʾ. He washed his face three times, washed his arms three times, wiped his head and ears, and washed his feet. On another occasion, I saw him perform wuḍūʾ washing each limb once."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط — مجمع البحرين (404)، والطحاوي في شرح معاني الآثار (1/30)."},{"num":1596,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُبَيْرٍ الْكِنْدِيَّ أَنَّهُ قَدِمَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَضُوءٍ وَقَالَ: تَوَضَّأْ يَا أَبَا جُبَيْرٍ، فَبَدَأَ بِفِيهِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لا تَبْدَأْ بِفِيكَ، فَإِنَّ الْكَافِرَ يَبْدَأُ بِفِيهِ، ثُمَّ دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَضُوءٍ، فَغَسَلَ يَدَيْهِ حَتَّى أَنْقَاهُمَا، ثُمَّ تَمَضْمَضَ وَاسْتَنْثَرَ، ثُمَّ غَسَلَ وَجْهَهُ ثَلاثًا، ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى إِلَى الْمِرْفَقِ ثَلاثًا، ثُمَّ غَسَلَ يَدَهُ الْيُسْرَى إِلَى الْمِرْفَقِ ثَلاثًا، ثُمَّ مَسَحَ بِرَأْسِهِ وَغَسَلَ رِجْلَيْهِ."],"takhrij":"حسن: رواه ابن حبان (1089) قال: أخبرنا ابن قتيبة، قال: حدَّثنا حرملة بن يحيى، قال: حدَّثنا ابن وهب، قال: حدثني معاوية بن صالح، عن عبدالرحمن بن جبير بن نفير، عن أبيه أن أبا جبير فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في صفة وضوء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Ḥibbān (1089) and al-Bayhaqī (1/46).","chapter_en":"What Has Been Reported Concerning the Description of the Prophet’s ﷺ Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Jubayr al-Kindī reported that he came to the Messenger of Allah ﷺ. The Messenger of Allah ﷺ had water for wuḍūʾ brought and said: “Perform wuḍūʾ, O Abū Jubayr.” He began with his mouth, so the Messenger of Allah ﷺ said: “Do not begin with your mouth, for the disbeliever begins with his mouth.” Then the Messenger of Allah ﷺ called for water for wuḍūʾ. He washed his hands until they were thoroughly clean, rinsed his mouth and expelled water from his nose, washed his face three times, washed his right arm to the elbow three times, washed his left arm to the elbow three times, then wiped his head and washed his feet."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (1089)، والبيهقي (211)."},{"num":1597,"demo":false,"sanad":"","matn":["عَنِ النَّزَّالِ بْنِ سَبْرَةَ قال: رَأَيْتُ عَلِيًّا رَضِيَ اللَّهُ عَنْهُ صَلَّى الظُّهْرَ ثُمَّ قَعَدَ لِحَوَائِجِ النَّاسِ، فَلَمَّا حَضَرَتِ الْعَصْرُ، أُتِيَ بِتَوْرٍ مِنْ مَاءٍ فَأَخَذَ مِنْهُ كَفًّا فَمَسَحَ بِهِ وَجْهَهُ وَذِرَاعَيْهِ وَرَأْسَهُ وَرِجْلَيْهِ، ثُمَّ أَخَذَ فَضْلَهُ فَشَرِبَ قَائِمًا. وَقَالَ: إِنَّ نَاسًا يَكْرَهُونَ هَذَا، وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ، وَهَذَا وُضُوءُ مَنْ لَمْ يُحْدِثْ."],"takhrij":"صحيح: رواه النسائي (130) عن عمرو بن يزيد قال: حدَّثنا بهز بن أسد، قال: حدَّثنا شعبة، عن عبد الملك بن ميسرة، قال: سمعتُ النزال بن سبرة فذكر مثله.","grade":"صحيح","chapter_ar":"باب صفة وضوء النبي ﷺ من غير حدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (130).","chapter_en":"The Description of the Prophet’s ﷺ Wuḍūʾ When He Had Not Broken His Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Al-Nazzāl ibn Sabrah said: I saw ʿAlī, may Allah be pleased with him, pray Ẓuhr and then sit to attend to the needs of the people. When the time for ʿAṣr came, a basin of water was brought to him. He took a handful of water and wiped his face, forearms, head, and feet. He then took the remaining water and drank it while standing. He said: “People dislike this, but I saw the Messenger of Allah ﷺ do it. This is the wuḍūʾ of one who has not broken his wuḍūʾ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (130)."},{"num":1598,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قال: تَوَضَّأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَغَرَفَ غَرْفَةً فَمَضْمَضَ وَاسْتَنْشَقَ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ وَجْهَهُ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ يَدَهُ الْيُمْنَى، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ يَدَهُ الْيُسْرَى، ثُمَّ مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ بَاطِنِهِمَا بِالسَّبَّاحَتَيْنِ وَظَاهِرِهِمَا بِإِبْهَامَيْهِ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ رِجْلَهُ الْيُمْنَى، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ رِجْلَهُ الْيُسْرَى."],"takhrij":"حسن: رواه النسائي الصغرى (102) واللفظ له، والترمذي (36)، وابن ماجه (439)، وابن خزيمة (148)، وابن حبان (1078) كلهم من حديث عبدالله بن إدريس، عن محمد بن عجلان، عن زيد بن أسلم، عن عطاء بن يسار، عن ابن عباس.","grade":"حسن","chapter_ar":"باب ما جاء في مسح الأذنين ظاهرهما وباطنهما","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Nasāʾī (102), whose wording this is, al-Tirmidhī (36), Ibn Mājah (439), Ibn Khuzaymah (148), and Ibn Ḥibbān (1078).","chapter_en":"What Has Been Reported Concerning Wiping the Outer and Inner Parts of the Ears","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿAbbās said: The Messenger of Allah ﷺ performed wuḍūʾ. He scooped one handful of water and rinsed his mouth and drew water into his nose. He then scooped another handful and washed his face, another handful and washed his right arm, and another handful and washed his left arm. He then wiped his head and ears, wiping the inner parts of the ears with his index fingers and their outer parts with his thumbs. He then scooped another handful and washed his right foot, and another handful and washed his left foot."]},"buhuth":{"en":["Al-Tirmidhī’s wording is:","“The Messenger of Allah ﷺ wiped his head and his ears, their outer and inner parts.”","Ibn Mājah’s wording is:","“The Messenger of Allah ﷺ wiped the inner parts of his ears with his index fingers, moved his thumbs to the outer parts of his ears, and wiped both their outer and inner parts.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (102)، واللفظ له، والترمذي (36)، وابن ماجه (439)، وابن خزيمة (148)، وابن حبان (1078)."},{"num":1599,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُخَلِّلُ لِحْيَتَهُ."],"takhrij":"حسن: رواه الترمذي (31) وابن ماجه (430) كلاهما من حديث عبد الرزاق، عن إسرائيل، عن عامر بن شقيق، عن أبي وائل، عن عثمان، فذكر مثله.","grade":"حسن","chapter_ar":"باب استحباب تخليل اللحية في الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Tirmidhī (31) and Ibn Mājah (430). Al-Tirmidhī said: “This is a ḥasan ṣaḥīḥ hadith.”","chapter_en":"The Recommendation of Running Water through the Beard During Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿUthmān ibn ʿAffān reported that the Prophet ﷺ used to run water through his beard."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (31)، وابن ماجه (430). وقال الترمذي: «هذا حديث حسن صحيح»."}]);